;(()=>{const p={"changes":{"beetle":{"definition":"An insect of the order Coleoptera, typically with hard forewings (elytra) that cover and protect the hind wings.","synonyms":["coleopteran"],"example":{"word":"beetle","text":"The ladybird is a beetle that feeds on aphids."},"exampleSynonym":{"word":"coleopteran","text":"The ladybird is a coleopteran that feeds on aphids."},"translation":"coleoptero"},"choleric":{"definition":"Formal: easily made angry or bad-tempered; also, expressing anger. The historical sense relates to the former theory of bodily humours.","synonyms":["irascible","short-tempered"],"example":{"word":"choleric","text":"The choleric manager became irritated by every delay."},"exampleSynonym":{"word":"irascible","text":"The irascible manager became irritated by every delay."},"translation":"colerico"},"anger-2":{"word":"anger","definition":"To make someone feel angry; to provoke or enrage.","synonyms":["enrage","infuriate"],"example":{"word":"anger","text":"The unexplained delay began to anger even the most patient customers."},"exampleSynonym":{"word":"enrage","text":"The unexplained delay began to enrage even the most patient customers."},"translation":"colerizar"},"cholesterin":{"definition":"An old name for cholesterol, a lipid found in animal tissues and blood.","synonyms":["cholesterol"],"example":{"word":"cholesterin","text":"Older medical texts sometimes use cholesterin for cholesterol."},"exampleSynonym":{"word":"cholesterol","text":"Modern medical texts use cholesterol as the standard name."},"translation":"colesterina"},"tail-swipe":{"word":"tail swipe","definition":"A forceful blow or sweeping movement made with an animal’s tail.","synonyms":["tail slap"],"example":{"word":"tail swipe","text":"The fish gave a tail swipe and splashed the people beside the pier."},"exampleSynonym":{"word":"tail slap","text":"The fish gave a tail slap and splashed the people beside the pier."},"translation":"coletazo"},"scrunchie":{"definition":"A fabric-covered elastic band used to hold a ponytail or other gathered hairstyle.","synonyms":["fabric hair tie"],"example":{"word":"scrunchie","text":"She tied her hair back with a blue fabric scrunchie."},"exampleSynonym":{"word":"fabric hair tie","text":"She tied her hair back with a blue fabric hair tie."},"translation":"coletero"},"tagline":{"definition":"A short, memorable phrase used to identify or promote a product, organization, or campaign.","synonyms":["slogan","catchphrase"],"example":{"word":"tagline","text":"The company chose a short tagline for its new campaign."},"exampleSynonym":{"word":"slogan","text":"The company chose a short slogan for its new campaign."},"translation":null},"coleto":{"translation":null},"hanging-2":{"word":"wall hanging","definition":"A decorative textile or other object displayed by hanging it on a wall.","synonyms":["wall tapestry","wall decoration"],"example":{"word":"wall hanging","text":"A woven wall hanging decorated the entrance hall."},"exampleSynonym":{"word":"wall tapestry","text":"A woven wall tapestry decorated the entrance hall."},"translation":"colgadura"},"colic":{"definition":"Severe, often intermittent or cramping abdominal pain; the term is also used for prolonged crying in an otherwise healthy infant.","synonyms":["abdominal colic"],"example":{"word":"colic","text":"The doctor asked when the abdominal colic had started."},"exampleSynonym":{"word":"abdominal colic","text":"The doctor asked when the abdominal colic had started."},"translation":"colica"},"privacy-settings":{"definition":"Controls in an app, account, or device that let a user choose how personal information is collected, used, or shared.","synonyms":["privacy options"],"example":{"word":"privacy settings","text":"She changed her privacy settings so only friends could see her posts."},"exampleSynonym":{"word":"privacy options","text":"She changed her privacy options so only friends could see her posts."}},"pop-up-ad":{"definition":"An advertisement that appears suddenly in a separate window or over the content of a web page or app.","synonyms":["pop-up advert"],"example":{"word":"pop-up ad","text":"He closed the pop-up ad before reading the news."},"exampleSynonym":{"word":"pop-up advert","text":"He closed the pop-up advert before reading the news."}},"carbon-monoxide-detector":{"definition":"A device that detects carbon monoxide in the air and sounds an alarm when its concentration reaches a dangerous level.","synonyms":["CO detector","carbon monoxide alarm"],"example":{"word":"carbon monoxide detector","text":"She tested the carbon monoxide detector near the boiler."},"exampleSynonym":{"word":"CO detector","text":"She tested the CO detector near the boiler."}},"fire-blanket":{"definition":"A fire-resistant sheet used to smother a small fire by covering it and cutting off its supply of oxygen.","synonyms":["fire smothering blanket"],"example":{"word":"fire blanket","text":"He covered the small pan fire with a fire blanket."},"exampleSynonym":{"word":"fire smothering blanket","text":"He covered the small pan fire with a fire smothering blanket."}},"fire-door":{"definition":"A door designed and rated to resist the spread of fire and smoke for a specified period when properly closed.","synonyms":["fire-resisting door"],"example":{"word":"fire door","text":"The fire door closed automatically behind the evacuees."},"exampleSynonym":{"word":"fire-resisting door","text":"The fire-resisting door closed automatically behind the evacuees."}},"emergency-light":{"definition":"A battery-powered light that switches on when the normal power supply fails, helping people see or leave the area.","synonyms":["backup light"],"example":{"word":"emergency light","text":"The emergency light came on when the building lost power."},"exampleSynonym":{"word":"backup light","text":"The backup light came on when the building lost power."}},"safety-harness":{"definition":"A set of straps worn around the body and attached to an anchorage or safety system to restrain a fall or limit its consequences.","synonyms":["fall-arrest harness","fall-protection harness"],"example":{"word":"safety harness","text":"The worker connected the safety harness to an approved anchor before climbing."},"exampleSynonym":{"word":"fall-arrest harness","text":"The worker connected the fall-arrest harness to an approved anchor before climbing."},"translation":"arnes-de-seguridad"},"hard-hat":{"definition":"A rigid protective helmet worn to reduce the risk of head injury from impact, falling or flying objects, or electrical hazards.","synonyms":["safety helmet","protective helmet"],"example":{"word":"hard hat","text":"Workers wore hard hats where tools could fall from above."},"exampleSynonym":{"word":"safety helmet","text":"Workers wore safety helmets where tools could fall from above."}},"door-chain":{"definition":"A short security chain fitted to a door that lets it open a little while limiting how far it can be opened from outside.","synonyms":["security chain"],"example":{"word":"door chain","text":"She fastened the door chain before opening the door to a stranger."},"exampleSynonym":{"word":"security chain","text":"She fastened the security chain before opening the door to a stranger."},"translation":"cadena-de-seguridad"},"peephole":{"definition":"A small opening, usually fitted with a lens, that lets someone inside a building see who is outside a door.","synonyms":["door viewer"],"example":{"word":"peephole","text":"He looked through the peephole before opening the door."},"exampleSynonym":{"word":"door viewer","text":"He looked through the door viewer before opening the door."}}},"removals":["coleto"]};for(const[id,fields]of Object.entries(p.changes)){const e=DICCIONARIOS.en.find(x=>x.id===id);if(!e)throw Error('Missing '+id);for(const[k,v]of Object.entries(fields)){if(k==='translation'){if(v)e.translation={es:v};else delete e.translation;}else e[k]=v;}}DICCIONARIOS.en=DICCIONARIOS.en.filter(x=>!p.removals.includes(x.id));})();

