// Corrections from the entry-by-entry review of Spanish and English batch 975.
(function () {
  const updates = {
    es: {
      estrabismo: { definition: 'Desalineación de los ojos: no apuntan al mismo objeto al mismo tiempo. Puede ser constante o intermitente y afectar a uno o ambos ojos; sus causas y tratamiento dependen de cada caso.', synonyms: ['desviación ocular', 'desalineación de los ojos'], example: { word: 'estrabismo', text: 'La evaluación oftalmológica determinó el tipo de estrabismo y el tratamiento adecuado.' }, exampleSynonym: { word: 'desviación ocular', text: 'La evaluación oftalmológica determinó el tipo de desviación ocular y el tratamiento adecuado.' } },
      'evasion-fiscal': { definition: 'Conducta ilegal e intencional destinada a reducir o evitar el pago de impuestos debidos, por ejemplo ocultando ingresos o declarando gastos o deducciones falsos. Se distingue de la planificación fiscal legal; el incumplimiento no intencional no constituye necesariamente evasión.', synonyms: ['fraude fiscal', 'elusión ilegal del pago de impuestos', 'ocultación fraudulenta de obligaciones tributarias'], example: { word: 'evasión fiscal', text: 'La investigación atribuyó a la empresa una evasión fiscal basada en ingresos ocultos.' }, exampleSynonym: { word: 'fraude fiscal', text: 'La investigación atribuyó a la empresa un fraude fiscal basado en ingresos ocultos.' } },
      excarcelar: { definition: 'Poner en libertad a una persona que se encuentra en prisión o bajo custodia penitenciaria. La excarcelación puede obedecer, entre otros motivos, al cumplimiento de la pena, a una resolución judicial o a la concesión de libertad provisional.', synonyms: ['poner en libertad', 'liberar de prisión', 'dejar en libertad a una persona presa'], example: { word: 'excarcelar', text: 'El tribunal ordenó excarcelar al acusado tras revisar las condiciones de su libertad provisional.' }, exampleSynonym: { word: 'poner en libertad', text: 'El tribunal ordenó poner en libertad al acusado tras revisar las condiciones de su libertad provisional.' } },
      exclusion: { definition: 'Acción o efecto de dejar a alguien o algo fuera de un grupo, actividad, proceso o conjunto. Puede referirse a una exclusión social, jurídica, económica u otra, según el contexto.', synonyms: ['acto de excluir', 'marginación (en ciertos contextos)', 'apartamiento'], example: { word: 'exclusión', text: 'La norma estableció criterios claros para evitar la exclusión de solicitantes elegibles.' }, exampleSynonym: { word: 'acto de excluir', text: 'La norma estableció criterios claros para evitar el acto de excluir a solicitantes elegibles.' } },
      exculpar: { definition: 'Descartar o reducir la responsabilidad o culpa atribuida a alguien, especialmente mediante pruebas o argumentos que muestran que no cometió el hecho o que no es responsable de él. No implica necesariamente una absolución formal.', synonyms: ['exonerar de culpa', 'descargar de responsabilidad', 'desvincular de una acusación'], example: { word: 'exculpar', text: 'Las imágenes de seguridad ayudaron a exculpar al trabajador de la acusación.' }, exampleSynonym: { word: 'exonerar de culpa', text: 'Las imágenes de seguridad ayudaron a exonerar de culpa al trabajador.' } },
      expedientar: { definition: 'Abrir o tramitar un expediente administrativo o disciplinario contra una persona o entidad. El uso y el procedimiento concreto dependen de la jurisdicción y del ámbito.', synonyms: ['abrir expediente', 'incoar un expediente', 'iniciar un procedimiento administrativo'], example: { word: 'expedientar', text: 'La autoridad decidió expedientar a la empresa por posibles incumplimientos.' }, exampleSynonym: { word: 'incoar un expediente', text: 'La autoridad decidió incoar un expediente a la empresa por posibles incumplimientos.' } },
      expropiar: { definition: 'Adquirir una autoridad pública, mediante el procedimiento legal aplicable y por una causa de interés público, un bien o derecho de propiedad privada. Las condiciones y la compensación dependen de la legislación correspondiente.', synonyms: ['privar legalmente de una propiedad por causa pública', 'adquirir forzosamente un bien privado', 'expropiación forzosa (forma nominal)'], example: { word: 'expropiar', text: 'El gobierno inició el procedimiento para expropiar los terrenos necesarios para la obra pública.' }, exampleSynonym: { word: 'adquirir forzosamente un bien privado', text: 'El gobierno inició el procedimiento para adquirir forzosamente los terrenos necesarios para la obra pública.' } },
      extraditar: { definition: 'Entregar una persona a otro Estado, previa solicitud y conforme a las normas y acuerdos aplicables, para que sea juzgada o cumpla una condena. La extradición puede estar sujeta a requisitos y límites legales.', synonyms: ['entregar a otro Estado para su enjuiciamiento', 'conceder la extradición', 'entregar para cumplir una condena en otro país'], example: { word: 'extraditar', text: 'El tribunal autorizó extraditar al acusado después de examinar la solicitud y las garantías aplicables.' }, exampleSynonym: { word: 'conceder la extradición', text: 'El tribunal autorizó conceder la extradición del acusado después de examinar la solicitud y las garantías aplicables.' } },
      faringitis: { definition: 'Inflamación de la faringe, conducto situado detrás de la nariz y la boca que comunica con la laringe y el esófago. Puede tener distintas causas y provocar dolor o irritación de garganta; los síntomas varían.', synonyms: ['inflamación de la faringe', 'irritación faríngea'], example: { word: 'faringitis', text: 'El médico evaluó la causa probable de la faringitis y los síntomas de la paciente.' }, exampleSynonym: { word: 'inflamación de la faringe', text: 'El médico evaluó la causa probable de la inflamación de la faringe y los síntomas de la paciente.' } },
      fedatario: { definition: 'Persona u órgano facultado por la ley para dar fe pública o certificar la autenticidad de determinados actos, hechos o documentos. Las funciones concretas dependen de la jurisdicción; puede tratarse, por ejemplo, de un notario u otra autoridad habilitada.', synonyms: ['persona autorizada para dar fe pública', 'funcionario certificador', 'notario (en algunos contextos)'], example: { word: 'fedatario', text: 'El fedatario certificó la identidad de los comparecientes y la firma del documento.' }, exampleSynonym: { word: 'persona autorizada para dar fe pública', text: 'La persona autorizada para dar fe pública certificó la identidad de los comparecientes y la firma del documento.' } }
    },
    en: {
      'fiscal-deficit': { definition: 'A government’s expenditure exceeding its revenue over a specified period, measured under a stated accounting basis. Revenue may include tax and non-tax receipts, and the scope may cover different levels or parts of government.', synonyms: ['government budget deficit', 'public-sector deficit (depending on scope)', 'excess of government expenditure over revenue'], example: { word: 'fiscal deficit', text: 'The finance ministry reported a fiscal deficit for the year after comparing expenditure with total revenue.' }, exampleSynonym: { word: 'government budget deficit', text: 'The finance ministry reported a government budget deficit for the year after comparing expenditure with total revenue.' } },
      deflation: { definition: 'A sustained decline in the general level of prices across an economy, rather than a fall in the price of only one item. It increases the purchasing power of money and can be associated with economic weakness.', synonyms: ['sustained fall in the general price level', 'negative inflation', 'general price decline'], example: { word: 'deflation', text: 'Several consecutive years of deflation reduced the general price level across the economy.' }, exampleSynonym: { word: 'sustained fall in the general price level', text: 'Several consecutive years of a sustained fall in the general price level affected businesses across the economy.' } },
      'delirium-tremens': { definition: 'A severe, potentially life-threatening form of alcohol withdrawal involving abrupt, marked changes in mental state and nervous-system activity. It can occur after reducing or stopping prolonged heavy alcohol use; it is more than ordinary shaking or confusion.', synonyms: ['severe alcohol-withdrawal delirium', 'acute delirium associated with alcohol withdrawal', 'severe withdrawal-related confusion and agitation'], example: { word: 'delirium tremens', text: 'The clinician recognised delirium tremens as a severe complication of alcohol withdrawal.' }, exampleSynonym: { word: 'severe alcohol-withdrawal delirium', text: 'The clinician recognised severe alcohol-withdrawal delirium as a serious complication.' } },
      repeal: { definition: 'To formally revoke or remove the legal force of a law or provision through an authority and procedure empowered to do so, commonly by a later statute. It is distinct from a court’s annulment of a measure, whose effects depend on the legal system.', synonyms: ['revoke a law', 'rescind a statute', 'formally abolish a legal provision'], example: { word: 'repeal', text: 'Parliament voted to repeal the provision through a new act.' }, exampleSynonym: { word: 'revoke a law', text: 'Parliament voted to revoke the law through a new act.' } },
      'syndicated-loan': { definition: 'A loan supplied by two or more lenders to one borrower under a coordinated arrangement, often organised by a lead arranger. The lenders share the financing and associated exposure; the loan need not involve only banks or a company.', synonyms: ['loan from a group of lenders', 'multi-lender loan', 'jointly arranged loan'], example: { word: 'syndicated loan', text: 'Several lenders provided a syndicated loan under a common set of terms.' }, exampleSynonym: { word: 'multi-lender loan', text: 'Several lenders provided a multi-lender loan under a common set of terms.' } },
      'lifting-of-attachment': { definition: 'The formal cancellation or removal of a legal attachment, seizure, or comparable restraint placed on property or assets. Its effect, including whether and when the asset becomes available again, depends on the order and applicable law.', synonyms: ['removal of an attachment', 'release of attached property', 'discharge of a seizure order'], example: { word: 'lifting of attachment', text: 'The court ordered the lifting of attachment after the creditor’s claim was resolved.' }, exampleSynonym: { word: 'removal of an attachment', text: 'The court ordered the removal of the attachment after the creditor’s claim was resolved.' } },
      'dismissal-of-claim': { definition: 'A court’s disposition ending a claim without granting the relief sought. Depending on the grounds and jurisdiction, dismissal may be with prejudice, preventing the same claim from being brought again, or without prejudice, allowing it to be refiled.', synonyms: ['court rejection of a claim', 'termination of a claim', 'dismissal of an action'], example: { word: 'dismissal of claim', text: 'The judge ordered dismissal of the claim without prejudice, allowing it to be refiled.' }, exampleSynonym: { word: 'termination of a claim', text: 'The judge ordered termination of the claim without prejudice, allowing it to be refiled.' } },
      disinheritance: { definition: 'The act of excluding a person who might otherwise inherit from receiving an inheritance, usually through a will or other legally recognised instrument. The grounds, formalities, limits, and ability to contest the exclusion vary by jurisdiction.', synonyms: ['exclusion from an inheritance', 'disinheriting an heir', 'denial of inheritance (context-dependent)'], example: { word: 'disinheritance', text: 'The will’s disinheritance clause was challenged under the succession law.' }, exampleSynonym: { word: 'exclusion from an inheritance', text: 'The will’s exclusion of the heir from an inheritance was challenged under the succession law.' } },
      disinformation: { definition: 'False or misleading information deliberately created or spread to deceive, manipulate, or cause harm. It differs from misinformation, which is shared without an intent to deceive; propaganda is not necessarily false.', synonyms: ['deliberate deception with false information', 'intentionally misleading information', 'deliberately spread falsehoods'], example: { word: 'disinformation', text: 'The report traced the disinformation campaign to accounts that deliberately circulated fabricated claims.' }, exampleSynonym: { word: 'intentionally misleading information', text: 'The report traced the campaign of intentionally misleading information to accounts that circulated fabricated claims.' } },
      offshoring: { definition: 'Moving a business activity, process, or production operation to another country. A company may do this to reduce costs or for other reasons, and it may move the work to its own overseas operation or to an external provider; offshoring does not itself mean outsourcing.', synonyms: ['relocation of business activity abroad', 'moving production overseas', 'transfer of operations to another country'], example: { word: 'offshoring', text: 'The company considered offshoring part of its production while keeping ownership of the overseas facility.' }, exampleSynonym: { word: 'relocation of business activity abroad', text: 'The company considered relocation of part of its production abroad while keeping ownership of the overseas facility.' } }
    }
  };
  for (const [lang, rows] of Object.entries(updates)) for (const [id, fields] of Object.entries(rows)) {
    const row = window.DICCIONARIOS[lang].find(item => item.id === id);
    if (!row) throw new Error(`Missing ${lang}:${id}`);
    Object.assign(row, fields);
  }
})();

// Corrections from the entry-by-entry review of Spanish and English batch 976.
(function () {
  const updates = {
    es: {
      exhumar: { definition: 'Desenterrar un cadáver o restos humanos después de su sepultura. La exhumación puede realizarse, por ejemplo, para una investigación, una identificación o un traslado, conforme a las autorizaciones y normas aplicables.', synonyms: ['desenterrar un cadáver', 'sacar restos humanos de su sepultura'], example: { word: 'exhumar', text: 'La autoridad autorizó exhumar los restos para realizar nuevos análisis.' }, exampleSynonym: { word: 'desenterrar un cadáver', text: 'La autoridad autorizó desenterrar el cadáver para realizar nuevos análisis.' } },
      feminicidio: { definition: 'Asesinato intencional de una mujer por razones relacionadas con su género. Las definiciones jurídicas y estadísticas pueden variar; no todo asesinato de una mujer se clasifica necesariamente como feminicidio.', synonyms: ['asesinato de una mujer por razones de género', 'muerte violenta de una mujer por motivos de género'], example: { word: 'feminicidio', text: 'El informe analizó los factores de género presentes en el feminicidio.' }, exampleSynonym: { word: 'asesinato de una mujer por razones de género', text: 'El informe analizó los factores de género presentes en el asesinato de una mujer por razones de género.' } },
      fideicomiso: { definition: 'Relación o instrumento jurídico por el que determinados bienes quedan bajo la titularidad o administración de un fiduciario, quien debe gestionarlos conforme a los fines establecidos en beneficio de uno o más beneficiarios. La estructura y sus efectos varían según el ordenamiento jurídico.', synonyms: ['patrimonio administrado por un fiduciario', 'relación fiduciaria en beneficio de terceros', 'trust (en algunos sistemas jurídicos)'], example: { word: 'fideicomiso', text: 'El fideicomiso asignó al fiduciario la administración de los bienes en beneficio de los menores.' }, exampleSynonym: { word: 'patrimonio administrado por un fiduciario', text: 'El patrimonio administrado por un fiduciario quedó destinado al beneficio de los menores.' } },
      fibromialgia: { definition: 'Afección crónica caracterizada principalmente por dolor generalizado y sensibilidad, y que puede acompañarse de fatiga, problemas de sueño y dificultades de concentración. Su causa exacta no se conoce y el diagnóstico se basa en la evaluación clínica y los criterios aplicables.', synonyms: ['síndrome de dolor generalizado crónico', 'afección crónica de dolor y sensibilidad generalizados'], example: { word: 'fibromialgia', text: 'La evaluación clínica tuvo en cuenta el dolor generalizado y la fatiga antes de diagnosticar fibromialgia.' }, exampleSynonym: { word: 'síndrome de dolor generalizado crónico', text: 'La evaluación clínica tuvo en cuenta el dolor generalizado y la fatiga antes de identificar el síndrome de dolor generalizado crónico.' } },
      finiquitar: { definition: 'Saldar o dar por concluida una cuenta, obligación o relación mediante la liquidación de lo pendiente. En el ámbito laboral, suele referirse a ajustar y pagar las cantidades finales al extinguirse una relación de trabajo; el uso y los efectos legales dependen del país.', synonyms: ['liquidar lo pendiente', 'saldar una cuenta', 'dar por concluida una obligación'], example: { word: 'finiquitar', text: 'Al terminar la relación laboral, ambas partes revisaron las cantidades antes de finiquitarla.' }, exampleSynonym: { word: 'liquidar lo pendiente', text: 'Al terminar la relación laboral, ambas partes revisaron las cantidades antes de liquidar lo pendiente.' } },
      fiscalia: { definition: 'Institución u órgano público al que la ley atribuye funciones como promover la acción penal, intervenir en procesos y proteger la legalidad o el interés público. Sus competencias, denominación y relación con la investigación de delitos varían según el país.', synonyms: ['ministerio público (en varios países)', 'órgano de acusación pública', 'institución encargada de ejercer la acción penal'], example: { word: 'fiscalía', text: 'La fiscalía presentó ante el tribunal las pruebas reunidas durante la investigación.' }, exampleSynonym: { word: 'ministerio público', text: 'El ministerio público presentó ante el tribunal las pruebas reunidas durante la investigación.' } },
      fisioterapia: { definition: 'Disciplina sanitaria que evalúa y trata problemas de movimiento y función física para ayudar a prevenir o reducir limitaciones y favorecer la recuperación. Puede incluir ejercicio terapéutico, terapia manual y otras intervenciones según la necesidad de cada persona.', synonyms: ['terapia física', 'tratamiento fisioterapéutico', 'rehabilitación física (ámbito relacionado)'], example: { word: 'fisioterapia', text: 'La fisioterapia formó parte del plan de recuperación de la movilidad.' }, exampleSynonym: { word: 'terapia física', text: 'La terapia física formó parte del plan de recuperación de la movilidad.' } },
      flebitis: { definition: 'Inflamación de una vena. Puede afectar a una vena superficial o presentarse junto con un coágulo; el dolor, el enrojecimiento y la hinchazón dependen del caso, y la flebitis no equivale por sí sola a una trombosis venosa profunda.', synonyms: ['inflamación venosa', 'inflamación de una vena'], example: { word: 'flebitis', text: 'El equipo médico evaluó la vena inflamada para determinar si había un coágulo.' }, exampleSynonym: { word: 'inflamación venosa', text: 'El equipo médico evaluó la inflamación venosa para determinar si había un coágulo.' } },
      flemon: { definition: 'Acumulación localizada de pus en los tejidos, a menudo asociada a una infección de origen dental o de las encías. La localización y el tratamiento dependen de la causa; no siempre basta con administrar antibióticos.', synonyms: ['absceso dental (cuando ese es el origen)', 'acumulación de pus en los tejidos'], example: { word: 'flemón', text: 'El dentista examinó el flemón y determinó el tratamiento necesario para la infección.' }, exampleSynonym: { word: 'acumulación de pus en los tejidos', text: 'El dentista examinó la acumulación de pus en los tejidos y determinó el tratamiento necesario para la infección.' } },
      forense: { definition: 'Perteneciente o relativo a la aplicación de conocimientos científicos o técnicos a asuntos judiciales. Como sustantivo, puede designar a un especialista que realiza ese trabajo, en particular a un médico que examina casos relacionados con la justicia; el sentido depende del contexto y del país.', synonyms: ['relativo a la investigación judicial', 'perito forense (como sustantivo)', 'médico forense (un tipo de especialista)'], example: { word: 'forense', text: 'El equipo forense documentó los indicios siguiendo el protocolo judicial.' }, exampleSynonym: { word: 'relativo a la investigación judicial', text: 'El equipo especializado en investigación judicial documentó los indicios siguiendo el protocolo.' } }
    },
    en: {
      decriminalization: { definition: 'The removal or reduction of criminal penalties for an act or activity. The conduct may remain regulated, subject to civil or administrative consequences, or criminal only in specified circumstances, depending on the law.', synonyms: ['removal of criminal penalties', 'ending criminalization of an activity', 'reduction of criminal sanctions'], example: { word: 'decriminalization', text: 'The reform decriminalized possession while retaining rules governing sale and distribution.' }, exampleSynonym: { word: 'removal of criminal penalties', text: 'The reform removed criminal penalties for possession while retaining rules governing sale and distribution.' } },
      'rural-depopulation': { definition: 'A sustained decline in the population of rural areas or settlements. It can result from migration, ageing, low birth rates, or other demographic and economic factors, rather than movement to cities alone.', synonyms: ['decline in the rural population', 'loss of residents in rural areas', 'rural population decline'], example: { word: 'rural depopulation', text: 'The report linked rural depopulation to migration, an ageing population, and limited local services.' }, exampleSynonym: { word: 'decline in the rural population', text: 'The report linked the decline in the rural population to migration, ageing, and limited local services.' } },
      deregulation: { definition: 'The removal or reduction of government rules or controls governing an activity, industry, or market. Its scope can vary and does not necessarily eliminate all regulation.', synonyms: ['reduction of government regulation', 'removal of regulatory controls', 'regulatory liberalization (in some contexts)'], example: { word: 'deregulation', text: 'The policy changed licensing and price controls as part of a broader deregulation programme.' }, exampleSynonym: { word: 'reduction of government regulation', text: 'The policy changed licensing and price controls as part of a broader reduction of government regulation.' } },
      accrue: { definition: 'To accumulate, build up, or become due over time. Interest, benefits, rights, liabilities, and expenses can accrue; the word does not necessarily mean that money has already been earned and is payable.', synonyms: ['accumulate over time', 'build up gradually', 'become due over time'], example: { word: 'accrue', text: 'Interest began to accrue daily from the date specified in the agreement.' }, exampleSynonym: { word: 'accumulate over time', text: 'Interest began to accumulate over time on a daily basis from the date specified in the agreement.' } },
      'dilatory-plea': { definition: 'A procedural plea or objection that seeks to delay proceedings or prevent the court from deciding the merits at that stage. It may raise procedural issues such as jurisdiction; its grounds and effects depend on the legal system.', synonyms: ['procedural plea seeking delay', 'plea to postpone proceedings', 'preliminary procedural objection (in some systems)'], example: { word: 'dilatory plea', text: 'The defendant raised a dilatory plea challenging the court’s jurisdiction before the merits were heard.' }, exampleSynonym: { word: 'plea to postpone proceedings', text: 'The defendant raised a plea to postpone proceedings while the jurisdictional issue was considered.' } },
      'provincial-council': { definition: 'A representative or governing body associated with a province. Its powers, responsibilities, and structure differ by country; in Spain, a diputación provincial provides services and coordinates certain functions for municipalities in a province.', synonyms: ['province-level council', 'provincial governing body', 'diputación provincial (in Spain)'], example: { word: 'provincial council', text: 'The provincial council coordinated services for municipalities across the province.' }, exampleSynonym: { word: 'provincial governing body', text: 'The provincial governing body coordinated services for municipalities across the province.' } },
      'affirmative-action': { definition: 'Measures intended to address the effects of past or present discrimination or barriers and to improve equal opportunity for disadvantaged or underrepresented groups. The forms allowed and legal standards vary by country, institution, and context.', synonyms: ['measures to promote equal opportunity', 'positive action (in some jurisdictions)', 'remedial measures addressing disadvantage'], example: { word: 'affirmative action', text: 'The organisation reviewed its affirmative-action measures under the rules applicable to its sector.' }, exampleSynonym: { word: 'measures to promote equal opportunity', text: 'The organisation reviewed its measures to promote equal opportunity under the rules applicable to its sector.' } },
      dystopia: { definition: 'An imagined society or setting marked by oppressive conditions, severe deprivation, or other deeply undesirable features, often used in fiction to critique social or political trends. It need not be set in the future.', synonyms: ['imagined oppressive society', 'fictional society marked by severe hardship', 'opposite of a utopia (broad contrast)'], example: { word: 'dystopia', text: 'The novel depicts a dystopia in which constant surveillance restricts daily life.' }, exampleSynonym: { word: 'imagined oppressive society', text: 'The novel depicts an imagined oppressive society in which constant surveillance restricts daily life.' } },
      'double-blind': { definition: 'Describing a study design in which participants and the researchers who assess outcomes do not know which participants receive each intervention or control condition, helping reduce certain biases. The exact blinding arrangements depend on the study.', synonyms: ['double-masked', 'study in which participants and outcome assessors are blinded'], example: { word: 'double-blind', text: 'The researchers used a double-blind design so participants and outcome assessors did not know the assigned group.' }, exampleSynonym: { word: 'double-masked', text: 'The researchers used a double-masked design so participants and outcome assessors did not know the assigned group.' } },
      dollarization: { definition: 'The adoption of the US dollar, or sometimes another foreign currency referred to as a dollar, for use in an economy. It may be official or informal and partial or extensive; it does not always involve formally replacing the domestic currency.', synonyms: ['adoption of the US dollar', 'use of a foreign dollar currency', 'currency substitution involving the dollar'], example: { word: 'dollarization', text: 'The country’s dollarization expanded as households increasingly used US dollars for savings and transactions.' }, exampleSynonym: { word: 'adoption of the US dollar', text: 'The adoption of the US dollar expanded as households increasingly used it for savings and transactions.' } }
    }
  };
  for (const [lang, rows] of Object.entries(updates)) for (const [id, fields] of Object.entries(rows)) {
    const row = window.DICCIONARIOS[lang].find(item => item.id === id);
    if (!row) throw new Error(`Missing ${lang}:${id}`);
    Object.assign(row, fields);
  }
})();

// Corrections from the entry-by-entry review of Spanish and English batch 977.
(function () {
  const updates = {
    es: {
      formalizar: { definition: 'Dar carácter formal o legal a un acuerdo, acto o trámite mediante los requisitos previstos, que pueden incluir firmar o elevar un documento a escritura pública. Formalizar no siempre significa que baste con una firma.', synonyms: ['dar forma oficial a un acto', 'perfeccionar un acuerdo', 'formalizar documentalmente'], example: { word: 'formalizar', text: 'Las partes firmaron el contrato para formalizar el acuerdo conforme a los requisitos aplicables.' }, exampleSynonym: { word: 'dar forma oficial a un acto', text: 'Las partes firmaron el contrato para dar forma oficial al acuerdo conforme a los requisitos aplicables.' } },
      fraudulento: { definition: 'Que implica fraude: engaño deliberado o conducta desleal dirigida a obtener un beneficio indebido o causar un perjuicio. Su calificación jurídica depende de la normativa y de las circunstancias.', synonyms: ['engañoso y desleal', 'constitutivo de fraude', 'realizado mediante engaño'], example: { word: 'fraudulento', text: 'La entidad anuló el cobro fraudulento tras comprobar que no había sido autorizado.' }, exampleSynonym: { word: 'constitutivo de fraude', text: 'La entidad anuló el cobro constitutivo de fraude tras comprobar que no había sido autorizado.' } },
      frotis: { definition: 'Muestra biológica extendida en una capa fina sobre una superficie, normalmente un portaobjetos, para examinarla al microscopio o someterla a otras pruebas. También puede designar el procedimiento de obtención o preparación de esa muestra.', synonyms: ['muestra extendida para examen', 'preparación microscópica en capa fina', 'extendido celular (según la muestra)'], example: { word: 'frotis', text: 'El laboratorio examinó el frotis sanguíneo al microscopio.' }, exampleSynonym: { word: 'muestra extendida para examen', text: 'El laboratorio examinó la muestra sanguínea extendida al microscopio.' } },
      funeraria: { definition: 'Empresa o establecimiento que presta servicios funerarios, como organizar el funeral y gestionar determinados trámites relacionados con el fallecimiento. Los servicios ofrecidos varían.', synonyms: ['empresa de servicios funerarios', 'casa funeraria', 'agencia funeraria'], example: { word: 'funeraria', text: 'La familia contactó con una funeraria para organizar el velatorio y el sepelio.' }, exampleSynonym: { word: 'empresa de servicios funerarios', text: 'La familia contactó con una empresa de servicios funerarios para organizar el velatorio y el sepelio.' } },
      fumigar: { definition: 'Aplicar un producto o tratamiento en forma de gas, vapor, aerosol u otra dispersión para combatir plagas o desinfectar un espacio o material. El método y el producto dependen del objetivo y de las normas aplicables.', synonyms: ['tratar con un fumigante', 'aplicar un tratamiento contra plagas', 'desinfectar mediante fumigación (según el uso)'], example: { word: 'fumigar', text: 'Una empresa autorizada fumigó el almacén siguiendo las medidas de seguridad.' }, exampleSynonym: { word: 'aplicar un tratamiento contra plagas', text: 'Una empresa autorizada aplicó un tratamiento contra plagas en el almacén siguiendo las medidas de seguridad.' } },
      gabinete: { definition: 'Habitación o conjunto de dependencias destinadas al trabajo de un profesional o a una actividad especializada; también puede designar un órgano consultivo o, en política, el conjunto de ministros de un gobierno. El sentido depende del contexto y del país.', synonyms: ['despacho profesional (uno de sus sentidos)', 'equipo ministerial (sentido político)', 'oficina especializada'], example: { word: 'gabinete', text: 'El gabinete ministerial se reunió para coordinar la respuesta del gobierno.' }, exampleSynonym: { word: 'equipo ministerial', text: 'El equipo ministerial se reunió para coordinar la respuesta del gobierno.' } },
      gangrena: { definition: 'Muerte de tejido corporal, que puede ocurrir cuando se interrumpe su irrigación sanguínea o por una infección grave. Puede afectar a la piel, los músculos u órganos internos y requiere evaluación médica urgente.', synonyms: ['necrosis de tejido por falta de riego (forma frecuente)', 'muerte de tejido corporal', 'gangrena infecciosa (un tipo)'], example: { word: 'gangrena', text: 'El equipo médico detectó gangrena en el tejido afectado y actuó de inmediato.' }, exampleSynonym: { word: 'muerte de tejido corporal', text: 'El equipo médico detectó la muerte de tejido corporal en la zona afectada y actuó de inmediato.' } },
      genocidio: { definition: 'Según el derecho internacional, cualquiera de determinados actos cometidos con la intención específica de destruir total o parcialmente a un grupo nacional, étnico, racial o religioso como tal. Incluye, además del asesinato, otros actos enumerados en la Convención sobre el Genocidio; los requisitos legales concretos dependen del marco aplicable.', synonyms: ['crimen de destrucción intencional de un grupo protegido', 'exterminio de un grupo protegido (descripción parcial)', 'genocide (término jurídico internacional)'], example: { word: 'genocidio', text: 'El tribunal examinó si se había probado la intención específica exigida para el genocidio.' }, exampleSynonym: { word: 'crimen de destrucción intencional de un grupo protegido', text: 'El tribunal examinó si se había probado la intención específica exigida para el crimen de destrucción intencional de un grupo protegido.' } },
      geriatria: { definition: 'Especialidad médica dedicada a la salud y la atención de las personas mayores, incluida la prevención, el diagnóstico y el tratamiento de enfermedades y problemas funcionales asociados al envejecimiento.', synonyms: ['medicina geriátrica', 'atención médica de las personas mayores', 'geriatrics (en inglés)'], example: { word: 'geriatría', text: 'La consulta de geriatría revisó la salud, la movilidad y la medicación de la paciente.' }, exampleSynonym: { word: 'medicina geriátrica', text: 'La consulta de medicina geriátrica revisó la salud, la movilidad y la medicación de la paciente.' } },
      gingivitis: { definition: 'Inflamación de las encías, con frecuencia relacionada con la acumulación de placa bacteriana en los dientes. Puede causar enrojecimiento, hinchazón o sangrado, aunque los síntomas y las causas pueden variar.', synonyms: ['inflamación gingival', 'inflamación de las encías'], example: { word: 'gingivitis', text: 'El dentista explicó que la placa acumulada podía contribuir a la gingivitis.' }, exampleSynonym: { word: 'inflamación gingival', text: 'El dentista explicó que la placa acumulada podía contribuir a la inflamación gingival.' } }
    },
    en: {
      duopoly: { definition: 'A market structure in which two sellers or producers account for the supply of a good or service, giving them substantial influence over competition. The degree of market power and the presence of other competitors can vary.', synonyms: ['market dominated by two suppliers', 'two-firm market structure', 'shared market control by two producers'], example: { word: 'duopoly', text: 'The regulator examined whether the duopoly limited competition in the market.' }, exampleSynonym: { word: 'two-firm market structure', text: 'The regulator examined whether the two-firm market structure limited competition.' } },
      'economies-of-scale': { definition: 'Reductions in average cost that occur as the scale of production increases, often because fixed costs are spread over more units or operations become more efficient. They do not arise automatically in every expansion.', synonyms: ['cost advantages from larger-scale production', 'lower average costs as output grows', 'scale-related cost savings'], example: { word: 'economies of scale', text: 'The manufacturer lowered average costs as output expanded and achieved economies of scale.' }, exampleSynonym: { word: 'cost advantages from larger-scale production', text: 'The manufacturer lowered average costs as output expanded and gained cost advantages from larger-scale production.' } },
      'snap-election': { definition: 'An election held earlier than the date or end of term otherwise expected, usually after an early dissolution or a decision to call an election. The rules for calling one vary by political system.', synonyms: ['early election', 'premature election', 'election called ahead of schedule'], example: { word: 'snap election', text: 'The prime minister called a snap election several months before the scheduled vote.' }, exampleSynonym: { word: 'early election', text: 'The prime minister called an early election several months before the scheduled vote.' } },
      disentailment: { definition: 'The historical removal of legal restrictions that kept property, especially land, in an inalienable or entailed estate, making it available for transfer or sale. In Spain, desamortización refers to related nineteenth-century laws that put substantial Church and communal property on the market; the terms are related but not exact equivalents in every context.', synonyms: ['release of entailed property from restrictions', 'conversion of inalienable estates into transferable property', 'Spanish disentailment or desamortización (historical context)'], example: { word: 'disentailment', text: 'The disentailment measures changed who could own and transfer formerly entailed land.' }, exampleSynonym: { word: 'release of entailed property from restrictions', text: 'The release of entailed property from restrictions changed who could own and transfer the land.' } },
      decentralization: { definition: 'The transfer or distribution of authority, responsibilities, or resources away from a central body to lower levels, local bodies, or other organisations. It may be administrative, political, or fiscal and does not necessarily create regional autonomy.', synonyms: ['devolution of authority', 'transfer of powers from the centre', 'distribution of decision-making across levels'], example: { word: 'decentralization', text: 'The reform transferred budget and service responsibilities to local authorities as part of decentralization.' }, exampleSynonym: { word: 'devolution of authority', text: 'The reform devolved budget and service responsibilities to local authorities.' } },
      'drug-dependence': { definition: 'A condition in which repeated use of a substance leads to physical adaptation, psychological reliance, or both. Dependence can involve withdrawal or tolerance and is related to, but not identical with, substance use disorder or addiction.', synonyms: ['dependence on a psychoactive substance', 'substance dependence', 'drug reliance (informal)'], example: { word: 'drug dependence', text: 'The clinician assessed whether the patient’s symptoms were related to drug dependence or another condition.' }, exampleSynonym: { word: 'substance dependence', text: 'The clinician assessed whether the patient’s symptoms were related to substance dependence or another condition.' } },
      'government-bond-loan': { definition: 'A government borrowing raised by issuing bonds that investors purchase, with repayment and interest governed by the bond terms. The phrase is less common than government bond issue or sovereign borrowing.', synonyms: ['government borrowing through bonds', 'sovereign bond issue', 'public borrowing raised by bond issuance'], example: { word: 'government bond loan', text: 'The government raised funds through a bond issue with a stated maturity and interest rate.' }, exampleSynonym: { word: 'sovereign bond issue', text: 'The government raised funds through a sovereign bond issue with a stated maturity and interest rate.' } },
      'criminal-procedure': { definition: 'The body of rules governing how criminal cases are investigated, prosecuted, adjudicated, and reviewed, including procedures before and during trial. Its scope and terminology vary by legal system.', synonyms: ['rules governing criminal proceedings', 'criminal process', 'law of criminal proceedings'], example: { word: 'criminal procedure', text: 'The new statute amended criminal procedure rules for pretrial hearings.' }, exampleSynonym: { word: 'rules governing criminal proceedings', text: 'The new statute amended the rules governing criminal proceedings for pretrial hearings.' } },
      'spin-off': { definition: 'A new organisation, product, or work developed from an existing one. In business, it often means separating a unit or subsidiary into an independent company; in entertainment, it can be a work centred on characters or material from another work.', synonyms: ['business separation creating a new company (one sense)', 'derivative work or product', 'independent company formed from an existing business (one sense)'], example: { word: 'spin-off', text: 'The company separated its research division into a spin-off, while the television series later inspired a successful spin-off.' }, exampleSynonym: { word: 'independent company formed from an existing business', text: 'The company separated its research division to create an independent company formed from an existing business.' } },
      spirometry: { definition: 'A lung-function test that measures how much air a person can inhale or exhale and how quickly air can be exhaled. It can help assess lung function and investigate or monitor respiratory conditions.', synonyms: ['measurement of airflow and exhaled volume', 'spirometric lung-function test', 'breathing test measuring air volume and flow'], example: { word: 'spirometry', text: 'The clinic used spirometry to measure the amount and speed of air the patient could exhale.' }, exampleSynonym: { word: 'measurement of airflow and exhaled volume', text: 'The clinic measured airflow and exhaled volume to assess the patient’s lung function.' } }
    }
  };
  for (const [lang, rows] of Object.entries(updates)) for (const [id, fields] of Object.entries(rows)) {
    const row = window.DICCIONARIOS[lang].find(item => item.id === id);
    if (!row) throw new Error(`Missing ${lang}:${id}`);
    Object.assign(row, fields);
  }
})();

// Corrections from the entry-by-entry review of Spanish and English batch 978.
(function () {
  const updates = {
    es: {
      glucemia: { definition: 'Concentración de glucosa en la sangre. Puede medirse en distintos momentos y sus valores se interpretan según el contexto clínico y el método de medición.', synonyms: ['concentración de glucosa en sangre', 'nivel de glucosa sanguínea'], example: { word: 'glucemia', text: 'El equipo registró la glucemia antes y después de la comida.' }, exampleSynonym: { word: 'concentración de glucosa en sangre', text: 'El equipo registró la concentración de glucosa en sangre antes y después de la comida.' } },
      gestante: { definition: 'Que está embarazada; también se usa como sustantivo para referirse a una persona embarazada. El término aparece especialmente en contextos sanitarios o administrativos.', synonyms: ['embarazada', 'persona en gestación', 'encinta (uso adjetivo)'], example: { word: 'gestante', text: 'El centro ofreció atención prenatal a la gestante durante el embarazo.' }, exampleSynonym: { word: 'persona embarazada', text: 'El centro ofreció atención prenatal a la persona embarazada durante el embarazo.' } },
      gonorrea: { definition: 'Infección de transmisión sexual causada por la bacteria Neisseria gonorrhoeae. Puede afectar los genitales, el recto o la garganta y no siempre produce síntomas; la resistencia a los antibióticos dificulta el tratamiento en algunos casos.', synonyms: ['infección gonocócica', 'infección de transmisión sexual por gonococo'], example: { word: 'gonorrea', text: 'La prueba confirmó gonorrea y el equipo sanitario indicó el tratamiento recomendado.' }, exampleSynonym: { word: 'infección gonocócica', text: 'La prueba confirmó una infección gonocócica y el equipo sanitario indicó el tratamiento recomendado.' } },
      gordofobia: { definition: 'Estigma, prejuicio, rechazo o discriminación contra las personas por su peso o tamaño corporal. El término se usa en debates sociales y su alcance puede variar según el contexto.', synonyms: ['discriminación por el peso', 'estigma contra las personas gordas', 'prejuicio por el tamaño corporal'], example: { word: 'gordofobia', text: 'La organización analizó cómo la gordofobia afectaba al acceso a la atención sanitaria.' }, exampleSynonym: { word: 'discriminación por el peso', text: 'La organización analizó cómo la discriminación por el peso afectaba al acceso a la atención sanitaria.' } },
      gravamen: { definition: 'Carga, obligación o limitación que recae sobre una persona o un bien; en el ámbito fiscal, también es un tributo o impuesto. Un gravamen sobre un bien puede limitar su transmisión o garantizar una obligación, según la ley aplicable.', synonyms: ['carga que recae sobre un bien', 'impuesto o tributo (sentido fiscal)', 'afectación o carga jurídica'], example: { word: 'gravamen', text: 'Antes de comprar la vivienda, comprobaron si estaba sujeta a algún gravamen registrado.' }, exampleSynonym: { word: 'carga que recae sobre un bien', text: 'Antes de comprar la vivienda, comprobaron si estaba sujeta a alguna carga registrada.' } },
      gremio: { definition: 'Asociación de personas que ejercen un mismo oficio o actividad profesional para representar o defender intereses comunes. Históricamente, un gremio también regulaba el acceso y las prácticas de un oficio; en el uso actual puede referirse a un sector profesional.', synonyms: ['asociación de profesionales de un oficio', 'corporación profesional (según el contexto)', 'colectivo de un mismo sector'], example: { word: 'gremio', text: 'El gremio de carpinteros organizó una reunión para tratar las condiciones del oficio.' }, exampleSynonym: { word: 'asociación de profesionales de un oficio', text: 'La asociación de profesionales de la carpintería organizó una reunión para tratar las condiciones del oficio.' } },
      guardavidas: { definition: 'Persona capacitada para vigilar la seguridad de quienes nadan y responder ante emergencias en el agua o en sus inmediaciones, por ejemplo en una piscina o playa. Las funciones y requisitos dependen del lugar y la normativa.', synonyms: ['socorrista acuático', 'persona encargada de la seguridad en el agua', 'salvavidas (uso regional)'], example: { word: 'guardavidas', text: 'El guardavidas advirtió a los bañistas de que debían alejarse de la corriente.' }, exampleSynonym: { word: 'socorrista acuático', text: 'El socorrista acuático advirtió a los bañistas de que debían alejarse de la corriente.' }, translation: { en: 'lifeguard' } },
      habilitar: { definition: 'Hacer que una persona, espacio, servicio o recurso quede autorizado, apto o disponible para un uso determinado. Según el contexto, puede significar conceder facultades, adaptar un lugar o activar una función.', synonyms: ['autorizar para un uso', 'poner en condiciones de funcionar', 'conceder facultades'], example: { word: 'habilitar', text: 'El municipio habilitó el edificio como centro temporal de atención.' }, exampleSynonym: { word: 'poner en condiciones de funcionar', text: 'El municipio puso el edificio en condiciones de funcionar como centro temporal de atención.' } },
      hacinado: { definition: 'Que ocupa, junto con otras personas o cosas, un espacio excesivamente reducido o insuficiente. Suele describir una situación de hacinamiento y puede referirse a personas, animales u objetos.', synonyms: ['amontonado en un espacio insuficiente', 'en condiciones de hacinamiento', 'overcrowded (en inglés)'], example: { word: 'hacinado', text: 'El informe describió el alojamiento como hacinado por la falta de espacio suficiente.' }, exampleSynonym: { word: 'en condiciones de hacinamiento', text: 'El informe describió el alojamiento como un lugar en condiciones de hacinamiento por la falta de espacio suficiente.' }, translation: { en: 'overcrowded' } },
      hambruna: { definition: 'Escasez extrema y prolongada de alimentos que afecta a una población y causa hambre generalizada y desnutrición. Puede resultar de sequías, conflictos, crisis económicas u otros factores; no es simplemente una falta puntual de alimentos.', synonyms: ['hambre generalizada y prolongada', 'crisis alimentaria extrema', 'famine (en inglés)'], example: { word: 'hambruna', text: 'La combinación de sequía y conflicto agravó la hambruna en la región.' }, exampleSynonym: { word: 'crisis alimentaria extrema', text: 'La combinación de sequía y conflicto agravó la crisis alimentaria extrema en la región.' } }
    },
    en: {
      stagflation: { definition: 'A condition in which high inflation occurs alongside stagnant or very weak economic growth, often with high unemployment. The mix and severity of these conditions can vary.', synonyms: ['inflation with stagnant economic growth', 'stagnation combined with inflation', 'weak growth and rising prices'], example: { word: 'stagflation', text: 'The economy experienced stagflation, with rising prices and little growth.' }, exampleSynonym: { word: 'inflation with stagnant economic growth', text: 'The economy experienced inflation with stagnant economic growth and rising prices.' } },
      stipulation: { definition: 'A specific condition, requirement, or provision, especially one set out in an agreement or imposed as a term. In legal proceedings, it can also be an agreement between parties about a fact or procedure.', synonyms: ['condition or requirement', 'provision in an agreement', 'agreement about a procedural fact (legal use)'], example: { word: 'stipulation', text: 'The agreement included a stipulation setting a deadline for delivery.' }, exampleSynonym: { word: 'condition or requirement', text: 'The agreement included a condition setting a deadline for delivery.' } },
      'statutory-rape': { definition: 'A jurisdiction-specific legal term for sexual intercourse or other sexual conduct with a person below the legally specified age of consent, where age makes the conduct an offence regardless of apparent agreement. The age limits, required age differences, covered conduct, and offence name vary by law.', synonyms: ['sexual activity criminalized because of age under a statute', 'sex with a person below the age of consent (legal description)', 'unlawful sexual conduct with a minor (depending on the law)'], example: { word: 'statutory rape', text: 'The statute defined the offence by the participants’ ages and the conduct involved.' }, exampleSynonym: { word: 'sexual activity criminalized because of age under a statute', text: 'The statute defined sexual activity criminalized because of age by the participants’ ages and the conduct involved.' } },
      eurozone: { definition: 'The group of European Union member states that have adopted the euro as their currency and participate in the euro area’s common monetary policy. Some non-EU countries also use the euro but are not members of the eurozone.', synonyms: ['euro area', 'EU member states that use the euro', 'countries participating in the euro area'], example: { word: 'eurozone', text: 'The report compared inflation rates among countries in the eurozone.' }, exampleSynonym: { word: 'euro area', text: 'The report compared inflation rates among countries in the euro area.' } },
      epidemiologist: { definition: 'A specialist who studies the distribution, causes, and control of health conditions in populations. Epidemiologists may work in public health, research, government, or other fields and are not necessarily physicians.', synonyms: ['population-health researcher', 'specialist in epidemiology', 'public-health epidemiology expert'], example: { word: 'epidemiologist', text: 'The epidemiologist analysed infection patterns across several communities.' }, exampleSynonym: { word: 'specialist in epidemiology', text: 'The specialist in epidemiology analysed infection patterns across several communities.' } },
      'eviction-by-court-order': { definition: 'The removal of a tenant or other occupant from property through a court process or order. The grounds and procedure depend on the applicable housing and property law; this is distinct from a buyer’s loss of title to property sold by someone without valid ownership.', synonyms: ['court-ordered removal of an occupant', 'judicial eviction from a property', 'enforced removal under a court order'], example: { word: 'eviction by court order', text: 'The landlord could not remove the tenant without completing the required court process.' }, exampleSynonym: { word: 'court-ordered removal of an occupant', text: 'The court-ordered removal of an occupant followed the required legal process.' }, translation: { es: 'desahucio' } },
      exculpatory: { definition: 'Tending to clear someone of blame or criminal responsibility, or to support a defence that they did not commit the alleged act. It can describe evidence, information, or a statement and does not itself establish innocence.', synonyms: ['tending to clear someone of blame', 'favourable to the defence', 'indicating lack of criminal responsibility'], example: { word: 'exculpatory', text: 'The recording contained exculpatory evidence that supported the defendant’s account.' }, exampleSynonym: { word: 'tending to clear someone of blame', text: 'The recording contained evidence tending to clear the defendant of blame.' } },
      exoneration: { definition: 'The act or result of clearing a person from blame, accusation, or responsibility, or formally releasing them from an obligation. The precise legal effect depends on the context; it is not simply a pardon or cancellation of debt.', synonyms: ['clearing from blame', 'release from responsibility', 'formal discharge from an obligation (context-dependent)'], example: { word: 'exoneration', text: 'New evidence led to the exoneration of the person convicted of the crime.' }, exampleSynonym: { word: 'clearing from blame', text: 'New evidence led to the person being cleared of blame for the crime.' } },
      expatriation: { definition: 'The act or process of leaving one’s home country to live abroad; in some legal contexts, it can also mean relinquishing citizenship or nationality. It does not necessarily involve moving for work or retaining one’s original nationality.', synonyms: ['living outside one’s home country', 'relocation abroad', 'renunciation of citizenship (legal sense)'], example: { word: 'expatriation', text: 'Her expatriation involved moving abroad for a research position.' }, exampleSynonym: { word: 'relocation abroad', text: 'Her relocation abroad was arranged for a research position.' } },
      extraterritoriality: { definition: 'The application or exercise of a state’s laws, authority, or jurisdiction beyond its own territory, or a legal status in which certain foreign persons or premises receive specified protections from local jurisdiction. Diplomatic premises remain within the host state’s territory; they are not generally outside its laws.', synonyms: ['application of jurisdiction beyond national territory', 'exercise of authority outside a state’s borders', 'limited immunity from local jurisdiction (one context)'], example: { word: 'extraterritoriality', text: 'The statute’s extraterritoriality allowed it to apply to specified conduct abroad.' }, exampleSynonym: { word: 'application of jurisdiction beyond national territory', text: 'The application of jurisdiction beyond national territory covered the specified conduct abroad.' } }
    }
  };
  // Correct cross-references to the proper senses of eviction and its Spanish legal cognate.
  updates.es.eviccion = { definition: 'Privación jurídica de un bien adquirido, normalmente tras reconocerse que un tercero tenía un derecho o título preferente. En los sistemas que utilizan esta figura, puede dar lugar a responsabilidades del vendedor; los requisitos y efectos dependen de la ley aplicable.', synonyms: ['pérdida del bien por un derecho de tercero', 'privación de la posesión por título preferente', 'saneamiento por evicción (institución relacionada)'], example: { word: 'evicción', text: 'El comprador reclamó al vendedor después de perder el inmueble por el derecho preferente de un tercero.' }, exampleSynonym: { word: 'pérdida del bien por un derecho de tercero', text: 'El comprador reclamó al vendedor después de sufrir la pérdida del bien por el derecho de un tercero.' }, translation: { en: 'eviction' } };
  updates.en.eviction = { definition: 'The legal process of removing a tenant or other occupant from property, especially by court process. In some property-law systems, eviction can also refer to a buyer’s loss of possession because a third party has a superior title; that technical sense is distinct from ordinary tenant eviction.', synonyms: ['legal removal of an occupant', 'court process to recover possession of leased property', 'loss of possession under a superior title (technical property-law sense)'], example: { word: 'eviction', text: 'The tenant challenged the eviction, while the buyer faced eviction from land claimed by a third party with superior title.' }, exampleSynonym: { word: 'legal removal of an occupant', text: 'The tenant challenged the legal removal of an occupant, while the buyer faced loss of possession under a third party’s superior title.' } };
  for (const [lang, rows] of Object.entries(updates)) for (const [id, fields] of Object.entries(rows)) {
    const row = window.DICCIONARIOS[lang].find(item => item.id === id);
    if (!row) throw new Error(`Missing ${lang}:${id}`);
    Object.assign(row, fields);
  }
})();

// Corrections from the entry-by-entry review of Spanish and English batch 979.
(function () {
  const updates = {
    es: {
      hematoma: { definition: 'Acumulación localizada de sangre fuera de los vasos sanguíneos, dentro de un tejido u órgano o bajo la piel. Puede producirse, por ejemplo, tras una lesión, pero su causa y gravedad dependen del caso.', synonyms: ['acumulación de sangre en un tejido', 'moretón (hematoma superficial)', 'colección sanguínea localizada'], example: { word: 'hematoma', text: 'La prueba de imagen mostró un hematoma en el tejido muscular.' }, exampleSynonym: { word: 'acumulación de sangre en un tejido', text: 'La prueba de imagen mostró una acumulación de sangre en el tejido muscular.' } },
      hemodialisis: { definition: 'Tipo de diálisis que hace pasar la sangre por un filtro externo para retirar productos de desecho y exceso de líquido cuando los riñones no pueden hacerlo adecuadamente. La frecuencia y duración del tratamiento dependen de la situación clínica.', synonyms: ['diálisis mediante un filtro externo', 'depuración extracorpórea de la sangre', 'filtrado sanguíneo con una máquina'], example: { word: 'hemodiálisis', text: 'Durante la hemodiálisis, la sangre pasó por un dializador y volvió al cuerpo.' }, exampleSynonym: { word: 'diálisis mediante un filtro externo', text: 'Durante la diálisis mediante un filtro externo, la sangre pasó por un dializador y volvió al cuerpo.' } },
      hemorragia: { definition: 'Salida o pérdida de sangre de los vasos sanguíneos, ya sea al exterior del cuerpo o hacia tejidos y cavidades internas. Puede ser leve o grave y no toda hemorragia implica una pérdida abundante.', synonyms: ['sangrado', 'pérdida de sangre', 'bleeding (en inglés)'], example: { word: 'hemorragia', text: 'El equipo médico identificó el origen de la hemorragia interna.' }, exampleSynonym: { word: 'sangrado', text: 'El equipo médico identificó el origen del sangrado interno.' } },
      hemorroides: { definition: 'Estructuras vasculares normales de la parte inferior del recto y alrededor del ano que, al hincharse o inflamarse, pueden producir síntomas. Pueden ser internas o externas y no siempre causan dolor.', synonyms: ['almorranas (uso común)', 'venas hemorroidales inflamadas', 'cojinetes vasculares anales dilatados'], example: { word: 'hemorroides', text: 'La evaluación determinó si los síntomas estaban relacionados con hemorroides internas o externas.' }, exampleSynonym: { word: 'almorranas', text: 'La evaluación determinó si los síntomas estaban relacionados con almorranas internas o externas.' } },
      hernia: { definition: 'Protrusión de un órgano, tejido u otra estructura a través de una abertura o zona debilitada que normalmente la contiene. Hay distintos tipos de hernia y no todos se deben a levantar peso.', synonyms: ['protrusión de tejido a través de una zona debilitada', 'salida de un órgano por una abertura anormal'], example: { word: 'hernia', text: 'La exploración confirmó una hernia en la pared abdominal.' }, exampleSynonym: { word: 'protrusión de tejido a través de una zona debilitada', text: 'La exploración confirmó una protrusión de tejido a través de una zona debilitada de la pared abdominal.' } },
      herpes: { definition: 'Infección causada por un virus del grupo herpesvirus; en el uso cotidiano, suele aludir al herpes simple, causado por HSV-1 o HSV-2. Puede producir lesiones en la boca o los genitales, aunque muchas infecciones no causan síntomas reconocibles.', synonyms: ['infección por herpesvirus', 'herpes simple (sentido común)', 'infección por HSV-1 o HSV-2 (herpes simple)'], example: { word: 'herpes', text: 'La infección por herpes podía estar presente aunque no hubiera lesiones visibles.' }, exampleSynonym: { word: 'infección por herpesvirus', text: 'La infección por herpesvirus podía estar presente aunque no hubiera lesiones visibles.' }, translation: { en: 'herpes-simplex' } },
      hipotecar: { definition: 'Constituir una hipoteca sobre un bien, normalmente un inmueble, como garantía de una deuda u obligación. No significa necesariamente pedir un préstamo para comprar una vivienda.', synonyms: ['gravar un inmueble con una hipoteca', 'dar un bien en garantía hipotecaria', 'constituir una hipoteca'], example: { word: 'hipotecar', text: 'La empresa decidió hipotecar el edificio para garantizar la financiación.' }, exampleSynonym: { word: 'gravar un inmueble con una hipoteca', text: 'La empresa decidió gravar el edificio con una hipoteca para garantizar la financiación.' }, translation: { en: 'mortgage' } },
      homicidio: { definition: 'Muerte de una persona causada por otra. Según las circunstancias y la ley aplicable, puede ser lícita o constituir un delito; no es necesariamente intencional ni equivale siempre a asesinato.', synonyms: ['muerte causada por otra persona', 'killing of one person by another (en inglés)'], example: { word: 'homicidio', text: 'La investigación determinó si la muerte constituía homicidio conforme a la ley aplicable.' }, exampleSynonym: { word: 'muerte causada por otra persona', text: 'La investigación determinó si la muerte causada por otra persona constituía un delito conforme a la ley aplicable.' } },
      homofobia: { definition: 'Prejuicio, rechazo, hostilidad o discriminación dirigidos contra personas homosexuales o, en un sentido más amplio, contra personas por su orientación sexual. Puede manifestarse en actitudes individuales o en prácticas institucionales.', synonyms: ['prejuicio contra las personas homosexuales', 'discriminación por orientación sexual', 'hostilidad hacia la homosexualidad'], example: { word: 'homofobia', text: 'La campaña abordó la homofobia y sus efectos en la vida escolar.' }, exampleSynonym: { word: 'discriminación por orientación sexual', text: 'La campaña abordó la discriminación por orientación sexual y sus efectos en la vida escolar.' } },
      hospitalizar: { definition: 'Ingresar a una persona en un hospital para que reciba atención o tratamiento durante un periodo de hospitalización. La decisión depende de la evaluación clínica y de las circunstancias.', synonyms: ['ingresar a una persona en el hospital', 'admitir para atención hospitalaria'], example: { word: 'hospitalizar', text: 'El equipo decidió hospitalizar al paciente para vigilar su evolución.' }, exampleSynonym: { word: 'ingresar a una persona en el hospital', text: 'El equipo decidió ingresar al paciente en el hospital para vigilar su evolución.' } }
    },
    en: {
      'in-vitro-fertilization': { definition: 'An assisted reproductive technique in which eggs and sperm are handled and fertilized outside the body in a laboratory. Embryos may then be cultured and transferred to a uterus; fertilization or transfer does not guarantee pregnancy.', synonyms: ['IVF', 'fertilization outside the body in a laboratory', 'assisted reproductive technique involving laboratory fertilization'], example: { word: 'in vitro fertilization', text: 'The clinic discussed in vitro fertilization as one possible assisted reproductive treatment.' }, exampleSynonym: { word: 'IVF', text: 'The clinic discussed IVF as one possible assisted reproductive treatment.' } },
      'flagrante-delicto': { definition: 'The circumstance of a person being discovered while committing an offence or immediately afterward. The expression in flagrante delicto is a Latin legal phrase; the procedural consequences depend on the jurisdiction.', synonyms: ['caught in the act', 'discovered while committing an offence', 'in flagrante delicto (Latin expression)'], example: { word: 'flagrante delicto', text: 'The officers said the suspect had been caught in flagrante delicto.' }, exampleSynonym: { word: 'caught in the act', text: 'The officers said the suspect had been caught in the act.' } },
      'vulture-fund': { definition: 'A pejorative term for an investor or fund that buys distressed debt, often at a steep discount, and seeks to recover value through repayment, restructuring, or litigation. Such investors may target corporate or sovereign debt; their strategies and outcomes vary.', synonyms: ['distressed-debt investor (neutral description)', 'fund investing in distressed debt', 'vulture investor (pejorative)'], example: { word: 'vulture fund', text: 'The government criticised the vulture fund’s attempt to recover the discounted sovereign debt in court.' }, exampleSynonym: { word: 'distressed-debt investor', text: 'The government criticised the distressed-debt investor’s attempt to recover the discounted sovereign debt in court.' } },
      geopolitics: { definition: 'The study or analysis of how geography, territory, resources, location, and spatial relationships shape political power and relations among states and other actors. The term can also refer to political competition shaped by these factors.', synonyms: ['relationship between geography and political power', 'geographical analysis of international relations', 'geopolitical analysis'], example: { word: 'geopolitics', text: 'The course examined how geography and access to resources shape geopolitics.' }, exampleSynonym: { word: 'geographical analysis of international relations', text: 'The course examined how geography and access to resources shape the geographical analysis of international relations.' } },
      'contract-termination': { definition: 'The ending of a contract, whether by expiry, agreement, performance, breach, or another ground recognised by the contract or applicable law. Ending a contract may leave some rights, liabilities, or clauses in effect.', synonyms: ['ending of a contract', 'termination of contractual relations', 'bringing a contract to an end'], example: { word: 'contract termination', text: 'The contract described the notice required for termination and identified clauses that would survive it.' }, exampleSynonym: { word: 'ending of a contract', text: 'The agreement described the notice required for ending the contract and identified clauses that would survive.' } },
      surrogacy: { definition: 'An arrangement in which a person carries a pregnancy for intended parent or parents, usually under an agreement made before or during the pregnancy. It may be gestational or traditional, and legal parentage, consent, and payment rules vary by jurisdiction.', synonyms: ['surrogacy arrangement', 'pregnancy carried for intended parents', 'gestational-carrier arrangement (one type)'], example: { word: 'surrogacy', text: 'The intended parents obtained legal advice about the surrogacy arrangement before treatment began.' }, exampleSynonym: { word: 'surrogacy arrangement', text: 'The intended parents obtained legal advice about the surrogacy arrangement before treatment began.' } },
      'coup-d-etat': { definition: 'A sudden, unlawful seizure or attempted seizure of state power, usually by a small group within the political or military establishment. It is not simply any change of government or transfer of power.', synonyms: ['unlawful seizure of state power', 'coup', 'overthrow of a government by a small group'], example: { word: 'coup d’état', text: 'The attempted coup d’état was condemned by regional governments.' }, exampleSynonym: { word: 'unlawful seizure of state power', text: 'The attempted unlawful seizure of state power was condemned by regional governments.' } },
      iatrogenesis: { definition: 'The occurrence of harm, illness, or another adverse outcome caused by medical care or a healthcare intervention. The term can apply to effects of treatment, diagnosis, or other clinical actions, whether or not there was an error.', synonyms: ['harm caused by medical care', 'adverse effect of a healthcare intervention', 'iatrogenic harm'], example: { word: 'iatrogenesis', text: 'The review distinguished an adverse drug reaction from other possible forms of iatrogenesis.' }, exampleSynonym: { word: 'iatrogenic harm', text: 'The review distinguished an adverse drug reaction from other possible forms of iatrogenic harm.' } },
      'criminal-responsibility-capacity': { word: 'Capacity for criminal responsibility', definition: 'A person’s legally assessed capacity to be held criminally responsible for conduct. The criteria, including the relevance of age or mental disorder, depend on the applicable criminal law.', synonyms: ['capacity to be held criminally responsible', 'criminal responsibility (capacity assessed under law)', 'legal capacity for criminal liability'], example: { word: 'capacity for criminal responsibility', text: 'The court assessed the defendant’s capacity for criminal responsibility under the applicable law.' }, exampleSynonym: { word: 'capacity to be held criminally responsible', text: 'The court assessed whether the defendant had the capacity to be held criminally responsible under the applicable law.' } },
      'failure-to-appear': { definition: 'Failure to attend a court hearing or other proceeding when legally required to do so. Whether the absence is excused and what consequences follow depend on the reason, notice, and applicable rules.', synonyms: ['nonappearance at a required proceeding', 'failure to attend a court hearing', 'nonappearance (legal use)'], example: { word: 'failure to appear', text: 'The court considered the reason for the defendant’s failure to appear at the hearing.' }, exampleSynonym: { word: 'nonappearance at a required proceeding', text: 'The court considered the reason for the defendant’s nonappearance at the required proceeding.' } },
      herpes: { definition: 'A viral infection caused by a virus in the Herpesviridae family; in everyday usage, herpes often refers specifically to herpes simplex virus type 1 or type 2. Herpes simplex infections may cause oral or genital sores, but many people have no noticeable symptoms.', synonyms: ['herpesvirus infection', 'herpes simplex infection (common usage)', 'HSV infection (herpes simplex)'], example: { word: 'herpes', text: 'A person can have herpes without visible sores or other recognised symptoms.' }, exampleSynonym: { word: 'herpesvirus infection', text: 'A person can have a herpesvirus infection without visible sores or other recognised symptoms.' }, translation: { es: 'herpes' } }
    }
  };
  for (const [lang, rows] of Object.entries(updates)) for (const [id, fields] of Object.entries(rows)) {
    const row = window.DICCIONARIOS[lang].find(item => item.id === id);
    if (!row) throw new Error(`Missing ${lang}:${id}`);
    Object.assign(row, fields);
  }
})();

// Corrections from the entry-by-entry review of Spanish and English batch 980.
(function () {
  const updates = {
    es: {
      huerfano: { definition: 'Persona que ha perdido a uno o ambos progenitores. El término también puede aplicarse a un animal o, en sentido figurado, a algo que carece de su elemento o referente habitual; no se limita a niños.', synonyms: ['persona que ha perdido a uno o ambos progenitores', 'huérfano de padre o madre (según el caso)'], example: { word: 'huérfano', text: 'Tras la muerte de su madre, quedó huérfano de madre y siguió viviendo con su padre.' }, exampleSynonym: { word: 'persona que ha perdido a uno de sus progenitores', text: 'Tras la muerte de su madre, pasó a ser una persona que había perdido a uno de sus progenitores y siguió viviendo con su padre.' } },
      ictus: { definition: 'Acontecimiento cerebrovascular agudo causado por la interrupción del flujo sanguíneo a una zona del cerebro o por una hemorragia cerebral. Puede producir daño neurológico y requiere atención urgente; se distinguen, entre otros, los ictus isquémicos y hemorrágicos.', synonyms: ['accidente cerebrovascular', 'ataque cerebral', 'stroke (en inglés)'], example: { word: 'ictus', text: 'El equipo activó el protocolo de ictus ante la aparición repentina de síntomas neurológicos.' }, exampleSynonym: { word: 'accidente cerebrovascular', text: 'El equipo activó el protocolo de accidente cerebrovascular ante la aparición repentina de síntomas neurológicos.' } },
      icterico: { definition: 'Que presenta ictericia, es decir, una coloración amarillenta de la piel o de la parte blanca de los ojos por acumulación de bilirrubina. Puede deberse a distintas causas y no necesariamente a una enfermedad del hígado.', synonyms: ['con ictericia', 'amarillento por ictericia', 'jaundiced (en inglés)'], example: { word: 'ictérico', text: 'El recién nacido presentó ictericia y el equipo evaluó si necesitaba tratamiento.' }, exampleSynonym: { word: 'con ictericia', text: 'El recién nacido estaba con ictericia y el equipo evaluó si necesitaba tratamiento.' }, translation: { en: 'jaundiced' } },
      iliquidez: { definition: 'Falta de activos líquidos o de efectivo suficiente para atender pagos y obligaciones a corto plazo cuando vencen. Puede afectar a una empresa o a una persona y no es necesariamente lo mismo que insolvencia o quiebra.', synonyms: ['falta de liquidez', 'escasez de efectivo disponible', 'dificultad para atender pagos inmediatos'], example: { word: 'iliquidez', text: 'La empresa afrontó una iliquidez temporal pese a conservar activos de valor.' }, exampleSynonym: { word: 'falta de liquidez', text: 'La empresa afrontó una falta de liquidez temporal pese a conservar activos de valor.' } },
      impetigo: { definition: 'Infección bacteriana superficial de la piel, contagiosa, causada habitualmente por estafilococos o estreptococos. Puede producir llagas, ampollas o costras y es frecuente en niños pequeños, aunque puede afectar a otras edades.', synonyms: ['infección bacteriana contagiosa de la piel', 'infección cutánea superficial por estafilococos o estreptococos'], example: { word: 'impétigo', text: 'El médico diagnosticó impétigo tras examinar las lesiones costrosas de la piel.' }, exampleSynonym: { word: 'infección bacteriana contagiosa de la piel', text: 'El médico diagnosticó una infección bacteriana contagiosa de la piel tras examinar las lesiones costrosas.' } },
      imputar: { definition: 'Atribuir a una persona un hecho o una responsabilidad; en el ámbito penal, atribuirle provisionalmente la participación en un delito o dirigir formalmente una acusación contra ella, según la terminología y el procedimiento de cada jurisdicción.', synonyms: ['atribuir un hecho a alguien', 'acusar formalmente de un delito (según el sistema jurídico)', 'atribuir responsabilidad penal'], example: { word: 'imputar', text: 'La fiscalía imputó al acusado la participación en el delito tras reunir indicios.' }, exampleSynonym: { word: 'atribuir responsabilidad penal', text: 'La fiscalía atribuyó responsabilidad penal al acusado tras reunir indicios.' }, translation: { en: 'charge' } },
      incapacidad: { definition: 'Falta o limitación de capacidad para realizar una actividad, ejercer una función o actuar jurídicamente. Puede ser física, laboral, funcional o legal; su reconocimiento y alcance dependen del contexto y de las normas aplicables.', synonyms: ['falta o limitación de capacidad', 'imposibilidad de desempeñar una función (según el contexto)', 'incapacity (en inglés)'], example: { word: 'incapacidad', text: 'La valoración distinguió entre la limitación funcional y la incapacidad laboral reconocida.' }, exampleSynonym: { word: 'falta o limitación de capacidad', text: 'La valoración distinguió entre la limitación funcional y la falta o limitación de capacidad laboral reconocida.' }, translation: { en: 'incapacity' } },
      incubadora: { definition: 'Dispositivo que mantiene condiciones controladas de temperatura y, según el uso, humedad, oxígeno u otros factores. En medicina se emplea para cuidar a algunos recién nacidos; también se usa en laboratorios y para apoyar proyectos empresariales.', synonyms: ['cámara de incubación', 'incubadora neonatal (uso médico)', 'incubadora de empresas (uso figurado o institucional)'], example: { word: 'incubadora', text: 'El recién nacido permaneció en una incubadora neonatal mientras recibía los cuidados indicados.' }, exampleSynonym: { word: 'incubadora neonatal', text: 'El recién nacido permaneció en una incubadora neonatal mientras recibía los cuidados indicados.' } },
      indemnizar: { definition: 'Compensar a una persona o entidad por un daño, una pérdida o un perjuicio, normalmente mediante el pago de una suma de dinero. El derecho a la indemnización y su cuantía dependen de las circunstancias y de la ley aplicable.', synonyms: ['compensar económicamente un perjuicio', 'pagar una indemnización', 'resarcir un daño'], example: { word: 'indemnizar', text: 'La aseguradora indemnizó a la familia por los daños cubiertos por la póliza.' }, exampleSynonym: { word: 'compensar económicamente un perjuicio', text: 'La aseguradora compensó económicamente a la familia por los daños cubiertos por la póliza.' }, translation: { en: 'compensate' } },
      inhabilitar: { definition: 'Privar a alguien de la aptitud o del derecho para ejercer una función, cargo, profesión o facultad, a menudo mediante una decisión legal o administrativa. También puede significar impedir que un dispositivo, servicio o recurso funcione.', synonyms: ['inhabilitar legalmente para ejercer', 'descalificar o privar de una facultad', 'desactivar o dejar fuera de servicio (uso técnico)'], example: { word: 'inhabilitar', text: 'La sentencia podía inhabilitar al funcionario para ejercer determinados cargos.' }, exampleSynonym: { word: 'privar del derecho a ejercer', text: 'La sentencia podía privar al funcionario del derecho a ejercer determinados cargos.' }, translation: { en: 'disqualify' } }
    },
    en: {
      unconstitutionality: { definition: 'The quality or state of being contrary to a constitution. Whether a law or act is invalid, and who may declare it so, depends on the constitutional system and the available judicial or political procedures.', synonyms: ['conflict with a constitution', 'constitutional invalidity (where declared)', 'incompatibility with constitutional requirements'], example: { word: 'unconstitutionality', text: 'The court considered the law’s alleged unconstitutionality under the constitution.' }, exampleSynonym: { word: 'conflict with a constitution', text: 'The court considered the alleged conflict between the law and the constitution.' } },
      defenselessness: { definition: 'A state of being unable or insufficiently able to protect or defend oneself, one’s interests, or one’s rights. In legal contexts, it can refer to being deprived of a genuine opportunity to respond or present a defence; its procedural meaning varies by jurisdiction.', synonyms: ['inability to defend oneself', 'lack of effective means of defence', 'legal inability to present a defence (context-dependent)'], example: { word: 'defenselessness', text: 'The court examined whether the lack of notice had left the defendant unable to present a defence.' }, exampleSynonym: { word: 'inability to defend oneself', text: 'The court examined whether the lack of notice had left the defendant unable to defend himself effectively.' } },
      shingles: { definition: 'A painful rash illness caused by reactivation of the varicella-zoster virus, the same virus that causes chickenpox. The rash commonly appears on one side of the body or face, though presentation can vary.', synonyms: ['herpes zoster', 'varicella-zoster virus reactivation', 'shingles rash'], example: { word: 'shingles', text: 'The clinician diagnosed shingles after assessing the painful rash on one side of the patient’s torso.' }, exampleSynonym: { word: 'herpes zoster', text: 'The clinician diagnosed herpes zoster after assessing the painful rash on one side of the patient’s torso.' } },
      immunodeficiency: { definition: 'A deficiency or impairment in one or more parts of the immune system that reduces its ability to respond normally. It may be inherited or acquired and varies in type and severity; it can increase susceptibility to some infections but does not affect everyone in the same way.', synonyms: ['impaired immune function', 'deficiency of immune-system function', 'immune deficiency'], example: { word: 'immunodeficiency', text: 'Testing identified an immunodeficiency affecting part of the immune response.' }, exampleSynonym: { word: 'immune deficiency', text: 'Testing identified an immune deficiency affecting part of the immune response.' } },
      'legal-interdiction': { definition: 'A court-ordered restriction or removal of a person’s legal capacity under systems that use the term interdiction, often historically associated with disability or inability to manage certain affairs. The term and its effects vary by jurisdiction, and many legal frameworks now emphasise support for decision-making and safeguards for autonomy.', synonyms: ['judicial interdiction (in some legal systems)', 'court-ordered restriction of legal capacity (jurisdiction-dependent)', 'legal guardianship or curatorship (related, not always equivalent)'], example: { word: 'legal interdiction', text: 'The court reviewed the existing interdiction and the support available to the person concerned.' }, exampleSynonym: { word: 'judicial interdiction', text: 'The court reviewed the judicial interdiction and the support available to the person concerned.' } },
      'interlocutory-order': { definition: 'A non-final order or ruling made by a court during proceedings to decide an interim, procedural, or other issue before final disposition. Its scope and appealability depend on the jurisdiction and type of case.', synonyms: ['interim court order (in some contexts)', 'non-final judicial order', 'procedural order before final judgment'], example: { word: 'interlocutory order', text: 'The court issued an interlocutory order addressing access to the documents while the case continued.' }, exampleSynonym: { word: 'non-final judicial order', text: 'The court issued a non-final judicial order addressing access to the documents while the case continued.' } },
      interoperability: { definition: 'The ability of systems, devices, or organisations to exchange information and make use of it across their interfaces. It may depend on technical standards, shared formats, and compatible processes; it does not guarantee that all systems work together without limitations.', synonyms: ['ability to exchange and use information across systems', 'system compatibility and information exchange', 'interworking capability'], example: { word: 'interoperability', text: 'The agencies adopted shared data standards to improve interoperability between their systems.' }, exampleSynonym: { word: 'ability to exchange and use information across systems', text: 'The agencies adopted shared data standards to improve the ability to exchange and use information across their systems.' } },
      'parliamentary-interpellation': { definition: 'A formal parliamentary procedure in which a legislator or parliamentary group calls on a government minister or other official to explain or defend a policy or decision. The rules, debate, and possible consequences vary by parliament.', synonyms: ['formal parliamentary demand for an explanation', 'parliamentary questioning of a government official', 'interpellation of a minister'], example: { word: 'parliamentary interpellation', text: 'The opposition submitted a parliamentary interpellation about the government’s energy policy.' }, exampleSynonym: { word: 'formal parliamentary demand for an explanation', text: 'The opposition submitted a formal parliamentary demand for an explanation of the government’s energy policy.' } },
      secularism: { definition: 'A principle or movement concerning the relationship between religion and public authority, commonly advocating that government institutions and political power be separate from religious control. Its interpretations vary and do not always require the exclusion of religion from public life.', synonyms: ['separation of religious and political authority', 'secular political principle', 'state independence from religious institutions (one interpretation)'], example: { word: 'secularism', text: 'The debate considered how secularism shapes the relationship between religious institutions and government.' }, exampleSynonym: { word: 'separation of religious and political authority', text: 'The debate considered how the separation of religious and political authority shapes their relationship.' } },
      'arbitration-award': { definition: 'A decision made by an arbitral tribunal that resolves some or all issues submitted to arbitration. It is generally binding under the applicable arbitration law, subject to any grounds and procedures for challenge, recognition, or enforcement.', synonyms: ['arbitral decision', 'arbitrator’s award', 'decision resolving an arbitration dispute'], example: { word: 'arbitration award', text: 'The tribunal issued an arbitration award resolving the parties’ contractual dispute.' }, exampleSynonym: { word: 'arbitral decision', text: 'The tribunal issued an arbitral decision resolving the parties’ contractual dispute.' } }
    }
  };
  for (const [lang, rows] of Object.entries(updates)) for (const [id, fields] of Object.entries(rows)) {
    const row = window.DICCIONARIOS[lang].find(item => item.id === id);
    if (!row) throw new Error(`Missing ${lang}:${id}`);
    Object.assign(row, fields);
  }
})();

// Corrections from the entry-by-entry review of Spanish and English batch 981.
(function () {
  const updates = {
    es: {
      inmobiliaria: { definition: 'Empresa que intermedia o presta servicios relacionados con la compraventa, el alquiler, la gestión o la promoción de bienes inmuebles. También puede usarse como adjetivo referido al sector o a esos bienes.', synonyms: ['agencia inmobiliaria (uno de sus sentidos)', 'empresa de servicios inmobiliarios', 'compañía del sector inmobiliario'], example: { word: 'inmobiliaria', text: 'La inmobiliaria gestionó el alquiler del apartamento y la revisión de la documentación.' }, exampleSynonym: { word: 'empresa de servicios inmobiliarios', text: 'La empresa de servicios inmobiliarios gestionó el alquiler del apartamento y la revisión de la documentación.' } },
      insolvente: { definition: 'Que no puede cumplir regularmente sus obligaciones de pago o cuyo pasivo supera el valor de sus activos, según el criterio y la legislación aplicables. La falta temporal de liquidez no implica siempre insolvencia.', synonyms: ['incapaz de atender sus obligaciones de pago', 'con pasivo superior al activo (un criterio de insolvencia)', 'en situación de insolvencia'], example: { word: 'insolvente', text: 'El tribunal analizó si la empresa era insolvente o solo atravesaba una falta temporal de liquidez.' }, exampleSynonym: { word: 'en situación de insolvencia', text: 'El tribunal analizó si la empresa estaba en situación de insolvencia o solo atravesaba una falta temporal de liquidez.' } },
      intestado: { definition: 'Dicho de una persona fallecida: que murió sin otorgar un testamento válido. En derecho sucesorio, también puede referirse a la sucesión o herencia que se tramita sin testamento; las reglas varían según el país.', synonyms: ['fallecido sin testamento válido', 'relativo a una sucesión sin testamento', 'intestate (en inglés)'], example: { word: 'intestado', text: 'Al fallecer intestado, su herencia se distribuyó conforme a las reglas legales de sucesión.' }, exampleSynonym: { word: 'fallecido sin testamento válido', text: 'Al ser un fallecido sin testamento válido, su herencia se distribuyó conforme a las reglas legales de sucesión.' } },
      intoxicacion: { definition: 'Alteración o daño producido por la exposición o entrada en el organismo de una sustancia tóxica o en una cantidad perjudicial. Puede deberse a ingestión, inhalación, contacto u otras vías; el alcohol también puede causar intoxicación.', synonyms: ['envenenamiento', 'efecto nocivo de una sustancia tóxica', 'intoxication (en inglés)'], example: { word: 'intoxicación', text: 'Los servicios sanitarios investigaron si la intoxicación se debía al alimento o a otra sustancia.' }, exampleSynonym: { word: 'envenenamiento', text: 'Los servicios sanitarios investigaron si el envenenamiento se debía al alimento o a otra sustancia.' }, translation: { en: 'intoxication' } },
      intubar: { definition: 'Introducir un tubo en una cavidad o conducto del cuerpo, especialmente en la tráquea para mantener abierta la vía respiratoria o facilitar la ventilación. La intubación puede realizarse por distintos motivos clínicos.', synonyms: ['introducir un tubo en la tráquea (sentido médico habitual)', 'colocar un tubo endotraqueal', 'realizar una intubación'], example: { word: 'intubar', text: 'El equipo decidió intubar al paciente para mantener la vía respiratoria durante la intervención.' }, exampleSynonym: { word: 'colocar un tubo endotraqueal', text: 'El equipo decidió colocar un tubo endotraqueal para mantener la vía respiratoria durante la intervención.' } },
      inseminacion: { definition: 'Introducción de semen o espermatozoides en el aparato reproductor femenino para facilitar la fecundación. Puede ser inseminación artificial o formar parte de la reproducción asistida; el método y el lugar de depósito varían.', synonyms: ['introducción de semen en el aparato reproductor', 'inseminación artificial (un tipo)', 'procedimiento de inseminar'], example: { word: 'inseminación', text: 'La clínica explicó en qué consistía la inseminación intrauterina y qué otras opciones existían.' }, exampleSynonym: { word: 'introducción de semen en el aparato reproductor', text: 'La clínica explicó el procedimiento de introducción de semen en el aparato reproductor y las demás opciones.' } },
      isquemia: { definition: 'Disminución o interrupción del flujo sanguíneo que llega a un tejido u órgano, lo que puede reducir el aporte de oxígeno y nutrientes y causar daño. Puede afectar a distintas partes del cuerpo y tener diversas causas.', synonyms: ['reducción del riego sanguíneo', 'flujo insuficiente de sangre a un tejido', 'ischaemia (variante británica en inglés)'], example: { word: 'isquemia', text: 'Las pruebas detectaron una isquemia en el tejido y el equipo valoró sus posibles causas.' }, exampleSynonym: { word: 'reducción del riego sanguíneo', text: 'Las pruebas detectaron una reducción del riego sanguíneo en el tejido y el equipo valoró sus posibles causas.' }, translation: { en: 'ischaemia' } },
      islamofobia: { definition: 'Prejuicio, hostilidad, miedo o discriminación dirigidos contra el islam, las personas musulmanas o quienes son percibidos como tales. El término puede abarcar actitudes y prácticas individuales o institucionales.', synonyms: ['prejuicio contra el islam o las personas musulmanas', 'discriminación antimusulmana', 'hostilidad hacia personas percibidas como musulmanas'], example: { word: 'islamofobia', text: 'El informe examinó incidentes de islamofobia y discriminación contra personas musulmanas.' }, exampleSynonym: { word: 'discriminación antimusulmana', text: 'El informe examinó incidentes de discriminación antimusulmana y otros prejuicios.' } },
      jaqueca: { definition: 'Migraña o episodio de dolor de cabeza migrañoso, que puede ser intenso y acompañarse de náuseas o sensibilidad a la luz y al sonido. En el uso coloquial, también puede designar un dolor de cabeza fuerte.', synonyms: ['migraña (uso frecuente)', 'dolor de cabeza migrañoso', 'ataque migrañoso'], example: { word: 'jaqueca', text: 'La jaqueca le obligó a descansar en una habitación tranquila.' }, exampleSynonym: { word: 'migraña', text: 'La migraña le obligó a descansar en una habitación tranquila.' } },
      jornalero: { definition: 'Persona que trabaja a cambio de un jornal, es decir, de una remuneración calculada por jornada o día trabajado. El término se asocia especialmente con el trabajo agrícola, pero no se limita a ese sector.', synonyms: ['trabajador remunerado por jornada', 'trabajador que cobra un jornal', 'peón agrícola (un uso frecuente)'], example: { word: 'jornalero', text: 'El jornalero cobró según los días que había trabajado en la cosecha.' }, exampleSynonym: { word: 'trabajador remunerado por jornada', text: 'El trabajador remunerado por jornada cobró según los días que había trabajado en la cosecha.' } }
    },
    en: {
      'legal-standing': { definition: 'The legal entitlement of a person or organisation to bring a claim, participate in a proceeding, or seek a particular remedy. The requirements vary by court and jurisdiction and may include a sufficient connection to the dispute or a legally recognised interest.', synonyms: ['standing to sue', 'legal entitlement to bring a claim', 'locus standi'], example: { word: 'legal standing', text: 'The court considered whether the organisation had legal standing to challenge the decision.' }, exampleSynonym: { word: 'standing to sue', text: 'The court considered whether the organisation had standing to sue over the decision.' } },
      'inclusive-language': { definition: 'Language chosen to avoid unnecessary exclusion, stereotyping, or disrespect toward people or groups, including in relation to gender, disability, race, or other identities. What is considered inclusive can depend on audience, context, and language conventions.', synonyms: ['non-exclusionary language', 'language attentive to diverse identities', 'respectful and inclusive wording'], example: { word: 'inclusive language', text: 'The editor revised the guidance to use inclusive language for a wider audience.' }, exampleSynonym: { word: 'non-exclusionary language', text: 'The editor revised the guidance to use non-exclusionary language for a wider audience.' } },
      lobbyist: { definition: 'A person who seeks to influence legislation, government policy, or public decisions on behalf of an employer, client, organisation, or cause. Registration, disclosure, and other rules vary by jurisdiction.', synonyms: ['lobbying representative', 'advocate seeking to influence public policy', 'government-relations professional (one role)'], example: { word: 'lobbyist', text: 'The lobbyist disclosed the organisation represented before meeting lawmakers.' }, exampleSynonym: { word: 'lobbying representative', text: 'The lobbying representative disclosed the organisation represented before meeting lawmakers.' } },
      islamism: { definition: 'A broad and diverse set of political ideas or movements that give Islam a role in public life or political governance. The term covers different approaches and should not be treated as synonymous with Islam, Muslim identity, or violent extremism.', synonyms: ['political movements referring to Islam', 'political Islam (broad term)', 'Islamist political thought'], example: { word: 'Islamism', text: 'The book compared different currents of Islamism and their views on political institutions.' }, exampleSynonym: { word: 'political Islam', text: 'The book compared different currents of political Islam and their views on political institutions.' } },
      'loss-of-earnings': { definition: 'Income a person loses, or is expected to lose, because they cannot work or earn as before, for example after an injury or breach of contract. Whether it is recoverable and how it is calculated depend on the facts and applicable law.', synonyms: ['lost income', 'loss of wages or earnings', 'income lost because of an injury or other event'], example: { word: 'loss of earnings', text: 'The claimant documented the loss of earnings caused by the period away from work.' }, exampleSynonym: { word: 'lost income', text: 'The claimant documented the lost income caused by the period away from work.' } },
      'division-of-marital-assets': { definition: 'The allocation or division of property and financial interests between spouses or former spouses, commonly on separation or divorce. Which assets are included and how they are divided depend on the jurisdiction, the marital-property regime, and any agreement.', synonyms: ['division of marital property', 'allocation of assets on divorce', 'distribution of property between spouses'], example: { word: 'division of marital assets', text: 'The agreement set out how the couple’s property would be handled in the division of marital assets.' }, exampleSynonym: { word: 'division of marital property', text: 'The agreement set out how the couple’s property would be handled in the division of marital property.' } },
      macroeconomics: { definition: 'The branch of economics that studies the behaviour and performance of an economy as a whole, including output, employment, prices, growth, and policy at national, regional, or global levels.', synonyms: ['study of the economy as a whole', 'aggregate economics', 'analysis of economy-wide outcomes'], example: { word: 'macroeconomics', text: 'The course used macroeconomics to examine inflation and employment across several countries.' }, exampleSynonym: { word: 'study of the economy as a whole', text: 'The course used the study of the economy as a whole to examine inflation and employment across several countries.' } },
      malnutrition: { definition: 'An abnormal nutritional condition caused by inadequate, excessive, or imbalanced intake or absorption of energy or nutrients. It includes undernutrition, micronutrient deficiencies, and overnutrition; it does not mean only insufficient food.', synonyms: ['nutritional imbalance', 'inadequate or excessive nutrition', 'undernutrition (one form, not an exact synonym)'], example: { word: 'malnutrition', text: 'The survey measured malnutrition, including both undernutrition and excess weight.' }, exampleSynonym: { word: 'nutritional imbalance', text: 'The survey measured nutritional imbalance, including both undernutrition and excess weight.' } },
      'municipal-association': { definition: 'An organisation formed by two or more municipalities or local authorities to cooperate on shared services, projects, or responsibilities. Its legal form and powers vary by country.', synonyms: ['intermunicipal association', 'association of local authorities', 'joint municipal body'], example: { word: 'municipal association', text: 'The municipalities created a municipal association to coordinate waste management.' }, exampleSynonym: { word: 'intermunicipal association', text: 'The municipalities created an intermunicipal association to coordinate waste management.' } },
      matriarchy: { definition: 'A social system in which women, especially mothers or senior women, hold central roles in family organisation, descent, inheritance, or authority. The term has different meanings in anthropology and everyday use and does not necessarily mean that women control every form of power.', synonyms: ['matriarchal social system', 'society with women in central positions of authority', 'matrilineal social system (related, but not always equivalent)'], example: { word: 'matriarchy', text: 'The study distinguished matrilineal inheritance from the broader idea of a matriarchy.' }, exampleSynonym: { word: 'matriarchal social system', text: 'The study distinguished matrilineal inheritance from the broader idea of a matriarchal social system.' } },
      intoxication: { definition: 'A state of impaired physical or mental functioning caused by alcohol, a drug, or another substance, or a harmful effect caused by exposure to a toxic substance. The intended sense depends on context.', synonyms: ['substance-induced impairment', 'poisoning or toxic exposure (one sense)', 'state of being under the influence'], example: { word: 'intoxication', text: 'The clinician assessed whether the symptoms reflected alcohol intoxication or exposure to another substance.' }, exampleSynonym: { word: 'substance-induced impairment', text: 'The clinician assessed whether the symptoms reflected substance-induced impairment from alcohol or another substance.' }, translation: { es: 'intoxicacion' } }
    }
  };
  for (const [lang, rows] of Object.entries(updates)) for (const [id, fields] of Object.entries(rows)) {
    const row = window.DICCIONARIOS[lang].find(item => item.id === id);
    if (!row) throw new Error(`Missing ${lang}:${id}`);
    Object.assign(row, fields);
  }
})();

// Corrections from the entry-by-entry review of Spanish and English batch 982.
(function () {
  const updates = {
    es: {
      judicializar: { definition: 'Someter un asunto a la actuación o decisión de los tribunales. En el uso político y periodístico, también puede referirse a que los tribunales intervengan de forma destacada en un conflicto o cuestión pública.', synonyms: ['llevar un asunto ante la justicia', 'someter una cuestión a decisión judicial', 'recurrir a los tribunales'], example: { word: 'judicializar', text: 'Las partes decidieron judicializar el conflicto después de agotar la mediación.' }, exampleSynonym: { word: 'recurrir a los tribunales', text: 'Las partes decidieron recurrir a los tribunales después de agotar la mediación.' } },
      jurisdiccion: { definition: 'Potestad de un tribunal u otra autoridad para conocer de determinados asuntos y tomar decisiones conforme a la ley. También puede designar el territorio, la materia o las personas sobre los que se ejerce esa potestad.', synonyms: ['competencia legal de un tribunal (sentido relacionado)', 'ámbito de autoridad de un tribunal', 'territorio sujeto a una autoridad'], example: { word: 'jurisdicción', text: 'El tribunal comprobó si tenía jurisdicción para conocer del asunto.' }, exampleSynonym: { word: 'ámbito de autoridad de un tribunal', text: 'El tribunal comprobó si el asunto pertenecía a su ámbito de autoridad.' } },
      laringitis: { definition: 'Inflamación de la laringe, órgano que contiene las cuerdas vocales. Puede causar ronquera o pérdida temporal de la voz, aunque los síntomas y las causas varían.', synonyms: ['inflamación laríngea', 'inflamación de la laringe'], example: { word: 'laringitis', text: 'La evaluación atribuyó la ronquera a una laringitis.' }, exampleSynonym: { word: 'inflamación laríngea', text: 'La evaluación atribuyó la ronquera a una inflamación laríngea.' } },
      laudo: { definition: 'Decisión dictada por un árbitro o tribunal arbitral para resolver una controversia. En algunos contextos también puede designar el dictamen o informe emitido por un especialista; el sentido depende del ámbito.', synonyms: ['decisión arbitral', 'fallo de un tribunal arbitral', 'dictamen pericial (en ciertos usos)'], example: { word: 'laudo', text: 'El tribunal arbitral emitió un laudo sobre el desacuerdo contractual.' }, exampleSynonym: { word: 'decisión arbitral', text: 'El tribunal arbitral emitió una decisión arbitral sobre el desacuerdo contractual.' }, translation: { en: 'arbitration-award' } },
      legatario: { definition: 'Persona a quien un testamento atribuye uno o varios bienes o derechos concretos a título de legado. Se distingue del heredero, que sucede en una parte o en la totalidad de la herencia según el ordenamiento jurídico.', synonyms: ['beneficiario de un legado', 'persona que recibe un bien legado por testamento'], example: { word: 'legatario', text: 'El testamento nombraba legatario a su sobrino y le dejaba una obra de arte.' }, exampleSynonym: { word: 'beneficiario de un legado', text: 'El testamento nombraba beneficiario de un legado a su sobrino y le dejaba una obra de arte.' } },
      laxante: { definition: 'Sustancia o medicamento que facilita o provoca la evacuación intestinal. Hay distintos tipos y su uso adecuado depende de la causa y de las indicaciones sanitarias; también puede usarse como adjetivo referido a ese efecto.', synonyms: ['medicamento para facilitar la evacuación intestinal', 'purgante (según el tipo y el uso)', 'que favorece la evacuación intestinal (adjetivo)'], example: { word: 'laxante', text: 'La farmacéutica explicó cómo debía utilizarse el laxante que le habían recomendado.' }, exampleSynonym: { word: 'medicamento para facilitar la evacuación intestinal', text: 'La farmacéutica explicó cómo debía utilizarse el medicamento para facilitar la evacuación intestinal que le habían recomendado.' } },
      'labio-leporino': { word: 'Fisura labial', definition: 'Abertura congénita en el labio superior que se produce cuando los tejidos no se unen completamente durante el desarrollo fetal. Puede presentarse sola o junto con una fisura del paladar. “Labio leporino” es una denominación tradicional que hoy suele evitarse por considerarse estigmatizante.', synonyms: ['hendidura congénita del labio superior', 'fisura del labio', 'labio leporino (término tradicional)'], example: { word: 'fisura labial', text: 'El equipo explicó las opciones de atención para la fisura labial del bebé.' }, exampleSynonym: { word: 'hendidura congénita del labio superior', text: 'El equipo explicó las opciones de atención para la hendidura congénita del labio superior del bebé.' } },
      legajo: { definition: 'Conjunto de documentos reunidos y ordenados porque corresponden a un mismo asunto, expediente o persona. El término y su uso administrativo pueden variar según el país.', synonyms: ['expediente documental', 'carpeta de documentos de un asunto', 'conjunto de documentos archivados'], example: { word: 'legajo', text: 'El funcionario incorporó la resolución al legajo del procedimiento.' }, exampleSynonym: { word: 'expediente documental', text: 'El funcionario incorporó la resolución al expediente documental del procedimiento.' } },
      lepra: { definition: 'Enfermedad infecciosa crónica, también llamada enfermedad de Hansen, causada principalmente por la bacteria Mycobacterium leprae. Afecta sobre todo a la piel y los nervios periféricos; es curable con tratamiento adecuado y no se transmite por contacto casual.', synonyms: ['enfermedad de Hansen', 'infección crónica por Mycobacterium leprae'], example: { word: 'lepra', text: 'El programa sanitario ofreció diagnóstico y tratamiento para la lepra sin coste.' }, exampleSynonym: { word: 'enfermedad de Hansen', text: 'El programa sanitario ofreció diagnóstico y tratamiento para la enfermedad de Hansen sin coste.' } },
      licitacion: { definition: 'Procedimiento competitivo en el que una entidad solicita y evalúa ofertas para adquirir bienes, contratar servicios u obras, o conceder un contrato. Puede ser público o privado; las reglas y requisitos dependen de la entidad y de la normativa aplicable.', synonyms: ['concurso para adjudicar un contrato', 'procedimiento de presentación y evaluación de ofertas', 'tender (en inglés)'], example: { word: 'licitación', text: 'La entidad publicó las condiciones de la licitación para contratar el servicio.' }, exampleSynonym: { word: 'concurso para adjudicar un contrato', text: 'La entidad publicó las condiciones del concurso para adjudicar el contrato del servicio.' }, translation: { en: 'tender' } }
    },
    en: {
      meritocracy: { definition: 'A system or ideal in which selection, advancement, or rewards are based mainly on ability and achievement. In practice, access to opportunities and how merit is measured may be affected by social and institutional inequalities.', synonyms: ['advancement based on merit', 'system rewarding achievement and ability', 'merit-based selection'], example: { word: 'meritocracy', text: 'The report questioned whether the company’s promotion process functioned as a meritocracy.' }, exampleSynonym: { word: 'merit-based selection', text: 'The report questioned whether the company’s promotion process used merit-based selection.' } },
      'cultural-mixing': { definition: 'The exchange, blending, or interaction of cultural practices, ideas, or traditions among people or communities. It can produce new cultural forms, but its meaning depends on the context and is not necessarily equivalent to ethnic or genetic mixture.', synonyms: ['cultural blending', 'exchange between cultures', 'mixing of cultural traditions'], example: { word: 'cultural mixing', text: 'Migration and trade contributed to cultural mixing in the port city.' }, exampleSynonym: { word: 'cultural blending', text: 'Migration and trade contributed to cultural blending in the port city.' }, translation: { es: 'mestizaje' } },
      metaverse: { definition: 'A concept for interconnected or persistent digital environments in which people may interact with one another, digital objects, and services, sometimes through avatars or immersive technologies. There is no single universally adopted technical definition, and not every virtual world is a metaverse.', synonyms: ['persistent shared digital environment (one concept)', 'network of immersive virtual spaces', 'interconnected virtual environments'], example: { word: 'metaverse', text: 'The company tested a collaborative virtual workspace as one possible metaverse application.' }, exampleSynonym: { word: 'interconnected virtual environments', text: 'The company tested collaboration tools across interconnected virtual environments.' } },
      microeconomics: { definition: 'The branch of economics that studies the decisions and interactions of individuals, households, firms, and other agents, as well as how prices and markets allocate resources.', synonyms: ['study of individual economic choices', 'analysis of firms, households, and markets', 'economics at the level of individual agents'], example: { word: 'microeconomics', text: 'The course used microeconomics to explain how supply and demand affect prices.' }, exampleSynonym: { word: 'study of individual economic choices', text: 'The course used the study of individual economic choices to explain how supply and demand affect prices.' } },
      multiculturalism: { definition: 'The presence of cultural diversity within a society and, in political or social theory, approaches that recognise, accommodate, or value the coexistence of different cultural groups. The term can refer to a descriptive fact or to a policy or ideology.', synonyms: ['recognition of cultural diversity', 'coexistence of multiple cultural groups', 'policy approach accommodating cultural pluralism'], example: { word: 'multiculturalism', text: 'The essay compared different approaches to multiculturalism and cultural rights.' }, exampleSynonym: { word: 'recognition of cultural diversity', text: 'The essay compared different approaches to the recognition of cultural diversity and cultural rights.' } },
      wokeism: { definition: 'An informal and often critical or pejorative term for “woke” ideas, attitudes, or activism, especially concerning social injustice. Its use is contested and can refer either to awareness of discrimination or, in criticism, to what a speaker sees as excessive or performative activism.', synonyms: ['wokery (informal, often critical)', 'term for “woke” politics or activism (usage varies)', 'critical label for social-justice activism'], example: { word: 'wokeism', text: 'The commentator used “wokeism” critically, while others described the same issue as activism against discrimination.' }, exampleSynonym: { word: 'wokery', text: 'The commentator used “wokery” critically, while others described the same issue as activism against discrimination.' } },
      monetization: { definition: 'The process of converting an asset, activity, service, or audience into a source of revenue or money. It can refer to digital content and platforms, as well as to financial or economic processes.', synonyms: ['generation of revenue from an asset or service', 'turning an activity into a source of income', 'revenue generation'], example: { word: 'monetization', text: 'The publisher explored several forms of monetization for its online service.' }, exampleSynonym: { word: 'revenue generation', text: 'The publisher explored several forms of revenue generation for its online service.' } },
      medicalization: { definition: 'The process by which a condition, behaviour, or aspect of life comes to be defined, understood, or managed as a medical issue. The term is often used critically when people argue that social or ordinary experiences are being treated too narrowly as medical problems.', synonyms: ['framing a condition as a medical issue', 'expansion of medical explanations or treatment', 'medical framing of a social or personal condition'], example: { word: 'medicalization', text: 'The article examined the medicalization of grief and the social factors shaping it.' }, exampleSynonym: { word: 'framing a condition as a medical issue', text: 'The article examined the framing of grief as a medical issue and the social factors shaping it.' } },
      nationalization: { definition: 'The transfer of ownership or control of a private company, asset, or industry to a national government or public authority. The process, compensation, and legal basis vary by country and circumstance.', synonyms: ['transfer of private assets to state ownership', 'state acquisition of a company or industry', 'public ownership of a formerly private asset'], example: { word: 'nationalization', text: 'The government announced the nationalization of the utility under a new statute.' }, exampleSynonym: { word: 'state acquisition of a company or industry', text: 'The government announced the state acquisition of the utility under a new statute.' } },
      'takeover-bid': { definition: 'An offer to acquire enough shares or voting rights in a company to obtain control of it. The term is often used for offers concerning publicly traded companies; legal requirements and whether the offer is voluntary or mandatory vary by jurisdiction.', synonyms: ['offer to acquire control of a company', 'bid to take over a company', 'company acquisition offer'], example: { word: 'takeover bid', text: 'The investor announced a takeover bid for the listed company.' }, exampleSynonym: { word: 'offer to acquire control of a company', text: 'The investor announced an offer to acquire control of the listed company.' } },
      'arbitration-award': { word: 'Arbitral award', definition: 'A decision made by an arbitral tribunal that resolves some or all issues submitted to arbitration. It is generally binding under applicable law, subject to procedures for challenge, recognition, or enforcement.', synonyms: ['arbitration award', 'arbitral decision', 'award issued by an arbitral tribunal'], example: { word: 'arbitral award', text: 'The tribunal issued an arbitral award resolving the dispute over the contract.' }, exampleSynonym: { word: 'arbitration award', text: 'The tribunal issued an arbitration award resolving the dispute over the contract.' }, translation: { es: 'laudo' } }
    }
  };
  for (const [lang, rows] of Object.entries(updates)) for (const [id, fields] of Object.entries(rows)) {
    const row = window.DICCIONARIOS[lang].find(item => item.id === id);
    if (!row) throw new Error(`Missing ${lang}:${id}`);
    Object.assign(row, fields);
  }
})();

// Corrections from the entry-by-entry review of Spanish and English batch 983.
(function () {
  const updates = {
    es: {
      liquidez: { definition: 'Facilidad con la que un activo puede convertirse en efectivo sin una pérdida importante de valor; también, capacidad de una persona o entidad para disponer de efectivo y atender pagos a su vencimiento. El sentido depende del contexto financiero.', synonyms: ['disponibilidad de efectivo', 'facilidad de conversión de un activo en dinero', 'capacidad para atender pagos a corto plazo'], example: { word: 'liquidez', text: 'La empresa conservó suficiente liquidez para cubrir los pagos previstos.' }, exampleSynonym: { word: 'disponibilidad de efectivo', text: 'La empresa conservó suficiente disponibilidad de efectivo para cubrir los pagos previstos.' } },
      locatario: { definition: 'Persona que recibe el uso o disfrute de un bien, con frecuencia una vivienda o local, mediante un contrato de arrendamiento y a cambio de una renta. La terminología jurídica cambia según el país y el tipo de bien.', synonyms: ['arrendatario', 'inquilino (si se trata de vivienda)', 'persona que alquila un bien'], example: { word: 'locatario', text: 'El locatario notificó al propietario que dejaría el local al finalizar el contrato.' }, exampleSynonym: { word: 'arrendatario', text: 'El arrendatario notificó al propietario que dejaría el local al finalizar el contrato.' } },
      logopedia: { definition: 'Disciplina sanitaria que evalúa y trata dificultades de comunicación, habla, lenguaje, voz, audición y deglución. La denominación y el alcance profesional pueden variar según el país.', synonyms: ['terapia del habla y del lenguaje', 'tratamiento logopédico', 'speech and language therapy (en inglés)'], example: { word: 'logopedia', text: 'La logopedia ayudó a tratar las dificultades de articulación del niño.' }, exampleSynonym: { word: 'terapia del habla y del lenguaje', text: 'La terapia del habla y del lenguaje ayudó a tratar las dificultades de articulación del niño.' } },
      lupus: { definition: 'Nombre común de un grupo de enfermedades autoinmunes, entre ellas el lupus eritematoso sistémico, en las que el sistema inmunitario puede afectar tejidos sanos. Los órganos afectados y los síntomas varían ampliamente.', synonyms: ['enfermedad autoinmune del grupo del lupus', 'lupus eritematoso (según el tipo)', 'lupus eritematoso sistémico (un tipo)'], example: { word: 'lupus', text: 'El equipo evaluó si los síntomas podían corresponder a lupus u otra enfermedad.' }, exampleSynonym: { word: 'lupus eritematoso sistémico', text: 'El equipo evaluó si los síntomas podían corresponder a lupus eritematoso sistémico u otra enfermedad.' } },
      magistratura: { definition: 'Función, cargo o carrera de los magistrados y, según el país, de otros jueces. También puede designar al conjunto de quienes ejercen la función judicial o a la institución correspondiente.', synonyms: ['función judicial de los magistrados', 'carrera judicial', 'conjunto de magistrados'], example: { word: 'magistratura', text: 'Tras años de ejercicio judicial, accedió a una plaza en la magistratura.' }, exampleSynonym: { word: 'carrera judicial', text: 'Tras años de ejercicio judicial, accedió a una plaza en la carrera judicial.' } },
      malaria: { definition: 'Enfermedad parasitaria causada por especies de Plasmodium y transmitida principalmente por la picadura de mosquitos Anopheles hembra infectados. Puede ser grave y es prevenible y tratable; sus síntomas y evolución dependen de la especie y de otros factores.', synonyms: ['paludismo', 'infección por Plasmodium', 'enfermedad parasitaria transmitida por mosquitos Anopheles'], example: { word: 'malaria', text: 'Antes del viaje, consultó qué medidas preventivas frente a la malaria eran adecuadas para su destino.' }, exampleSynonym: { word: 'paludismo', text: 'Antes del viaje, consultó qué medidas preventivas frente al paludismo eran adecuadas para su destino.' }, translation: { en: 'malaria' } },
      malformacion: { definition: 'Alteración anormal de la forma o estructura de un órgano o parte del cuerpo, con frecuencia originada durante el desarrollo antes del nacimiento. Puede ser congénita o, en ciertos usos, describir una alteración estructural adquirida.', synonyms: ['anomalía estructural', 'alteración de la forma o estructura corporal', 'defecto congénito (cuando está presente al nacer)'], example: { word: 'malformación', text: 'El estudio prenatal detectó una malformación cardíaca y el equipo explicó los siguientes pasos.' }, exampleSynonym: { word: 'anomalía estructural', text: 'El estudio prenatal detectó una anomalía estructural cardíaca y el equipo explicó los siguientes pasos.' } },
      malversacion: { definition: 'Uso o apropiación indebidos de dinero o bienes que se administran o custodian, especialmente fondos públicos. La definición y el delito aplicable dependen de la legislación; puede haber malversación tanto en el sector público como en organizaciones privadas.', synonyms: ['apropiación indebida de fondos administrados', 'desvío ilícito de recursos', 'malversación de caudales públicos (sentido específico)'], example: { word: 'malversación', text: 'La auditoría investigó el posible desvío de fondos bajo responsabilidad del funcionario.' }, exampleSynonym: { word: 'apropiación indebida de fondos administrados', text: 'La auditoría investigó la posible apropiación indebida de fondos administrados por el funcionario.' } },
      mamografia: { definition: 'Exploración radiográfica de la mama. Puede utilizarse para detectar signos de cáncer en personas sin síntomas (mamografía de cribado) o para evaluar un hallazgo o síntoma (mamografía diagnóstica).', synonyms: ['mamograma', 'radiografía de la mama', 'exploración radiológica mamaria'], example: { word: 'mamografía', text: 'El centro explicó las diferencias entre la mamografía de cribado y la diagnóstica.' }, exampleSynonym: { word: 'radiografía de la mama', text: 'El centro explicó cómo se realiza la radiografía de la mama de cribado y la diagnóstica.' } },
      manicomio: { word: 'Hospital psiquiátrico', definition: 'Centro sanitario que presta atención especializada en salud mental, incluida la atención hospitalaria cuando se necesita. “Manicomio” es un término histórico que hoy suele evitarse por su carácter estigmatizante.', synonyms: ['hospital de salud mental', 'centro psiquiátrico', 'manicomio (término histórico o peyorativo)'], example: { word: 'hospital psiquiátrico', text: 'El hospital psiquiátrico ofrecía atención de salud mental con distintos niveles de apoyo.' }, exampleSynonym: { word: 'hospital de salud mental', text: 'El hospital de salud mental ofrecía atención con distintos niveles de apoyo.' } }
    },
    en: {
      'ruling-party': { definition: 'The political party or coalition that currently forms or leads the government. The term may be used differently in parliamentary and presidential systems.', synonyms: ['governing party', 'party in government', 'governing coalition (when multiple parties)'], example: { word: 'ruling party', text: 'The ruling party introduced its budget in parliament.' }, exampleSynonym: { word: 'governing party', text: 'The governing party introduced its budget in parliament.' } },
      oligarchy: { definition: 'A system of government or power in which a relatively small group controls or strongly influences political authority. The group may be defined by wealth, family, military status, or another source of power.', synonyms: ['rule by a small group', 'concentration of political power in a few hands', 'government controlled by a few influential people'], example: { word: 'oligarchy', text: 'The report described how a small circle of officials concentrated power in the oligarchy.' }, exampleSynonym: { word: 'rule by a small group', text: 'The report described how a small circle of officials concentrated power under rule by a small group.' } },
      oligopoly: { definition: 'A market structure in which a small number of firms account for a large share of supply. Because firms are interdependent, one firm’s decisions can affect competitors; the market need not be fully controlled by them.', synonyms: ['market dominated by a few firms', 'market with a small number of major suppliers', 'concentrated market structure'], example: { word: 'oligopoly', text: 'The regulator examined how the firms’ decisions affected competition in the oligopoly.' }, exampleSynonym: { word: 'concentrated market structure', text: 'The regulator examined how the firms’ decisions affected competition in the concentrated market structure.' } },
      'legal-system': { definition: 'The framework of laws, legal institutions, procedures, and practices through which a society creates, interprets, and applies law. Its structure and sources vary across jurisdictions.', synonyms: ['system of law and legal institutions', 'framework for creating and applying law', 'body of legal rules and procedures'], example: { word: 'legal system', text: 'The study compared how each legal system handles commercial disputes.' }, exampleSynonym: { word: 'system of law and legal institutions', text: 'The study compared how each system of law and legal institutions handles commercial disputes.' } },
      neoliberalism: { definition: 'A contested term for political and economic ideas or policies that give a substantial role to markets, competition, private enterprise, and limited or restructured state intervention. Its use and precise meaning vary among scholars and political speakers.', synonyms: ['market-oriented political-economic ideas', 'political and economic approach favouring market mechanisms', 'free-market policy orientation (one use)'], example: { word: 'neoliberalism', text: 'The article examined how different writers use the term neoliberalism to describe economic reforms.' }, exampleSynonym: { word: 'market-oriented political-economic ideas', text: 'The article examined how different writers use the phrase market-oriented political-economic ideas to describe economic reforms.' } },
      'narco-state': { definition: 'A political label for a state in which drug-trafficking organisations are alleged to exert substantial influence over government, public institutions, or political decisions. It is not a formal legal category and can be used polemically.', synonyms: ['state heavily influenced by drug-trafficking networks', 'country where drug-trafficking groups influence government', 'narco-state (political label)'], example: { word: 'narco-state', text: 'Commentators disputed whether the term narco-state accurately described the country’s institutions.' }, exampleSynonym: { word: 'state heavily influenced by drug-trafficking networks', text: 'Commentators disputed whether the description “state heavily influenced by drug-trafficking networks” accurately described the country’s institutions.' } },
      'failure-to-render-assistance': { definition: 'Failure to provide help to someone in danger when a legal duty to do so applies. Whether a duty exists, what help is required, and whether failure is a crime depend on the jurisdiction and circumstances; a general moral duty is not always a legal duty.', synonyms: ['failure to assist a person in danger when legally required', 'breach of a duty to provide assistance', 'failure to rescue (in some legal systems)'], example: { word: 'failure to render assistance', text: 'The court considered whether the defendant had a legal duty to provide assistance in the circumstances.' }, exampleSynonym: { word: 'breach of a duty to provide assistance', text: 'The court considered whether the defendant had breached a duty to provide assistance in the circumstances.' } },
      'annulment-of-marriage': { definition: 'A legal declaration that a marriage is void or voidable under the applicable law. The grounds, procedure, and effects vary by jurisdiction, and an annulment is distinct from divorce; it is not necessarily a ruling that the relationship never existed for every purpose.', synonyms: ['marital annulment', 'declaration of nullity of marriage', 'legal annulment of a marriage'], example: { word: 'annulment of marriage', text: 'The court considered whether the statutory grounds for annulment of the marriage had been met.' }, exampleSynonym: { word: 'declaration of nullity of marriage', text: 'The court considered whether the statutory grounds for a declaration of nullity of marriage had been met.' } },
      peremptory: { definition: 'Insisting on immediate compliance or allowing no refusal, debate, or delay; in law, it can also mean final or not open to challenge in a particular way. A peremptory deadline is one that cannot be extended under the applicable rules.', synonyms: ['imperative or commanding', 'final and absolute (legal use)', 'not allowing delay or refusal'], example: { word: 'peremptory', text: 'The arbitrator issued a peremptory order requiring the parties to comply by the stated date.' }, exampleSynonym: { word: 'imperative or commanding', text: 'The arbitrator issued an imperative order requiring the parties to comply by the stated date.' } },
      'legal-personality': { definition: 'The status by which the law recognises an entity as a legal person capable of holding rights and duties. It can apply to natural persons and, where the law provides, organisations or other entities; it is distinct from a person’s capacity to make particular legal decisions.', synonyms: ['legal personhood', 'recognition as a bearer of legal rights and duties', 'juridical personality'], example: { word: 'legal personality', text: 'Registration gave the association legal personality under the applicable statute.' }, exampleSynonym: { word: 'legal personhood', text: 'Registration gave the association legal personhood under the applicable statute.' } }
    }
  };
  for (const [lang, rows] of Object.entries(updates)) for (const [id, fields] of Object.entries(rows)) {
    const row = window.DICCIONARIOS[lang].find(item => item.id === id);
    if (!row) throw new Error(`Missing ${lang}:${id}`);
    Object.assign(row, fields);
  }
})();

// Corrections from the entry-by-entry review of Spanish and English batch 984.
(function () {
  const updates = {
    es: {
      mastectomia: { definition: 'Intervención quirúrgica que extirpa una mama o tejido mamario, de forma total o parcial según el procedimiento. Puede realizarse para tratar o reducir el riesgo de determinadas enfermedades, entre otros motivos.', synonyms: ['extirpación quirúrgica de una mama', 'cirugía de extirpación mamaria', 'mastectomía total o parcial (según la técnica)'], example: { word: 'mastectomía', text: 'El equipo explicó las opciones de reconstrucción después de la mastectomía.' }, exampleSynonym: { word: 'cirugía de extirpación mamaria', text: 'El equipo explicó las opciones de reconstrucción después de la cirugía de extirpación mamaria.' }, translation: { en: 'mastectomy' } },
      matasellos: { definition: 'Marca postal estampada sobre un sello o envío, normalmente para inutilizar el sello y dejar constancia de una fecha, lugar u otro dato del procesamiento postal.', synonyms: ['marca postal de cancelación', 'sello postal fechador', 'marca que anula un sello usado'], example: { word: 'matasellos', text: 'El matasellos permitió comprobar cuándo y dónde se había enviado la carta.' }, exampleSynonym: { word: 'marca postal de cancelación', text: 'La marca postal de cancelación permitió comprobar cuándo y dónde se había enviado la carta.' }, translation: { en: 'postmark' } },
      mayorista: { definition: 'Persona o empresa que vende bienes en grandes cantidades, normalmente a minoristas, empresas u otros compradores profesionales. También se usa como adjetivo para referirse a la venta o distribución al por mayor.', synonyms: ['comerciante al por mayor', 'empresa de distribución mayorista', 'wholesaler (en inglés)'], example: { word: 'mayorista', text: 'El mayorista abastecía a varias tiendas de la región.' }, exampleSynonym: { word: 'comerciante al por mayor', text: 'El comerciante al por mayor abastecía a varias tiendas de la región.' }, translation: { en: 'wholesaler' } },
      maquinista: { definition: 'Persona que maneja u opera una máquina o un equipo mecánico. En el transporte ferroviario, designa especialmente a quien conduce una locomotora o un tren.', synonyms: ['operador de maquinaria', 'conductor de tren (sentido ferroviario)', 'persona que maneja una máquina'], example: { word: 'maquinista', text: 'El maquinista redujo la velocidad al aproximarse a la estación.' }, exampleSynonym: { word: 'conductor de tren', text: 'El conductor de tren redujo la velocidad al aproximarse a la estación.' } },
      medicacion: { definition: 'Medicamentos que una persona toma o recibe, o el acto y régimen de administrarlos para prevenir, aliviar o tratar una afección. Puede referirse a un solo fármaco o a varios; el sentido depende del contexto.', synonyms: ['tratamiento farmacológico', 'conjunto de medicamentos utilizados', 'administración de medicamentos'], example: { word: 'medicación', text: 'El profesional revisó la medicación que tomaba la paciente antes de modificar el tratamiento.' }, exampleSynonym: { word: 'tratamiento farmacológico', text: 'El profesional revisó el tratamiento farmacológico de la paciente antes de modificarlo.' }, translation: { en: 'medication' } },
      mendicidad: { definition: 'Actividad o situación de pedir limosna, dinero o ayuda material, a menudo en espacios públicos. Sus circunstancias pueden relacionarse con pobreza, exclusión social u otros factores y no deben reducirse a una elección individual.', synonyms: ['acción de pedir limosna', 'práctica de mendigar', 'begging (en inglés)'], example: { word: 'mendicidad', text: 'El programa municipal combinó atención social con medidas para abordar la mendicidad en la calle.' }, exampleSynonym: { word: 'acción de pedir limosna', text: 'El programa municipal combinó atención social con medidas para abordar la acción de pedir limosna en la calle.' }, translation: { en: 'begging' } },
      menstruacion: { definition: 'Proceso periódico en el que se desprende y expulsa por la vagina el revestimiento del útero, acompañado de sangrado, cuando no se ha producido un embarazo. La frecuencia y duración varían entre personas y etapas de la vida.', synonyms: ['regla (uso coloquial)', 'sangrado menstrual', 'periodo menstrual'], example: { word: 'menstruación', text: 'La información sobre salud menstrual explicó los cambios que pueden acompañar a la menstruación.' }, exampleSynonym: { word: 'sangrado menstrual', text: 'La información sobre salud menstrual explicó los cambios que pueden acompañar al sangrado menstrual.' } },
      metastasis: { definition: 'Proceso por el que células cancerosas se desprenden del tumor primario y se diseminan a otras partes del cuerpo, donde pueden formar tumores secundarios. El término también puede designar uno de esos tumores secundarios.', synonyms: ['diseminación del cáncer a distancia', 'tumor secundario originado por un cáncer', 'metástasis cancerosa'], example: { word: 'metástasis', text: 'Las pruebas evaluaron si el tumor había producido metástasis en otros órganos.' }, exampleSynonym: { word: 'tumor secundario', text: 'Las pruebas evaluaron si el cáncer había producido un tumor secundario en otros órganos.' } },
      migratorio: { definition: 'Relacionado con la migración o el desplazamiento de personas, animales u otros organismos de un lugar a otro. En contextos humanos puede referirse a movimientos dentro de un país o entre países, temporales o permanentes.', synonyms: ['relativo a la migración', 'relacionado con desplazamientos poblacionales', 'migratory (en inglés)'], example: { word: 'migratorio', text: 'El informe analizó el patrón migratorio de varias especies de aves.' }, exampleSynonym: { word: 'relativo a la migración', text: 'El informe analizó el patrón relativo a la migración de varias especies de aves.' } },
      membresia: { definition: 'Condición o calidad de miembro de una organización, asociación, club o grupo. En algunos países también puede referirse a la cuota o suscripción que se paga para pertenecer a una entidad o utilizar un servicio.', synonyms: ['condición de miembro', 'pertenencia a una organización', 'suscripción o cuota de socio (uso regional)'], example: { word: 'membresía', text: 'La membresía de la asociación daba acceso a sus actividades y publicaciones.' }, exampleSynonym: { word: 'condición de miembro', text: 'La condición de miembro de la asociación daba acceso a sus actividades y publicaciones.' }, translation: { en: 'membership' } }
    },
    en: {
      plutocracy: { definition: 'A system or society in which political power is held or strongly influenced by a small wealthy group. The term can also refer to that group and is often used critically.', synonyms: ['rule or influence by the wealthy', 'government dominated by a wealthy minority', 'political power concentrated among the rich'], example: { word: 'plutocracy', text: 'The inquiry examined whether concentrated wealth had turned political influence into a plutocracy.' }, exampleSynonym: { word: 'rule or influence by the wealthy', text: 'The inquiry examined whether concentrated wealth had produced rule or influence by the wealthy.' } },
      'executive-branch': { definition: 'The part of government responsible for carrying out laws and conducting public administration. Its leadership and powers vary by constitutional system and may include a president, prime minister, cabinet, or other officials.', synonyms: ['executive arm of government', 'government branch that administers and enforces laws', 'executive authority'], example: { word: 'executive branch', text: 'The executive branch issued regulations under authority delegated by the legislature.' }, exampleSynonym: { word: 'executive arm of government', text: 'The executive arm of government issued regulations under authority delegated by the legislature.' } },
      'legislative-branch': { definition: 'The part of government entrusted primarily with making, amending, and repealing laws. It may be a parliament, congress, assembly, or another body, and its relationship with other branches varies by constitutional system.', synonyms: ['legislature', 'law-making branch of government', 'parliament or assembly (depending on the system)'], example: { word: 'legislative branch', text: 'The legislative branch debated the bill and proposed amendments.' }, exampleSynonym: { word: 'legislature', text: 'The legislature debated the bill and proposed amendments.' } },
      polarization: { definition: 'The process or state in which opinions, interests, or groups become more divided or opposed. Political or social polarization can involve two or more camps and does not always eliminate moderate positions.', synonyms: ['growing division between opposing views', 'increasing separation of groups or opinions', 'intensification of social or political divisions'], example: { word: 'polarization', text: 'The study measured political polarization across several issues and groups.' }, exampleSynonym: { word: 'growing division between opposing views', text: 'The study measured the growing division between opposing views across several issues and groups.' } },
      populism: { definition: 'A political approach or style that claims to represent “the people” against an elite or establishment. It appears across different ideologies and may involve particular policies, rhetoric, or leadership styles; the term is used in several contested ways.', synonyms: ['politics framed as people versus elite', 'appeal to popular sovereignty against an establishment', 'political style claiming to speak for ordinary people'], example: { word: 'populism', text: 'The researchers compared how populism was used by movements on different parts of the political spectrum.' }, exampleSynonym: { word: 'politics framed as people versus elite', text: 'The researchers compared political messages framed as people versus elite across different movements.' } },
      'preliminary-question': { definition: 'An issue that must be considered before a court or decision-maker can resolve another matter. In some legal systems it refers more specifically to a question that another court or authority must decide first; procedural effects depend on the jurisdiction.', synonyms: ['threshold issue', 'question to be determined before the main issue', 'prejudicial question (in certain legal systems)'], example: { word: 'preliminary question', text: 'The court suspended the proceedings while another authority determined the preliminary question.' }, exampleSynonym: { word: 'threshold issue', text: 'The court suspended the proceedings while another authority determined the threshold issue.' } },
      presidentialism: { definition: 'A system of government organised around a president, typically with the president serving as head of state and government for a fixed term and holding executive authority separately from the legislature. Institutional powers and checks differ among countries.', synonyms: ['presidential system of government', 'government with a separately elected executive president (in many systems)', 'presidential form of government'], example: { word: 'presidentialism', text: 'The constitutional analysis compared presidentialism with parliamentary government.' }, exampleSynonym: { word: 'presidential system of government', text: 'The constitutional analysis compared a presidential system of government with parliamentary government.' } },
      'judicial-misconduct': { definition: 'Inappropriate conduct by a judge that violates applicable ethical, professional, or disciplinary standards. It may be serious without constituting a crime, and the definition and review process vary by jurisdiction.', synonyms: ['judicial ethical violation', 'improper conduct by a judge', 'breach of judicial conduct standards'], example: { word: 'judicial misconduct', text: 'The oversight body investigated a complaint alleging judicial misconduct.' }, exampleSynonym: { word: 'improper conduct by a judge', text: 'The oversight body investigated a complaint alleging improper conduct by a judge.' }, translation: null },
      'risk-premium': { definition: 'The additional expected return or compensation investors require for holding an asset or accepting an exposure with greater risk than a chosen benchmark. In sovereign borrowing, it can refer to the extra yield investors demand on a government’s debt relative to a lower-risk benchmark.', synonyms: ['additional expected return for risk', 'compensation for bearing greater risk', 'extra yield over a benchmark (bond-market use)'], example: { word: 'risk premium', text: 'Investors demanded a higher risk premium for the more uncertain asset.' }, exampleSynonym: { word: 'additional expected return for risk', text: 'Investors demanded a higher additional expected return for holding the more uncertain asset.' } },
      privatization: { definition: 'The transfer of ownership, control, or provision of an asset, company, or service from the public sector to private entities. It can take different forms and does not always involve an outright sale.', synonyms: ['transfer from public to private ownership or control', 'private-sector operation of a formerly public service', 'sale of a state-owned company (one form)'], example: { word: 'privatization', text: 'The proposal considered privatization through a transfer of operating control rather than a full sale.' }, exampleSynonym: { word: 'transfer from public to private ownership or control', text: 'The proposal considered a transfer from public to private ownership or control of the service.' } }
    }
  };
  for (const [lang, rows] of Object.entries(updates)) for (const [id, fields] of Object.entries(rows)) {
    const row = window.DICCIONARIOS[lang].find(item => item.id === id);
    if (!row) throw new Error(`Missing ${lang}:${id}`);
    const { translation, ...otherFields } = fields;
    Object.assign(row, otherFields);
    if (translation === null) delete row.translation;
    else if (translation) row.translation = translation;
  }
})();

// Corrections from the entry-by-entry review of Spanish and English batch 985.
(function () {
  const updates = {
    es: {
      minusvalia: { word: 'minusvalía', definition: 'Situación que surge de la interacción entre una persona con una deficiencia y las barreras del entorno que pueden limitar su participación plena y efectiva. En el uso administrativo de España, el grado de discapacidad es una valoración oficial expresada en porcentaje; “minusvalía” es una denominación antigua que hoy suele evitarse.', synonyms: ['discapacidad', 'grado de discapacidad (en el sentido administrativo)', 'limitación de la participación por barreras del entorno'], example: { word: 'discapacidad', text: 'La administración reconoció un grado de discapacidad del 40 % tras valorar la situación conforme a los criterios aplicables.' }, exampleSynonym: { word: 'grado de discapacidad', text: 'La administración reconoció un grado de discapacidad del 40 % tras valorar la situación conforme a los criterios aplicables.' }, translation: { en: 'disability' } },
      miocarditis: { definition: 'Inflamación del miocardio, el tejido muscular del corazón. Puede tener distintas causas y manifestaciones; el término nombra la inflamación y no determina por sí solo su causa o gravedad.', synonyms: ['inflamación del músculo cardíaco', 'inflamación del miocardio', 'miocarditis aguda (cuando es de inicio reciente)'], example: { word: 'miocarditis', text: 'El equipo médico evaluó posibles causas de la miocarditis y vigiló la función cardíaca.' }, exampleSynonym: { word: 'inflamación del miocardio', text: 'El equipo médico evaluó posibles causas de la inflamación del miocardio y vigiló la función cardíaca.' }, translation: { en: 'myocarditis' } },
      misoginia: { definition: 'Prejuicio, desprecio, hostilidad u odio hacia las mujeres; puede expresarse en ideas, conductas o prácticas discriminatorias.', synonyms: ['prejuicio contra las mujeres', 'hostilidad hacia las mujeres', 'aversión o desprecio por las mujeres'], example: { word: 'misoginia', text: 'El informe analizó cómo la misoginia se manifestaba tanto en discursos como en prácticas discriminatorias.' }, exampleSynonym: { word: 'prejuicio contra las mujeres', text: 'El informe analizó cómo el prejuicio contra las mujeres se manifestaba tanto en discursos como en prácticas discriminatorias.' } },
      moratoria: { definition: 'Aplazamiento o suspensión temporal y autorizada de una obligación, un pago o una actividad. Su alcance y condiciones dependen de la norma, el acuerdo o la decisión que la establece.', synonyms: ['aplazamiento temporal', 'suspensión temporal de una obligación', 'prórroga autorizada'], example: { word: 'moratoria', text: 'La norma estableció una moratoria temporal para el cumplimiento de la obligación.' }, exampleSynonym: { word: 'aplazamiento temporal', text: 'La norma estableció un aplazamiento temporal para el cumplimiento de la obligación.' } },
      morosidad: { definition: 'Retraso en el pago de una deuda u obligación vencida. También puede designar el nivel o la tasa de pagos atrasados en un conjunto de operaciones.', synonyms: ['retraso en los pagos', 'incumplimiento de pago a su vencimiento', 'tasa de impagos o pagos atrasados'], example: { word: 'morosidad', text: 'El informe comparó la morosidad de los préstamos de consumo con la del año anterior.' }, exampleSynonym: { word: 'retraso en los pagos', text: 'El informe comparó el retraso en los pagos de los préstamos de consumo con el del año anterior.' } },
      monoparental: { definition: 'Dicho de una familia: formada por un solo progenitor y sus hijos, o relativo a ese tipo de familia. La expresión describe una estructura familiar y no presupone por qué está formada así.', synonyms: ['de una familia con un solo progenitor', 'relativo a familias monoparentales', 'de un solo padre o madre y sus hijos'], example: { word: 'monoparental', text: 'El programa ofrecía apoyo a hogares monoparentales con menores a cargo.' }, exampleSynonym: { word: 'de una familia con un solo progenitor', text: 'El programa ofrecía apoyo a hogares de una familia con un solo progenitor y menores a cargo.' } },
      mortalidad: { definition: 'Número de muertes ocurridas en una población y durante un periodo determinados; también, relación o tasa que expresa esas muertes respecto de la población considerada.', synonyms: ['número de defunciones', 'tasa de mortalidad', 'frecuencia de muertes en una población'], example: { word: 'mortalidad', text: 'El estudio comparó la mortalidad infantil de varias regiones durante el mismo periodo.' }, exampleSynonym: { word: 'tasa de mortalidad', text: 'El estudio comparó la tasa de mortalidad infantil de varias regiones durante el mismo periodo.' }, translation: { en: 'mortality' } },
      multar: { definition: 'Imponer una multa a una persona u organización por una infracción, cuando una autoridad u otra entidad facultada puede hacerlo conforme a las normas aplicables.', synonyms: ['imponer una multa', 'sancionar con una multa', 'castigar económicamente una infracción'], example: { word: 'multar', text: 'La autoridad puede multar a la empresa si confirma la infracción conforme al procedimiento aplicable.' }, exampleSynonym: { word: 'imponer una multa', text: 'La autoridad puede imponer una multa a la empresa si confirma la infracción conforme al procedimiento aplicable.' } },
      narcolepsia: { definition: 'Trastorno crónico del sueño y del sistema nervioso que suele causar somnolencia diurna excesiva y puede incluir episodios de sueño y, en algunas personas, cataplejía. Los síntomas varían; no todas las personas presentan los mismos.', synonyms: ['trastorno crónico del sueño con somnolencia diurna excesiva', 'trastorno de narcolepsia', 'enfermedad del ciclo sueño-vigilia'], example: { word: 'narcolepsia', text: 'La evaluación especializada consideró la narcolepsia entre las posibles causas de la somnolencia diurna persistente.' }, exampleSynonym: { word: 'trastorno crónico del sueño', text: 'La evaluación especializada consideró un trastorno crónico del sueño entre las posibles causas de la somnolencia diurna persistente.' } },
      natalidad: { definition: 'Frecuencia o número de nacimientos en una población y durante un periodo determinados. En demografía, las tasas de natalidad relacionan los nacimientos con el tamaño de la población según una medida definida.', synonyms: ['frecuencia de nacimientos', 'número de nacidos en una población', 'tasa de natalidad (medida demográfica)'], example: { word: 'natalidad', text: 'El estudio describió la natalidad de la región durante la última década.' }, exampleSynonym: { word: 'frecuencia de nacimientos', text: 'El estudio describió la frecuencia de nacimientos de la región durante la última década.' } }
    },
    en: {
      'statute-of-limitations': { definition: 'A law that sets a time limit for starting a legal claim or prosecution. The applicable period, exceptions, and rules for pausing or extending it vary by jurisdiction and type of matter; some claims or offenses may have no such limit.', synonyms: ['limitation period', 'time limit for bringing a claim', 'prescriptive period (in some legal systems)'], example: { word: 'statute of limitations', text: 'Counsel checked the applicable statute of limitations and any rules that might pause its running.' }, exampleSynonym: { word: 'limitation period', text: 'Counsel checked the applicable limitation period and any rules that might pause its running.' }, translation: { es: 'prescripcion' } },
      'forensic-expert': { definition: 'A person with specialized scientific, technical, medical, or other expertise who examines evidence or addresses questions relevant to legal proceedings. The expert’s role and duties depend on the jurisdiction and proceeding.', synonyms: ['forensic specialist', 'expert witness in forensic matters', 'court-appointed technical expert (in some systems)'], example: { word: 'forensic expert', text: 'The forensic expert explained the laboratory findings and the limits of the analysis.' }, exampleSynonym: { word: 'forensic specialist', text: 'The forensic specialist explained the laboratory findings and the limits of the analysis.' } },
      'co-ownership': { definition: 'Ownership of the same property by two or more people or entities. The owners’ shares may be defined or undivided, and their rights and responsibilities depend on the agreement and applicable law.', synonyms: ['joint ownership', 'shared ownership', 'ownership held by multiple parties'], example: { word: 'co-ownership', text: 'The agreement set out each party’s share and responsibilities under the co-ownership.' }, exampleSynonym: { word: 'joint ownership', text: 'The agreement set out each party’s share and responsibilities under the joint ownership.' } },
      protectionism: { definition: 'A policy approach that seeks to shield domestic industries or producers from foreign competition. Measures may include tariffs, quotas, subsidies, or other restrictions on trade.', synonyms: ['trade protection', 'policy protecting domestic producers', 'restriction of foreign competition'], example: { word: 'protectionism', text: 'The debate considered whether the proposed tariffs would amount to protectionism.' }, exampleSynonym: { word: 'trade protection', text: 'The debate considered whether the proposed tariffs would amount to trade protection.' } },
      'draft-bill': { definition: 'A proposed piece of legislation in draft form. It may be published, consulted on, or formally introduced before legislative debate; its procedural status varies by jurisdiction.', synonyms: ['draft legislation', 'proposed bill', 'legislative proposal in draft form'], example: { word: 'draft bill', text: 'The ministry published a draft bill for public comment before introducing it in parliament.' }, exampleSynonym: { word: 'draft legislation', text: 'The ministry published draft legislation for public comment before introducing it in parliament.' } },
      psychosomatic: { definition: 'Relating to interactions between psychological factors and bodily processes or symptoms. Psychosomatic symptoms are real; the term does not by itself mean that a symptom is imaginary or rule out a physical disease.', synonyms: ['involving mind–body interactions', 'relating psychological factors to bodily symptoms', 'psychophysiological (in some contexts)'], example: { word: 'psychosomatic', text: 'The clinician discussed how stress could contribute to the symptoms while continuing to assess other possible causes.' }, exampleSynonym: { word: 'involving mind–body interactions', text: 'The clinician discussed how mind–body interactions could contribute to the symptoms while continuing to assess other possible causes.' } },
      rezoning: { definition: 'The official change of a property’s zoning classification or applicable land-use rules, which can alter permitted uses, density, or development requirements. Procedures and effects depend on the jurisdiction.', synonyms: ['zoning change', 'change in land-use designation', 'amendment of zoning regulations'], example: { word: 'rezoning', text: 'The council considered rezoning the site to allow a mix of residential and commercial uses.' }, exampleSynonym: { word: 'zoning change', text: 'The council considered a zoning change to allow a mix of residential and commercial uses.' } },
      'social-reintegration': { definition: 'The process of supporting a person’s return to and participation in community or social life after exclusion, displacement, incarceration, or time in an institution. The support needed depends on the person and circumstances.', synonyms: ['reintegration into the community', 'return to social participation', 'community reintegration'], example: { word: 'social reintegration', text: 'The programme offered housing and employment support as part of social reintegration after release.' }, exampleSynonym: { word: 'reintegration into the community', text: 'The programme offered housing and employment support for reintegration into the community after release.' } },
      'land-readjustment': { definition: 'A land-development method in which landowners pool or contribute parcels so an authority or project can reorganize the area, provide infrastructure, and allocate reconfigured plots back to owners. Some land may be reserved for roads or public facilities; arrangements vary.', synonyms: ['land pooling and replotting', 'land replotting for urban development', 'land readjustment scheme'], example: { word: 'land readjustment', text: 'The land-readjustment plan reconfigured parcels and reserved space for roads and public facilities.' }, exampleSynonym: { word: 'land pooling and replotting', text: 'The land-pooling and replotting plan reconfigured parcels and reserved space for roads and public facilities.' } },
      'compensation-for-damages': { definition: 'A remedy or payment intended to address harm or loss. Compensation may be monetary or take another legally available form, and entitlement and amount depend on the facts and applicable law.', synonyms: ['damages', 'compensation for loss or injury', 'reparation for harm'], example: { word: 'compensation for damages', text: 'The claimant sought compensation for damages allegedly caused by the breach.' }, exampleSynonym: { word: 'compensation for loss or injury', text: 'The claimant sought compensation for loss allegedly caused by the breach.' } }
    }
  };
  for (const [lang, rows] of Object.entries(updates)) for (const [id, fields] of Object.entries(rows)) {
    const row = window.DICCIONARIOS[lang].find(item => item.id === id);
    if (!row) throw new Error(`Missing ${lang}:${id}`);
    Object.assign(row, fields);
  }
})();

