      anaemia: { definition: 'British spelling of anemia: a condition in which the blood has too few healthy red blood cells or too little hemoglobin to carry enough oxygen to the body’s tissues.', synonyms: ['anemia (US spelling)', 'low red blood cell or hemoglobin condition', 'anaemia (British spelling)'], example: { word: 'anaemia', text: 'The blood test helped determine whether the patient had anaemia.' }, exampleSynonym: { word: 'anemia', text: 'The blood test helped determine whether the patient had anemia.' }, translation: { es: 'anemia' } },
