// Corrections from the entry-by-entry review of Spanish and English batch 996.
(function () {
  const updates = {
    es: {
      tetanos: { definition: 'Enfermedad grave causada por una toxina producida por la bacteria Clostridium tetani. La bacteria puede entrar en el organismo por una herida y la toxina provoca rigidez y espasmos musculares; no se transmite de persona a persona.', synonyms: ['infección por Clostridium tetani', 'enfermedad causada por la toxina tetánica', 'tétanos generalizado (forma clínica)'], example: { word: 'tétanos', text: 'La vacuna protege frente al tétanos, que puede aparecer después de una herida contaminada.' }, exampleSynonym: { word: 'enfermedad causada por la toxina tetánica', text: 'La vacuna protege frente a la enfermedad causada por la toxina tetánica, que puede aparecer después de una herida contaminada.' }, translation: { en: 'tetanus' } },
      titularidad: { definition: 'Condición de titular de un derecho, bien, cuenta, cargo o relación jurídica; indica quién figura o está reconocido como titular, aunque no siempre coincida con quien posee o controla materialmente el bien.', synonyms: ['condición de titular de un derecho o bien', 'atribución formal de la titularidad', 'propiedad o titularidad registrada (según el contexto)'], example: { word: 'titularidad', text: 'La entidad pidió documentos para acreditar la titularidad de la cuenta.' }, exampleSynonym: { word: 'condición de titular', text: 'La entidad pidió documentos para acreditar la condición de titular de la cuenta.' } },
      tomografia: { definition: 'Técnica de diagnóstico por imagen que produce representaciones de secciones o cortes del interior del cuerpo. La tomografía computarizada utiliza rayos X; otras técnicas tomográficas pueden basarse en distintos principios físicos.', synonyms: ['técnica de imagen por secciones', 'exploración tomográfica', 'tomografía computarizada (un tipo)'], example: { word: 'tomografía', text: 'El equipo solicitó una tomografía para obtener imágenes detalladas de la zona.' }, exampleSynonym: { word: 'exploración tomográfica', text: 'El equipo solicitó una exploración tomográfica para obtener imágenes detalladas de la zona.' } },
      tiroides: { definition: 'Glándula endocrina situada en la parte anterior del cuello que produce hormonas tiroideas y otras sustancias que participan en la regulación del metabolismo, el crecimiento y varias funciones corporales.', synonyms: ['glándula tiroidea', 'glándula endocrina del cuello', 'órgano productor de hormonas tiroideas'], example: { word: 'tiroides', text: 'Los análisis evaluaron la función de la tiroides.' }, exampleSynonym: { word: 'glándula tiroidea', text: 'Los análisis evaluaron la función de la glándula tiroidea.' } },
      tosferina: { definition: 'Infección respiratoria muy contagiosa causada por la bacteria Bordetella pertussis. Puede comenzar con síntomas parecidos a un resfriado y luego producir accesos de tos prolongados; puede ser especialmente grave en bebés.', synonyms: ['pertussis', 'tos convulsiva', 'infección por Bordetella pertussis'], example: { word: 'tosferina', text: 'La vacunación ayuda a prevenir la tosferina y sus complicaciones.' }, exampleSynonym: { word: 'pertussis', text: 'La vacunación ayuda a prevenir la pertussis y sus complicaciones.' }, translation: { en: 'pertussis' } },
      traumatismo: { definition: 'Lesión o daño corporal causado por un agente externo, como un golpe, una caída, una colisión o una herida. También puede referirse al hecho o mecanismo que causa la lesión.', synonyms: ['lesión traumática', 'daño corporal por una fuerza externa', 'trauma físico'], example: { word: 'traumatismo', text: 'El equipo evaluó si el traumatismo había afectado órganos internos.' }, exampleSynonym: { word: 'lesión traumática', text: 'El equipo evaluó si la lesión traumática había afectado órganos internos.' } },
      traumatologo: { definition: 'Médico especialista en la evaluación y tratamiento de lesiones y trastornos del aparato locomotor, incluidos huesos, articulaciones, ligamentos, tendones y músculos. La formación y el alcance de la especialidad varían por país.', synonyms: ['especialista en traumatología', 'médico de lesiones musculoesqueléticas', 'cirujano ortopédico o traumatólogo (según el sistema)'], example: { word: 'traumatólogo', text: 'El traumatólogo evaluó la lesión de la rodilla y explicó las opciones de tratamiento.' }, exampleSynonym: { word: 'especialista en traumatología', text: 'El especialista en traumatología evaluó la lesión de la rodilla y explicó las opciones de tratamiento.' } },
      trombosis: { definition: 'Formación de un trombo o coágulo dentro de un vaso sanguíneo o, en algunos usos, en el corazón. Puede obstruir parcial o totalmente el flujo sanguíneo y tener consecuencias distintas según su ubicación.', synonyms: ['formación de un trombo', 'coágulo dentro de un vaso sanguíneo', 'oclusión vascular por trombo (cuando ocurre)'], example: { word: 'trombosis', text: 'Las pruebas determinaron la ubicación y extensión de la trombosis.' }, exampleSynonym: { word: 'formación de un trombo', text: 'Las pruebas determinaron la ubicación y extensión de la formación de un trombo.' } },
      trasplantar: { definition: 'Trasladar un órgano, tejido o células a otro lugar del cuerpo o a otra persona para sustituir, reparar o restablecer una función; también, cambiar una planta de lugar. La técnica y los requisitos dependen del caso.', synonyms: ['realizar un trasplante', 'implantar un órgano o tejido', 'cambiar una planta de lugar'], example: { word: 'trasplantar', text: 'El equipo decidió trasplantar tejido para reparar la zona lesionada.' }, exampleSynonym: { word: 'realizar un trasplante', text: 'El equipo decidió realizar un trasplante de tejido para reparar la zona lesionada.' }, translation: { en: 'transplant' } },
      transfobia: { definition: 'Prejuicio, rechazo, hostilidad o discriminación dirigidos contra las personas trans o contra quienes no se ajustan a las expectativas tradicionales sobre género. Puede manifestarse en actitudes, conductas, políticas o barreras institucionales.', synonyms: ['prejuicio contra las personas trans', 'discriminación por identidad o expresión de género', 'hostilidad hacia las personas trans'], example: { word: 'transfobia', text: 'La organización adoptó medidas para prevenir la transfobia y atender las denuncias.' }, exampleSynonym: { word: 'discriminación por identidad de género', text: 'La organización adoptó medidas para prevenir la discriminación por identidad de género y atender las denuncias.' } }
    },
    en: {
      'labor-union': { definition: 'An organization of workers formed to protect or improve members’ economic and social interests through collective action, including negotiation with employers. Members may work in one occupation, across occupations, or in related sectors.', synonyms: ['trade union', 'workers’ organization', 'labor organization'], example: { word: 'labor union', text: 'The labor union negotiated with the employer over wages and workplace safety.' }, exampleSynonym: { word: 'workers’ organization', text: 'The workers’ organization negotiated with the employer over wages and workplace safety.' }, translation: { es: 'sindicato' } },
      'minimum-wage': { definition: 'The lowest remuneration that an employer is legally required to pay covered workers for work performed during a specified period. It may be set hourly, daily, monthly, or by another method, and coverage and rates vary by jurisdiction.', synonyms: ['statutory minimum pay', 'minimum legally required remuneration', 'wage floor'], example: { word: 'minimum wage', text: 'The new minimum wage took effect at the start of the year.' }, exampleSynonym: { word: 'statutory minimum pay', text: 'The new statutory minimum pay took effect at the start of the year.' }, translation: { es: 'salario-minimo' } },
      icterus: { definition: 'A medical term for jaundice: yellow discoloration of the skin and whites of the eyes caused by increased bilirubin in the blood. It is a sign with several possible causes, not a diagnosis of one disease.', synonyms: ['jaundice', 'yellow discoloration from raised bilirubin', 'icteric condition'], example: { word: 'icterus', text: 'The clinician assessed the icterus and ordered tests to investigate its cause.' }, exampleSynonym: { word: 'jaundice', text: 'The clinician assessed the jaundice and ordered tests to investigate its cause.' }, translation: { es: 'ictericia' } },
      judgment: { definition: 'The ability to form an opinion or decision; a formal decision by a court or judge; or the act of judging. In legal use, a judgment determines matters submitted to the court, with effects that depend on the proceeding and jurisdiction.', synonyms: ['court decision or ruling', 'discernment or decision-making ability', 'act of judging'], example: { word: 'judgment', text: 'The court issued a judgment explaining its decision and the parties’ obligations.' }, exampleSynonym: { word: 'ruling', text: 'The court issued a ruling explaining its decision and the parties’ obligations.' }, translation: { es: 'juicio' } },
      sober: { definition: 'Not affected by alcohol or other intoxicating substances; also, serious, restrained, or clear-headed in manner or judgment.', synonyms: ['not intoxicated', 'abstaining from alcohol (context-dependent)', 'serious or restrained'], example: { word: 'sober', text: 'The report called for a sober assessment of the available evidence.' }, exampleSynonym: { word: 'clear-headed', text: 'The report called for a clear-headed assessment of the available evidence.' }, translation: { es: 'sobrio' } },
      resource: { definition: 'A useful source of supply, support, or assistance; an asset, material, person, or capability that can be used to achieve an objective. The word also has specific meanings in computing, education, and law.', synonyms: ['source of support or supply', 'useful asset or capability', 'available means for achieving a goal'], example: { word: 'resource', text: 'The library is a valuable resource for students and local researchers.' }, exampleSynonym: { word: 'source of support', text: 'The library is a valuable source of support for students and local researchers.' }, translation: { es: 'recurso' } },
      demandant: { definition: 'A party who brings a claim or demands relief in a legal proceeding, especially in some civil-law systems. The word is uncommon in general English, where claimant or plaintiff is usually preferred depending on the jurisdiction.', synonyms: ['claimant (general equivalent)', 'plaintiff (in some systems)', 'party bringing a legal claim'], example: { word: 'demandant', text: 'The demandant asked the court to review the disputed decision.' }, exampleSynonym: { word: 'claimant', text: 'The claimant asked the court to review the disputed decision.' }, translation: { es: 'demandante' } },
      offence: { definition: 'An act that breaks a law, rule, or accepted standard; in legal usage, a criminal or regulatory violation. Offence is the standard British spelling; offense is standard in American English.', synonyms: ['offense (US spelling)', 'crime (criminal-law context)', 'violation of a rule or law'], example: { word: 'offence', text: 'The law defines the offence and sets out the possible penalties.' }, exampleSynonym: { word: 'violation', text: 'The law defines the violation and sets out the possible penalties.' }, translation: { es: 'delito' } },
      pain: { definition: 'An unpleasant physical sensation or emotional distress. The term also appears in idioms and phrases, but it is not synonymous with a legal penalty or punishment.', synonyms: ['ache or bodily suffering', 'physical discomfort', 'emotional distress (figurative sense)'], example: { word: 'pain', text: 'The patient described where the pain began and how it changed over time.' }, exampleSynonym: { word: 'ache', text: 'The patient described where the ache began and how it changed over time.' }, translation: null },
      penalty: { definition: 'A punishment or other adverse consequence imposed for breaking a law, rule, or agreement; in sports, a consequence for a rule violation; or a sum payable under specified conditions. Legal forms vary by jurisdiction.', synonyms: ['sanction', 'punishment for a violation', 'fine or contractual charge (specific contexts)'], example: { word: 'penalty', text: 'The regulator imposed a penalty for failing to meet the reporting requirement.' }, exampleSynonym: { word: 'sanction', text: 'The regulator imposed a sanction for failing to meet the reporting requirement.' }, translation: { es: 'pena' } }
    }
  };
  for (const [lang, rows] of Object.entries(updates)) for (const [id, fields] of Object.entries(rows)) {
    const row = window.DICCIONARIOS[lang].find(item => item.id === id);
    if (!row) throw new Error(`Missing ${lang}:${id}`);
    const { translation, ...otherFields } = fields;
    Object.assign(row, otherFields);
    if (translation === null) delete row.translation;
    else if (translation) row.translation = translation;
  }
})();


