;(()=>{const updates={"en":{"solvable":{"definition":"Capable of being solved or resolved, especially a problem, equation, or dispute.","synonyms":["resolvable","capable of being solved"],"example":{"word":"solvable","text":"The puzzle looked difficult, but it was solvable with careful reasoning."},"exampleSynonym":{"word":"resolvable","text":"The puzzle looked difficult, but it was resolvable with careful reasoning."}},"performance":{"definition":"The act or process of carrying something out; the quality or results of how a person, machine, or organization functions; also, a public presentation of music, drama, or another art.","synonyms":["execution","effectiveness","presentation"],"example":{"word":"performance","text":"The company reported stronger financial performance this year."},"exampleSynonym":{"word":"financial results","text":"The company reported stronger financial results this year."}},"aggression":{"definition":"Hostile, threatening, or forceful behavior, especially an unprovoked attack or an attempt to dominate or harm another person or group.","synonyms":["hostility","attack","belligerence"],"example":{"word":"aggression","text":"The mediator asked both sides to avoid aggression during the talks."},"exampleSynonym":{"word":"hostility","text":"The mediator asked both sides to avoid hostility during the talks."}},"explosible":{"definition":"Capable of exploding under particular conditions; a technical adjective used especially of substances or mixtures that can form an explosive atmosphere.","synonyms":["capable of exploding","explosive"],"example":{"word":"explosible","text":"The safety manual explains how to handle explosible dust in the plant."},"exampleSynonym":{"word":"explosive","text":"The safety manual explains how to handle explosive dust in the plant."}},"plane":{"definition":"Flat and level; also, a flat surface or level in geometry, a tool for smoothing wood, or an aircraft. The intended sense depends on context.","synonyms":["flat","level","aircraft"],"example":{"word":"plane","text":"The carpenter used a plane to smooth the edge of the door."},"exampleSynonym":{"word":"tool for smoothing wood","text":"The carpenter used a tool for smoothing wood to smooth the edge of the door."}},"trainee":{"definition":"A person receiving instruction or practical experience to learn a job, skill, or profession; an apprentice is a more specific kind of trainee in some trades.","synonyms":["learner","person in training"],"example":{"word":"trainee","text":"Each trainee completed a safety course before starting work."},"exampleSynonym":{"word":"person in training","text":"Each person in training completed a safety course before starting work."}},"breach-of-contract":{"definition":"A failure, without a valid legal excuse, to perform an obligation required by a contract; the consequences depend on the agreement and applicable law.","synonyms":["contractual breach","failure to perform a contract"],"example":{"word":"breach of contract","text":"The supplier’s repeated failure to deliver the goods led to a breach of contract claim."},"exampleSynonym":{"word":"contractual breach","text":"The supplier’s repeated failure to deliver the goods led to a contractual breach claim."}},"customs-officer":{"definition":"A government official who checks goods and, where applicable, travelers crossing a border and enforces customs rules on imports and exports.","synonyms":["customs agent","border customs official"],"example":{"word":"customs officer","text":"A customs officer inspected the shipment before it entered the country."},"exampleSynonym":{"word":"customs agent","text":"A customs agent inspected the shipment before it entered the country."}},"affection":{"definition":"A feeling of fondness, liking, or tender attachment; in older or specialized usage, a physical or mental condition or an influence that acts on something.","synonyms":["fondness","tenderness","attachment"],"example":{"word":"affection","text":"She spoke of her grandmother with deep affection."},"exampleSynonym":{"word":"fondness","text":"She spoke of her grandmother with deep fondness."}},"acquisition":{"definition":"The act of obtaining or learning something, or the thing obtained; in business, the purchase of one company or asset by another.","synonyms":["purchase","procurement","attainment"],"example":{"word":"acquisition","text":"The acquisition of the smaller firm expanded the company’s regional network."},"exampleSynonym":{"word":"purchase","text":"The purchase of the smaller firm expanded the company’s regional network."}}}};for(const [id,fields] of Object.entries(updates.en)){const row=window.DICCIONARIOS.en.find(x=>x.id===id);if(!row)throw Error('Missing en:'+id);Object.assign(row,fields);}})();

;(()=>{const updates={"en":{"gathering":{"definition":"An act or process of collecting or bringing things together; a group or meeting of people assembled for a purpose or social occasion.","synonyms":["meeting","assembly","collection"],"example":{"word":"gathering","text":"The annual gathering brought researchers from several countries together."},"exampleSynonym":{"word":"meeting","text":"The annual meeting brought researchers from several countries together."}},"aggressor":{"definition":"A person, group, or state that initiates an attack or hostile action; in a conflict, the party that starts the aggression.","synonyms":["attacker","assailant","instigator"],"example":{"word":"aggressor","text":"Investigators identified the aggressor from the security footage."},"exampleSynonym":{"word":"attacker","text":"Investigators identified the attacker from the security footage."}},"argument":{"definition":"A reason or set of reasons offered to support a conclusion; also, a disagreement or heated exchange between people.","synonyms":["reasoning","case","dispute"],"example":{"word":"argument","text":"Her argument for extending the library hours persuaded the committee."},"exampleSynonym":{"word":"case","text":"Her case for extending the library hours persuaded the committee."}},"storage":{"definition":"The act or process of keeping something for later use, the space or facility where it is kept, or the capacity and systems used to retain digital data.","synonyms":["keeping","warehousing","data retention"],"example":{"word":"storage","text":"The archive uses secure cloud storage for its digital records."},"exampleSynonym":{"word":"data retention","text":"The archive uses secure cloud data retention for its digital records."}},"amnesia":{"definition":"A loss or impairment of memory, often caused by illness, injury, or psychological factors; it may affect memories of past events or the ability to form new ones.","synonyms":["memory loss","memory impairment"],"example":{"word":"amnesia","text":"After the injury, he experienced temporary amnesia and could not recall the accident."},"exampleSynonym":{"word":"memory loss","text":"After the injury, he experienced temporary memory loss and could not recall the accident."}},"illiterate":{"definition":"Unable to read and write; by extension, lacking basic knowledge or competence in a particular subject. The term can be stigmatizing when used about people, so more specific wording may be preferable.","synonyms":["unable to read and write","unlettered"],"example":{"word":"illiterate","text":"The survey measures access to literacy programs for adults who are illiterate."},"exampleSynonym":{"word":"unable to read and write","text":"The survey measures access to literacy programs for adults who are unable to read and write."}},"autism":{"definition":"A neurodevelopmental condition involving differences in social communication and interaction and patterns of behavior, interests, or sensory experience; autistic people have varied abilities and support needs.","synonyms":["autism spectrum disorder","ASD"],"example":{"word":"autism","text":"The center offers communication support tailored to each autistic person."},"exampleSynonym":{"word":"autism spectrum disorder","text":"The center offers communication support tailored to each person with autism spectrum disorder."}},"self-esteem":{"definition":"A person’s overall sense of their own worth or value, including how they regard and respect themselves.","synonyms":["self-worth","self-respect"],"example":{"word":"self-esteem","text":"Encouragement from her coach helped build her self-esteem."},"exampleSynonym":{"word":"self-worth","text":"Encouragement from her coach helped build her sense of self-worth."}},"range":{"definition":"A span or extent between limits; a variety or series of things; a line of mountains; a cooking appliance; or, as a verb, to vary or extend between points. Context determines the sense.","synonyms":["span","variety","series","mountain chain"],"example":{"word":"range","text":"The store offers a wide range of sizes and colors."},"exampleSynonym":{"word":"variety","text":"The store offers a wide variety of sizes and colors."}},"teetotaller":{"definition":"A person who does not drink alcohol; teetotaller is the usual British spelling, while teetotaler is the usual American spelling.","synonyms":["total abstainer","teetotaler"],"example":{"word":"teetotaller","text":"As a teetotaller, she chose a non-alcoholic drink at the reception."},"exampleSynonym":{"word":"total abstainer","text":"As a total abstainer, she chose a non-alcoholic drink at the reception."}}}};for(const [id,fields] of Object.entries(updates.en)){const row=window.DICCIONARIOS.en.find(x=>x.id===id);if(!row)throw Error('Missing en:'+id);Object.assign(row,fields);}})();

;(()=>{const updates={"en":{"accessible":{"definition":"Able to be reached, entered, used, or obtained; designed for use by people with disabilities; or easy to understand or approach, depending on context.","synonyms":["usable","easy to reach","easy to understand"],"example":{"word":"accessible","text":"The museum is accessible to wheelchair users and visitors with limited mobility."},"exampleSynonym":{"word":"usable","text":"The museum is usable by wheelchair users and visitors with limited mobility."}},"attainable":{"definition":"Possible to achieve, reach, or obtain, especially through effort or planning.","synonyms":["achievable","feasible","within reach"],"example":{"word":"attainable","text":"With steady practice, the target was challenging but attainable."},"exampleSynonym":{"word":"achievable","text":"With steady practice, the target was challenging but achievable."},"translation":{"es":"alcanzable"}},"approachable":{"definition":"Easy to reach or get near; of a person, friendly and easy to talk to; of a subject or style, accessible and not overly difficult.","synonyms":["easy to talk to","friendly","easy to reach"],"example":{"word":"approachable","text":"The new director is approachable and welcomes questions from staff."},"exampleSynonym":{"word":"friendly","text":"The new director is friendly and welcomes questions from staff."}},"obey":{"definition":"To do what a person, law, rule, or instruction requires; to comply with or follow an order or requirement.","synonyms":["comply with","follow","abide by"],"example":{"word":"obey","text":"All drivers must obey the posted speed limit."},"exampleSynonym":{"word":"comply with","text":"All drivers must comply with the posted speed limit."}},"abide-by":{"definition":"To accept and act in accordance with a rule, agreement, decision, or requirement.","synonyms":["comply with","follow","observe"],"example":{"word":"abide by","text":"Both parties agreed to abide by the terms of the settlement."},"exampleSynonym":{"word":"comply with","text":"Both parties agreed to comply with the terms of the settlement."}},"stalk":{"definition":"As a noun, the main stem of a plant or a slender supporting part; as a verb, to follow or approach someone or an animal stealthily, or to persistently harass a person.","synonyms":["stem","follow stealthily","harass"],"example":{"word":"stalk","text":"The documentary explains how a predator may stalk its prey before attacking."},"exampleSynonym":{"word":"follow stealthily","text":"The documentary explains how a predator may follow its prey stealthily before attacking."}},"waylay":{"definition":"To stop or intercept someone unexpectedly, often in order to question, confront, or attack them.","synonyms":["intercept","ambush","stop unexpectedly"],"example":{"word":"waylay","text":"Reporters tried to waylay the spokesperson outside the hearing."},"exampleSynonym":{"word":"intercept","text":"Reporters tried to intercept the spokesperson outside the hearing."}},"enclose":{"definition":"To surround or close off an area; to put something inside an envelope, package, or container; or to include an item with a letter or document.","synonyms":["surround","encircle","include"],"example":{"word":"enclose","text":"Please enclose a copy of the receipt with your application."},"exampleSynonym":{"word":"include","text":"Please include a copy of the receipt with your application."}},"adulteration":{"definition":"The act or result of making food, medicine, or another substance impure or lower in quality, often by adding an inferior, harmful, or undeclared ingredient.","synonyms":["contamination","dilution","tampering"],"example":{"word":"adulteration","text":"Inspectors detected the adulteration of the cooking oil with a cheaper substance."},"exampleSynonym":{"word":"contamination","text":"Inspectors detected the contamination of the cooking oil with a cheaper substance."}},"aphonia":{"definition":"Loss of the ability to produce a normal voice, usually because of a problem affecting the larynx or vocal cords; it does not necessarily mean loss of the ability to whisper or communicate.","synonyms":["loss of voice","voice loss"],"example":{"word":"aphonia","text":"The singer developed temporary aphonia after straining her voice."},"exampleSynonym":{"word":"loss of voice","text":"The singer developed a temporary loss of voice after straining it."}}}};for(const [id,fields] of Object.entries(updates.en)){const row=window.DICCIONARIOS.en.find(x=>x.id===id);if(!row)throw Error('Missing en:'+id);Object.assign(row,fields);}})();

