;(()=>{const rows=window.DICCIONARIOS.en;const updates={"big-mouthed":{"definition":"Having a large mouth; informally, speaking too freely, loudly, or indiscreetly.","synonyms":["large-mouthed","loudmouthed","bigmouthed"],"example":{"word":"big-mouthed","text":"The big-mouthed fish swallowed the bait at once."},"exampleSynonym":{"word":"large-mouthed","text":"The large-mouthed fish swallowed the bait at once."},"translation":{"es":"bocudo; bocazas (informal)"}},"still-life":{"word":"still life","definition":"A painting, drawing, or photograph of inanimate objects arranged as the subject, such as food, flowers, or household items.","synonyms":["still-life painting","arranged-object composition"],"example":{"word":"still life","text":"The still life showed fruit and a pitcher on the table."},"exampleSynonym":{"word":"still-life painting","text":"The still-life painting showed fruit and a pitcher on the table."},"translation":{"es":"bodegón; naturaleza muerta"}},"bohrium":{"definition":"A short-lived radioactive chemical element produced artificially, with symbol Bh and atomic number 107.","synonyms":["element 107","Bh"],"example":{"word":"bohrium","text":"Bohrium is an artificially produced element with short-lived isotopes."},"exampleSynonym":{"word":"element 107","text":"Element 107 is artificially produced and has short-lived isotopes."},"translation":{"es":"bohrio"}},"bolas":{"definition":"A cord or set of cords with weights attached to the ends, thrown to entangle an animal’s legs; bolas is the usual plural and also a variant form.","synonyms":["bola","throwing weapon"],"example":{"word":"bolas","text":"The gaucho threw the bolas to entangle the animal’s legs."},"exampleSynonym":{"word":"throwing weapon","text":"The gaucho threw the throwing weapon to entangle the animal’s legs."},"translation":{"es":"boleadoras; bolas"}},"waste-time":{"word":"waste time","definition":"To spend time unproductively or without making useful progress; in some varieties of South American Spanish, a slang equivalent is boludear.","synonyms":["fool around","idle","dawdle"],"example":{"word":"waste time","text":"Stop wasting time and finish the work."},"exampleSynonym":{"word":"fool around","text":"Stop fooling around and finish the work."},"translation":{"es":"perder el tiempo; holgazanear; boludear (coloquial, regional)"}},"borax":{"definition":"A hydrated sodium borate, usually a white crystalline mineral or prepared compound, used in cleaning, metalworking, and other applications.","synonyms":["sodium borate","tincal"],"example":{"word":"borax","text":"The cleaner used borax to help remove the stain."},"exampleSynonym":{"word":"sodium borate","text":"The cleaner used sodium borate to help remove the stain."},"translation":{"es":"bórax; borato de sodio"}},"borborygmus":{"definition":"A rumbling or gurgling sound in the intestines, caused by movement of gas and fluid.","synonyms":["intestinal rumbling","stomach rumble"],"example":{"word":"borborygmus","text":"The doctor heard a borborygmus during the examination."},"exampleSynonym":{"word":"intestinal rumbling","text":"The doctor heard intestinal rumbling during the examination."},"translation":{"es":"borborigmo; ruido intestinal"}},"boron":{"definition":"A chemical element with symbol B and atomic number 5; it is a metalloid that occurs in compounds and has several crystalline and amorphous forms.","synonyms":["element B","chemical element"],"example":{"word":"boron","text":"Boron is added to some glass to improve its heat resistance."},"exampleSynonym":{"word":"chemical element","text":"The chemical element is added to some glass to improve its heat resistance."},"translation":{"es":"boro"}},"crumb":{"definition":"A small fragment of bread or another baked food; by extension, a very small piece or amount. It can also refer to the soft inner part of bread.","synonyms":["morsel","small fragment","bit"],"example":{"word":"crumb","text":"A crumb fell from the cornbread onto the table."},"exampleSynonym":{"word":"small fragment","text":"A small fragment fell from the cornbread onto the table."},"translation":{"es":"miga; migaja; fragmento pequeño"}},"lamb":{"definition":"Noun: a young sheep, especially one less than a year old; also its meat or skin, and figuratively a gentle or vulnerable person. Verb: for a sheep to give birth.","synonyms":["young sheep","lamb meat","give birth (of a sheep)"],"example":{"word":"lamb","text":"The lamb stayed close to its mother in the pasture."},"exampleSynonym":{"word":"young sheep","text":"The young sheep stayed close to its mother in the pasture."},"translation":{"es":"cordero; oveja joven; parir (una oveja)"}}};for(const [id,data]of Object.entries(updates)){const row=rows.find(entry=>entry.id===id);if(!row)throw new Error('Missing dictionary entry: '+id);Object.assign(row,data);}})();

