;(()=>{const updates={"kaolin":{"definition":"A fine white clay composed chiefly of kaolinite, used in making porcelain, paper, paint, and other products; also called china clay.","synonyms":["china clay","kaolinite-rich clay"],"example":{"word":"kaolin","text":"The potter mixed kaolin with other minerals to make porcelain."},"exampleSynonym":{"word":"china clay","text":"The potter mixed china clay with other minerals to make porcelain."},"translation":{"es":"caolín; arcilla china"}},"castrate":{"definition":"To remove the testicles of a male person or animal; more generally, to sterilize an animal or deprive something of its force or effectiveness.","synonyms":["geld (animals)","neuter","sterilize"],"example":{"word":"castrate","text":"The veterinarian advised the owners to castrate the young bull."},"exampleSynonym":{"word":"geld","text":"The veterinarian advised the owners to geld the young bull."},"translation":{"es":"castrar; capar; esterilizar (animales)"}},"captious":{"definition":"(Formal.) Inclined to find fault or raise trivial objections; fault-finding and overly critical.","synonyms":["fault-finding","carping","nitpicking"],"example":{"word":"captious","text":"The captious reviewer objected to minor details in every chapter."},"exampleSynonym":{"word":"fault-finding","text":"The fault-finding reviewer objected to minor details in every chapter."},"translation":{"es":"quisquilloso; puntilloso; inclinado a criticar"}},"sophistical":{"definition":"Seemingly plausible but subtly fallacious or misleading; based on sophistry.","synonyms":["specious","fallacious","deceptive"],"example":{"word":"sophistical","text":"The argument sounded convincing but relied on sophistical reasoning."},"exampleSynonym":{"word":"specious","text":"The argument sounded convincing but relied on specious reasoning."},"translation":{"es":"sofístico; engañosamente plausible; falaz"}},"capybara":{"definition":"A large semiaquatic South American rodent (Hydrochoerus hydrochaeris), the largest living rodent, found near rivers, lakes, and wetlands.","synonyms":["carpincho","water hog"],"example":{"word":"capybara","text":"A capybara rested on the riverbank beside its group."},"exampleSynonym":{"word":"carpincho","text":"A carpincho rested on the riverbank beside its group."},"translation":{"es":["capibara","carpincho"]}},"capitoline":{"definition":"Of or relating to the Capitoline Hill in Rome, the Capitol, or the temples and institutions located there.","synonyms":["Capitolinian","of the Capitol"],"example":{"word":"Capitoline","text":"The Capitoline temple stood on one of Rome’s seven hills."},"exampleSynonym":{"word":"Capitolinian","text":"The Capitolinian temple stood on one of Rome’s seven hills."},"translation":{"es":"capitolino; relativo al Capitolio o al monte Capitolino"}},"mince":{"definition":"(Verb) To cut or chop food into very small pieces; to soften or disguise words or actions, as in “mince words.” (Noun) Finely chopped food, especially meat.","synonyms":["chop finely","minced meat","soften one’s words"],"example":{"word":"mince","text":"Mince the meat finely, but do not mince words when you explain the problem."},"exampleSynonym":{"word":"chop finely","text":"Chop the meat finely, but speak plainly when you explain the problem."},"translation":{"es":"picar muy fino; carne picada; andarse con rodeos"}},"chokeberry":{"definition":"A shrub of the genus Aronia, especially the red or black chokeberry (Aronia arbutifolia or A. melanocarpa), native to eastern North America; also, its tart fruit.","synonyms":["Aronia berry","black chokeberry"],"example":{"word":"chokeberry","text":"The chokeberry shrub produced clusters of dark, tart fruit."},"exampleSynonym":{"word":"Aronia berry","text":"The Aronia berry shrub produced clusters of dark, tart fruit."},"translation":{"es":"aronia; fruto del serbal de los cazadores"}},"tawny-owl":{"definition":"A medium-sized nocturnal owl (Strix aluco) with dark eyes and mottled brown or gray plumage, native to Europe and parts of Asia.","synonyms":["brown owl","Strix aluco"],"example":{"word":"tawny owl","text":"A tawny owl called from the trees after sunset."},"exampleSynonym":{"word":"brown owl","text":"A brown owl called from the trees after sunset."},"translation":{"es":"cárabo común; Strix aluco"}}};for(const [id,data] of Object.entries(updates)){const row=window.DICCIONARIOS.en.find(entry=>entry.id===id);if(!row)throw new Error('missing en/'+id);Object.assign(row,data);}window.DICCIONARIOS.en=window.DICCIONARIOS.en.filter(entry=>entry.id!=='cappadocian');})();

