;(()=>{const updates={"civilize":{"definition":"(Verb.) To educate or refine a person’s behaviour; to help a society develop organised social and political institutions. The term can be judgmental when applied to cultures from a colonial perspective.","synonyms":["educate","refine","socialise"],"example":{"word":"civilize","text":"The essay examines how colonial writers used civilize to describe other societies."},"exampleSynonym":{"word":"educate","text":"The essay examines how colonial writers used educate to describe other societies."},"translation":{"es":"civilizar; educar; refinar"}},"civility":{"definition":"(Noun.) Polite, respectful behaviour or speech, especially in formal or public interactions.","synonyms":["courtesy","politeness","respectfulness"],"example":{"word":"civility","text":"Even during the disagreement, they treated one another with civility."},"exampleSynonym":{"word":"courtesy","text":"Even during the disagreement, they treated one another with courtesy."},"translation":{"es":"civismo; cortesía; urbanidad"}},"claretian":{"definition":"(Noun and adjective.) A member of the Catholic missionary congregation founded by Saint Anthony Mary Claret; relating to that congregation.","synonyms":["member of the Claretian congregation","Claretian missionary"],"example":{"word":"Claretian","text":"The Claretian community runs a local school."},"exampleSynonym":{"word":"Claretian missionary","text":"A Claretian missionary helped establish the local school."},"translation":{"es":"claretiano; miembro de la congregación claretiana"}},"illuminating":{"word":"illuminating","definition":"(Adjective.) Providing useful information or making something easier to understand; enlightening.","synonyms":["enlightening","informative","instructive"],"example":{"word":"illuminating","text":"The documentary offers an illuminating account of the discovery."},"exampleSynonym":{"word":"enlightening","text":"The documentary offers an enlightening account of the discovery."},"translation":{"es":"esclarecedor; instructivo; revelador"}},"illuminate":{"definition":"(Verb.) To light or brighten something; figuratively, to explain or make something clear; also, to decorate a manuscript or book with illustrations.","synonyms":["light up","brighten","clarify","explain"],"example":{"word":"illuminate","text":"The guide used a small lamp to illuminate the inscription."},"exampleSynonym":{"word":"light up","text":"The guide used a small lamp to light up the inscription."},"translation":{"es":"iluminar; esclarecer; ilustrar"}},"clarify":{"definition":"(Verb.) To make something easier to understand; also, to make a liquid clear by removing suspended matter.","synonyms":["make clear","explain","elucidate"],"example":{"word":"clarify","text":"The spokesperson will clarify the scope of the new rule."},"exampleSynonym":{"word":"make clear","text":"The spokesperson will make clear the scope of the new rule."},"translation":{"es":"aclarar; clarificar; esclarecer"}},"shining":{"definition":"(Adjective.) Emitting or reflecting light; bright or lustrous.","synonyms":["glowing","radiant","gleaming"],"example":{"word":"shining","text":"A shining star appeared above the horizon."},"exampleSynonym":{"word":"glowing","text":"A glowing star appeared above the horizon."},"translation":{"es":"brillante; resplandeciente"}},"chalk":{"definition":"(Noun.) A soft, fine-grained form of limestone, often white, used for writing or drawing. (Verb.) To write, mark, or draw with chalk.","synonyms":["blackboard chalk","writing chalk"],"example":{"word":"chalk","text":"The teacher wrote the date on the board with chalk."},"exampleSynonym":{"word":"blackboard chalk","text":"The teacher wrote the date on the board with blackboard chalk."},"translation":{"es":"tiza; escribir o marcar con tiza"}},"chiaroscuro":{"definition":"(Noun, art.) The treatment of light and dark in drawing or painting to create a sense of volume and depth; also, a strong contrast between light and shadow.","synonyms":["light-and-shade technique","contrast of light and dark"],"example":{"word":"chiaroscuro","text":"The artist used chiaroscuro to give the portrait a sense of depth."},"exampleSynonym":{"word":"light-and-shade technique","text":"The artist used a light-and-shade technique to give the portrait a sense of depth."},"translation":{"es":"claroscuro; contraste de luces y sombras"}},"nailer":{"definition":"(Noun.) A person or device that drives or fastens nails; especially, a powered tool for driving nails.","synonyms":["nail gun","nail-driving tool"],"example":{"word":"nailer","text":"The carpenter used a nailer to fasten the boards quickly."},"exampleSynonym":{"word":"nail gun","text":"The carpenter used a nail gun to fasten the boards quickly."},"translation":{"es":"clavadora; herramienta para clavar clavos"}}};for(const [id,data] of Object.entries(updates)){const row=window.DICCIONARIOS.en.find(entry=>entry.id===id);if(!row)throw new Error('missing '+id);Object.assign(row,data);}})();

;(()=>{const updates={"steep":{"definition":"(Adjective.) Rising or falling sharply; describing a slope with a large angle of inclination. (Verb.) To soak or immerse in liquid; also, to saturate or imbue.","synonyms":["precipitous","sheer","to soak","to immerse"],"example":{"word":"steep","text":"A steep path led from the village to the ridge."},"exampleSynonym":{"word":"precipitous","text":"A precipitous path led from the village to the ridge."},"translation":{"es":"empinado; escarpado; remojar; impregnar"}},"cluck":{"definition":"(Noun and verb.) The short, low-pitched sound made by a chicken; to make this sound.","synonyms":["clucking sound","chicken call"],"example":{"word":"cluck","text":"The hen gave a soft cluck as her chicks gathered around."},"exampleSynonym":{"word":"clucking sound","text":"The hen made a soft clucking sound as her chicks gathered around."},"translation":{"es":"cloqueo; cloquear"}},"clutch":{"definition":"(Verb.) To grasp or seize something firmly. (Noun.) A firm grasp; a device that connects and disconnects a vehicle engine from its transmission; or a group of eggs laid at one time.","synonyms":["grasp","grip","clutch mechanism","group of eggs"],"example":{"word":"clutch","text":"She clutched the rail as the train began to move."},"exampleSynonym":{"word":"gripped","text":"She gripped the rail as the train began to move."},"translation":{"es":"agarrar con fuerza; embrague; nidada"}},"coadjute":{"definition":"(Verb, rare and historical.) To assist or cooperate with someone.","synonyms":["assist","help","cooperate with"],"example":{"word":"coadjute","text":"The appointed officer was expected to coadjute with the local authorities."},"exampleSynonym":{"word":"assist","text":"The appointed officer was expected to assist the local authorities."},"translation":{"es":"ayudar; cooperar (raro y anticuado)"}},"coalescent":{"definition":"(Adjective.) Coming together or growing together to form one mass, whole, or group.","synonyms":["merging","unifying","fusing"],"example":{"word":"coalescent","text":"The coalescent droplets formed a larger drop."},"exampleSynonym":{"word":"merging","text":"The merging droplets formed a larger drop."},"translation":{"es":"coalescente; que se une o fusiona"}},"coati":{"definition":"(Noun.) A long-tailed mammal of the genus Nasua, native to Central and South America and related to raccoons.","synonyms":["coatimundi","Nasua"],"example":{"word":"coati","text":"A coati searched the forest floor for insects."},"exampleSynonym":{"word":"coatimundi","text":"A coatimundi searched the forest floor for insects."},"translation":{"es":"coatí; pizote"}},"coaxial":{"definition":"(Adjective.) Having or sharing a common axis; arranged around the same axis.","synonyms":["concentric","having a common axis"],"example":{"word":"coaxial","text":"The coaxial cable carries the signal with little interference."},"exampleSynonym":{"word":"having a common axis","text":"The cable, with conductors having a common axis, carries the signal with little interference."},"translation":{"es":"coaxial; que comparte un eje"}},"guinea-pig":{"definition":"(Noun.) A small, tailless South American rodent of the genus Cavia, often kept as a pet; figuratively, a person or animal used in an experiment.","synonyms":["cavy","experimental subject"],"example":{"word":"guinea pig","text":"The guinea pig nibbled hay in its enclosure."},"exampleSynonym":{"word":"cavy","text":"The cavy nibbled hay in its enclosure."},"translation":{"es":"cobaya; conejillo de Indias; sujeto de experimentación"}},"sheltering":{"definition":"(Adjective and gerund noun.) Providing protection from danger or weather; the act of giving someone or something shelter.","synonyms":["protective","providing shelter","protection"],"example":{"word":"sheltering","text":"The trees provided a sheltering canopy over the path."},"exampleSynonym":{"word":"protective","text":"The trees provided a protective canopy over the path."},"translation":{"es":"protector; que da cobijo; acción de dar refugio"}},"noogie":{"definition":"(Noun, informal.) A playful or rough gesture in which someone rubs their knuckles on another person’s head, often while holding them in a headlock.","synonyms":["knuckle rub","Dutch rub"],"example":{"word":"noogie","text":"His older brother gave him a noogie after the game."},"exampleSynonym":{"word":"knuckle rub","text":"His older brother gave him a knuckle rub after the game."},"translation":{"es":"cocorrón; colleja con los nudillos (informal)"}}};for(const [id,data] of Object.entries(updates)){const row=window.DICCIONARIOS.en.find(entry=>entry.id===id);if(!row)throw new Error('missing '+id);Object.assign(row,data);}})();

