;(()=>{const updates={"coetaneous":{"definition":"(Adjective, rare.) Of the same age or period; existing or beginning at the same time.","synonyms":["coeval","contemporary","contemporaneous"],"example":{"word":"coetaneous","text":"The two coetaneous settlements developed along the same river."},"exampleSynonym":{"word":"coeval","text":"The two coeval settlements developed along the same river."},"translation":{"es":"coetáneo; de la misma época o edad"}},"coeval":{"definition":"(Adjective and noun.) Of the same age or period as another; as a noun, a person or thing of the same age or period.","synonyms":["coetaneous","contemporary","contemporaneous"],"example":{"word":"coeval","text":"The two coeval settlements developed along the same river."},"exampleSynonym":{"word":"contemporaneous","text":"The two contemporaneous settlements developed along the same river."},"translation":{"es":"coetáneo; contemporáneo"}},"contemporary":{"definition":"(Adjective and noun.) Belonging to or occurring in the present, or existing at the same time as something else; a person living or existing at the same time as another.","synonyms":["current","modern","contemporaneous","coeval"],"example":{"word":"contemporary","text":"The exhibition pairs contemporary works with paintings from the same period."},"exampleSynonym":{"word":"modern","text":"The exhibition pairs modern works with paintings from the same period."},"translation":{"es":"contemporáneo; actual; coetáneo"}},"cofounder":{"definition":"(Noun.) A person who establishes an organisation, business, or project together with one or more other people.","synonyms":["co-founder","joint founder"],"example":{"word":"cofounder","text":"She became a cofounder of the research company."},"exampleSynonym":{"word":"co-founder","text":"She became a co-founder of the research company."},"translation":{"es":"cofundador; cofundadora"}},"cognatic":{"definition":"(Adjective, anthropology.) Relating to descent or kinship traced through any combination of male and female links, rather than exclusively through the paternal line.","synonyms":["bilateral","ambilineal"],"example":{"word":"cognatic","text":"The anthropologist described the society’s cognatic system of descent."},"exampleSynonym":{"word":"bilateral","text":"The anthropologist described the society’s bilateral system of descent."},"translation":{"es":"cognático; relativo al parentesco por líneas paterna y materna"}},"enatic":{"definition":"(Adjective, anthropology.) Related through the maternal line; descended from the same mother or female ancestor.","synonyms":["matrilineal","maternal-line"],"example":{"word":"enatic","text":"The historian traced the enatic line through the women in the family."},"exampleSynonym":{"word":"matrilineal","text":"The historian traced the matrilineal line through the women in the family."},"translation":{"es":"enático; relativo a la línea materna"}},"cognitive":{"definition":"(Adjective.) Relating to thinking, learning, memory, perception, and other mental processes.","synonyms":["mental","intellectual"],"example":{"word":"cognitive","text":"The assessment measures cognitive skills such as attention and memory."},"exampleSynonym":{"word":"mental","text":"The assessment measures mental skills such as attention and memory."},"translation":{"es":"cognitivo; relativo a los procesos mentales"}},"knowable":{"definition":"(Adjective.) Able to be known, understood, or discovered.","synonyms":["discoverable","ascertainable","cognizable"],"example":{"word":"knowable","text":"The answer was knowable once the missing records were found."},"exampleSynonym":{"word":"discoverable","text":"The answer was discoverable once the missing records were found."},"translation":{"es":"cognoscible; que puede conocerse o descubrirse"}},"cohesive":{"definition":"(Adjective.) United and working together effectively; forming a connected or consistent whole.","synonyms":["united","integrated","coherent"],"example":{"word":"cohesive","text":"The team became more cohesive after the retreat."},"exampleSynonym":{"word":"united","text":"The team became more united after the retreat."},"translation":{"es":"cohesivo; unido; coherente"}},"restrain":{"definition":"(Verb.) To hold back, control, or keep within limits; to prevent someone or something from acting freely.","synonyms":["control","hold back","constrain","curb"],"example":{"word":"restrain","text":"The handler had to restrain the dog near the busy road."},"exampleSynonym":{"word":"hold back","text":"The handler had to hold back the dog near the busy road."},"translation":{"es":"restringir; contener; refrenar"}}};for(const [id,data] of Object.entries(updates)){const row=window.DICCIONARIOS.en.find(entry=>entry.id===id);if(!row)throw new Error('missing '+id);Object.assign(row,data);}})();

