;(()=>{const updates={"demystifier":{"definition":"Noun: a person or thing that makes a subject easier to understand by explaining it or removing its air of mystery.","synonyms":["explainer","clarifier","interpreter"],"example":{"word":"demystifier","text":"The guidebook is an excellent demystifier of the region’s complex history."},"exampleSynonym":{"word":"explainer","text":"The guidebook is an excellent explainer of the region’s complex history."},"translation":{"es":"divulgador; explicador; quien aclara un tema"}},"demystify":{"definition":"Verb: to make a subject clearer or easier to understand by explaining it and removing mystery or misconceptions.","synonyms":["clarify","explain","make understandable"],"example":{"word":"demystify","text":"The workshop aims to demystify the process of applying for a mortgage."},"exampleSynonym":{"word":"clarify","text":"The workshop aims to clarify the process of applying for a mortgage."},"translation":{"es":"desmitificar; aclarar; explicar"}},"crumbly":{"definition":"Adjective: easily broken into small pieces or crumbs; friable.","synonyms":["crumbly-textured","friable","brittle"],"example":{"word":"crumbly","text":"The old cheese had a dry, crumbly texture."},"exampleSynonym":{"word":"friable","text":"The old cheese had a dry, friable texture."},"translation":{"es":"desmenuzable; que se desmigaja; friable"}},"gear-down":{"definition":"Phrasal verb: to use a lower gear ratio so an engine turns faster relative to the wheels, usually to slow a vehicle or increase torque; in aviation, to lower an aircraft’s landing gear.","synonyms":["shift down","downshift","lower the landing gear"],"example":{"word":"gear down","text":"The driver had to gear down on the steep hill, while the pilot checked whether the aircraft was ready to lower its landing gear."},"exampleSynonym":{"word":"shift down","text":"The driver had to shift down on the steep hill, while the pilot checked whether the aircraft was ready to lower its landing gear."},"translation":{"es":"reducir de marcha; poner una marcha más baja; bajar el tren de aterrizaje"}},"unevenness":{"definition":"Noun: the quality or state of being uneven; irregularity in surface, size, distribution, or consistency.","synonyms":["irregularity","uneven distribution","disparity"],"example":{"word":"unevenness","text":"The survey found unevenness in the distribution of services across rural districts."},"exampleSynonym":{"word":"disparity","text":"The survey found disparity in the distribution of services across rural districts."},"translation":{"es":"irregularidad; desigualdad; falta de uniformidad"}},"difference":{"definition":"Noun: the way in which two or more things are unlike; a point or amount by which they differ; a disagreement or distinction.","synonyms":["distinction","variation","disagreement","gap"],"example":{"word":"difference","text":"There is a clear difference between the two versions of the contract."},"exampleSynonym":{"word":"distinction","text":"There is a clear distinction between the two versions of the contract."},"translation":{"es":"diferencia; distinción; desacuerdo"}},"inequality":{"definition":"Noun: the condition of being unequal, especially in status, opportunity, resources, or rights; in mathematics, a relation in which two quantities are not equal.","synonyms":["disparity","unequalness","imbalance"],"example":{"word":"inequality","text":"The study examines inequality in access to education."},"exampleSynonym":{"word":"disparity","text":"The study examines disparity in access to education."},"translation":{"es":"desigualdad; inequidad; desigualdad matemática"}},"gap":{"definition":"Noun: an opening or space between things; a difference or shortfall between amounts, levels, or groups; an interval or missing part.","synonyms":["opening","space","shortfall","disparity"],"example":{"word":"gap","text":"The report highlights a widening gap between housing costs and wages."},"exampleSynonym":{"word":"disparity","text":"The report highlights a widening disparity between housing costs and wages."},"translation":{"es":"hueco; brecha; diferencia; déficit; intervalo"}},"unbalance":{"definition":"Verb: to make something unstable or unevenly weighted; to disturb the balance or equilibrium of a person, system, or situation.","synonyms":["destabilize","upset the balance of","throw off balance"],"example":{"word":"unbalance","text":"A sudden gust could unbalance the cyclist on the narrow bridge."},"exampleSynonym":{"word":"destabilize","text":"A sudden gust could destabilize the cyclist on the narrow bridge."},"translation":{"es":"desequilibrar; desestabilizar; descompensar"}},"ignore":{"definition":"Verb: to refuse or fail to pay attention to someone or something; to disregard or deliberately take no notice of it.","synonyms":["disregard","take no notice of","overlook"],"example":{"word":"ignore","text":"Please do not ignore the warning light on the dashboard."},"exampleSynonym":{"word":"disregard","text":"Please do not disregard the warning light on the dashboard."},"translation":{"es":"ignorar; desatender; no hacer caso de; pasar por alto"}}};for(const [id,data] of Object.entries(updates)){const row=window.DICCIONARIOS.en.find(entry=>entry.id===id);if(!row)throw new Error('Missing '+id);Object.assign(row,data);}})();

;(()=>{const updates={"dislodge":{"definition":"Verb: to force or move something from its fixed or usual position; to make someone leave a place or position.","synonyms":["remove","shift","force out","eject"],"example":{"word":"dislodge","text":"A strong gust of wind could dislodge the loose roof tile."},"exampleSynonym":{"word":"remove","text":"A strong gust of wind could remove the loose roof tile."},"translation":{"es":"desalojar; desprender; desplazar; expulsar"}},"skin":{"definition":"Noun: the outer covering of a person or animal; the peel or outer layer of a fruit or other object. Verb: to remove this covering; to scrape or injure the surface.","synonyms":["hide","outer layer","peel","strip"],"example":{"word":"skin","text":"Peel and skin the tomatoes before adding them to the sauce."},"exampleSynonym":{"word":"peel","text":"Peel and remove the outer layer of the tomatoes before adding them to the sauce."},"translation":{"es":"piel; cuero; cáscara; pelar; despellejar"}},"untidily":{"definition":"Adverb: in an untidy, disordered, or careless manner.","synonyms":["messily","sloppily","in a disorderly way"],"example":{"word":"untidily","text":"The papers were stacked untidily across the desk."},"exampleSynonym":{"word":"messily","text":"The papers were stacked messily across the desk."},"translation":{"es":"desordenadamente; de manera descuidada"}},"disarrange":{"definition":"Verb: to disturb the order or arrangement of something; to put things into a disorganized state.","synonyms":["disorder","rearrange","jumble","disturb"],"example":{"word":"disarrange","text":"Please do not disarrange the files while looking for the report."},"exampleSynonym":{"word":"disorder","text":"Please do not disorder the files while looking for the report."},"translation":{"es":"desordenar; desarreglar; desorganizar"}},"disorder":{"definition":"Noun: a state of confusion or lack of order; a disturbance or illness, especially one affecting physical or mental health. Verb: to disrupt the order of something.","synonyms":["disarray","confusion","disturbance","illness"],"example":{"word":"disorder","text":"The files were in disorder after the office move."},"exampleSynonym":{"word":"disarray","text":"The files were in disarray after the office move."},"translation":{"es":"desorden; trastorno; alteración; desordenar"}},"jumble":{"definition":"Verb: to mix things together in a confused or disorderly way. Noun: a confused mixture or collection.","synonyms":["mix up","muddle","disorder","hodgepodge"],"example":{"word":"jumble","text":"The wind jumbled the papers on the table into a messy pile."},"exampleSynonym":{"word":"mix up","text":"The wind mixed up the papers on the table into a messy pile."},"translation":{"es":"mezclar; revolver; confundir; revoltijo; mezcla desordenada"}},"defrock":{"definition":"Verb: to remove a priest or other member of the clergy from clerical status and privileges; to unfrock.","synonyms":["unfrock","laicize","remove from the clergy"],"example":{"word":"defrock","text":"The church court voted to defrock the priest after the investigation."},"exampleSynonym":{"word":"unfrock","text":"The church court voted to unfrock the priest after the investigation."},"translation":{"es":"despojar de la condición clerical; secularizar; expulsar del clero"}},"disorganize":{"definition":"Verb: to disrupt the orderly operation or arrangement of something; to make it confused or inefficient.","synonyms":["disrupt","throw into disorder","upset the arrangement of"],"example":{"word":"disorganize","text":"A sudden staff shortage could disorganize the entire schedule."},"exampleSynonym":{"word":"disrupt","text":"A sudden staff shortage could disrupt the entire schedule."},"translation":{"es":"desorganizar; desordenar; trastocar"}},"disrupt":{"definition":"Verb: to interrupt or prevent the normal progress or operation of something; to throw a system, event, or activity into disorder.","synonyms":["interrupt","disturb","upset","disorganize"],"example":{"word":"disrupt","text":"The storm may disrupt ferry services throughout the weekend."},"exampleSynonym":{"word":"interrupt","text":"The storm may interrupt ferry services throughout the weekend."},"translation":{"es":"interrumpir; perturbar; trastornar; desorganizar"}},"deoxidizer":{"definition":"Noun: a substance or agent that removes oxygen from a material or reduces its oxide content, especially in metallurgy and chemical processing.","synonyms":["deoxidant","oxygen remover","reducing agent"],"example":{"word":"deoxidizer","text":"The steelmaker added a deoxidizer to reduce the oxygen content of the molten metal."},"exampleSynonym":{"word":"deoxidant","text":"The steelmaker added a deoxidant to reduce the oxygen content of the molten metal."},"translation":{"es":"desoxidante; agente desoxidante; reductor"}}};for(const [id,data] of Object.entries(updates)){const row=window.DICCIONARIOS.en.find(entry=>entry.id===id);if(!row)throw new Error('Missing '+id);Object.assign(row,data);}})();

