;(()=>{const updates={"fascinate":{"definition":"Verb: to attract and hold someone’s attention or interest intensely.","synonyms":["captivate","enthrall","charm","intrigue"],"translation":{"es":"fascinar; cautivar; atraer intensamente"},"example":{"word":"fascinate","text":"The ancient map continues to fascinate historians."},"exampleSynonym":{"word":"captivate","text":"The ancient map continues to captivate historians."}},"sumptuous":{"definition":"Adjective: splendid, rich, or luxurious, especially in appearance, furnishings, or food.","synonyms":["lavish","luxurious","opulent","magnificent"],"translation":{"es":"fastuoso; lujoso; espléndido"},"example":{"word":"sumptuous","text":"The guests admired the sumptuous meal and elegant decorations."},"exampleSynonym":{"word":"lavish","text":"The guests admired the lavish meal and elegant decorations."}},"fatalism":{"definition":"Noun: the belief that events are determined by fate or necessity and cannot be changed by human action.","synonyms":["belief in fate","predestination","determinism"],"translation":{"es":"fatalismo; creencia en el destino"},"example":{"word":"fatalism","text":"Her fatalism led her to accept events as unavoidable."},"exampleSynonym":{"word":"belief in fate","text":"Her belief in fate led her to accept events as unavoidable."}},"fatally":{"definition":"Adverb: in a way that causes death or disastrous harm; also, with consequences that cannot be repaired.","synonyms":["lethally","mortally","disastrously"],"translation":{"es":"mortalmente; fatalmente"},"example":{"word":"fatally","text":"The collision fatally injured one passenger."},"exampleSynonym":{"word":"mortally","text":"The collision mortally injured one passenger."}},"tire":{"definition":"Verb: to become weary or sleepy, or to make someone feel weary; also, to lose interest through repetition.","synonyms":["weary","exhaust","fatigue","bore"],"translation":{"es":"cansarse; cansar; fatigar"},"example":{"word":"tire","text":"Long meetings can tire even the most attentive listener."},"exampleSynonym":{"word":"weary","text":"Long meetings can weary even the most attentive listener."}},"fatuousness":{"definition":"Noun: foolishness or silliness, especially a self-satisfied or complacent kind.","synonyms":["foolishness","silliness","inanity","fatuity"],"translation":{"es":"fatuidad; necedad; simpleza"},"example":{"word":"fatuousness","text":"The speech’s fatuousness became clear when its claims were examined."},"exampleSynonym":{"word":"foolishness","text":"The speech’s foolishness became clear when its claims were examined."}},"conceit":{"definition":"Noun: an excessively high opinion of oneself; also, a fanciful or ingenious idea, comparison, or expression.","synonyms":["vanity","self-importance","fanciful idea","metaphor"],"translation":{"es":"vanidad; presunción; idea ingeniosa; metáfora"},"example":{"word":"conceit","text":"His conceit made him dismiss every suggestion from his colleagues."},"exampleSynonym":{"word":"vanity","text":"His vanity made him dismiss every suggestion from his colleagues."}},"faun":{"definition":"Noun: in Roman mythology, a woodland deity or spirit, usually represented with pointed ears, horns, and legs like a goat.","synonyms":["woodland spirit","satyr"],"translation":{"es":"fauno; espíritu silvestre"},"example":{"word":"faun","text":"The painting depicts a faun playing a flute beneath the trees."},"exampleSynonym":{"word":"woodland spirit","text":"The painting depicts a woodland spirit playing a flute beneath the trees."}},"feverishly":{"definition":"Adverb: with intense, restless energy or excitement; also, in a manner resembling a fever.","synonyms":["frantically","frenetically","intensely"],"translation":{"es":"febrilmente; frenéticamente; con gran intensidad"},"example":{"word":"feverishly","text":"The reporters worked feverishly to meet the publication deadline."},"exampleSynonym":{"word":"frantically","text":"The reporters worked frantically to meet the publication deadline."}},"starch":{"definition":"Noun: a white, odorless carbohydrate found in plants and used as food or to stiffen fabric. As a verb, to treat fabric with starch to make it stiff.","synonyms":["amylum","laundry stiffener","stiffen"],"translation":{"es":"almidón; apresto; almidonar"},"example":{"word":"starch","text":"The laundry uses starch to give the shirt a crisp finish."},"exampleSynonym":{"word":"laundry stiffener","text":"The laundry uses a laundry stiffener to give the shirt a crisp finish."}}};for(const [id,data] of Object.entries(updates)){const row=window.DICCIONARIOS.en.find(entry=>entry.id===id);if(!row)throw new Error('Missing '+id);Object.assign(row,data);}})();

