;(()=>{const updates={"film":{"definition":"Noun: a thin layer or coating covering a surface; a motion picture or the medium of cinema. Verb: to record moving images with a camera.","synonyms":["thin coating","motion picture","movie"],"translation":{"es":"película; filme; capa delgada; filmar"},"example":{"word":"film","text":"A thin film of oil covered the water, and they later watched a film about the harbor."},"exampleSynonym":{"word":"thin coating","text":"A thin coating of oil covered the water."}},"philology":{"definition":"Noun: the study of language in historical and literary texts, including their development, meaning, and cultural context.","synonyms":["historical linguistics","study of texts and languages"],"translation":{"es":"filología"},"example":{"word":"philology","text":"Her research in philology compared medieval manuscripts and their language."},"exampleSynonym":{"word":"historical linguistics","text":"Her research in historical linguistics compared medieval manuscripts and their language."}},"philologically":{"definition":"Adverb: from the perspective or by the methods of philology, especially through the study of written texts and their linguistic history.","synonyms":["by philological methods","from a philological perspective"],"translation":{"es":"filológicamente"},"example":{"word":"philologically","text":"The editor philologically examined the oldest surviving versions of the poem."},"exampleSynonym":{"word":"by philological methods","text":"The editor examined the oldest surviving versions of the poem by philological methods."}},"finely":{"definition":"Adverb: in a fine or delicate way; into small pieces or particles; with great precision or sensitivity, depending on context.","synonyms":["into small pieces","delicately","precisely"],"translation":{"es":"finamente; en trozos pequeños; con precisión"},"example":{"word":"finely","text":"Finely chop the onions before adding them to the pan."},"exampleSynonym":{"word":"into small pieces","text":"Chop the onions into small pieces before adding them to the pan."}},"fjord":{"definition":"Noun: a long, narrow, deep inlet of the sea between steep or mountainous sides, typically formed by glacial erosion.","synonyms":["sea inlet","glacial inlet"],"translation":{"es":"fiordo"},"example":{"word":"fjord","text":"The village stood at the head of a steep-sided fjord."},"exampleSynonym":{"word":"sea inlet","text":"The village stood at the head of a steep-sided sea inlet."}},"fiord":{"definition":"Noun: an alternative spelling of fjord, a long, narrow sea inlet between steep sides, usually formed by glacial erosion.","synonyms":["fjord","glacial inlet"],"translation":{"es":"fiordo"},"example":{"word":"fiord","text":"Their ship entered a narrow fiord surrounded by mountains."},"exampleSynonym":{"word":"fjord","text":"Their ship entered a narrow fjord surrounded by mountains."}},"physiographic":{"definition":"Adjective: relating to physiography, the description and study of the physical features and landforms of the Earth.","synonyms":["physical-geographical","geomorphological"],"translation":{"es":"fisiográfico"},"example":{"word":"physiographic","text":"The report divided the region into several physiographic provinces."},"exampleSynonym":{"word":"geomorphological","text":"The report divided the region into several geomorphological provinces."}},"physiological":{"definition":"Adjective: relating to the normal functions and processes of a living organism or one of its parts.","synonyms":["relating to bodily function","biological"],"translation":{"es":"fisiológico"},"example":{"word":"physiological","text":"The study measured the physiological effects of exercise on the volunteers."},"exampleSynonym":{"word":"biological","text":"The study measured the biological effects of exercise on the volunteers."}},"physiognomy":{"definition":"Noun: a person’s facial features or expression, especially when considered as indicating character; also, the general appearance or features of a place or thing.","synonyms":["facial features","appearance","countenance"],"translation":{"es":"fisonomía; aspecto"},"example":{"word":"physiognomy","text":"The sculptor captured the distinctive physiognomy of the old man."},"exampleSynonym":{"word":"facial features","text":"The sculptor captured the distinctive facial features of the old man."}},"fistular":{"definition":"Adjective: hollow and tube-shaped, or resembling a tube; chiefly a botanical or zoological term.","synonyms":["tubular","hollow-tubed"],"translation":{"es":"fistular; tubular"},"example":{"word":"fistular","text":"The plant has fistular stems that store water."},"exampleSynonym":{"word":"tubular","text":"The plant has tubular stems that store water."}}};for(const [id,data] of Object.entries(updates)){const row=window.DICCIONARIOS.en.find(entry=>entry.id===id);if(!row)throw new Error('Missing '+id);Object.assign(row,data);}})();

;(()=>{const updates={"skinny":{"definition":"Adjective: very thin, often implying that someone looks too thin. Informal noun, usually “the skinny”: the essential facts or inside information.","synonyms":["thin","slender","inside information"],"translation":{"es":"flaco; delgado; (the skinny) información confidencial"},"example":{"word":"skinny","text":"The skinny runner wore a bright jacket, and later gave us the skinny on the race."},"exampleSynonym":{"word":"thin","text":"The thin runner wore a bright jacket."}},"flagellate":{"definition":"Verb: to whip or scourge. Adjective or noun in biology: (of a cell or organism) having one or more flagella; a flagellated organism.","synonyms":["whip","scourge","flagellated organism"],"translation":{"es":"azotar; flagelar; flagelado"},"example":{"word":"flagellate","text":"The researchers observed a flagellate microorganism under the microscope."},"exampleSynonym":{"word":"flagellated organism","text":"The researchers observed a flagellated organism under the microscope."}},"flap":{"definition":"Noun: a broad, usually thin piece attached along one edge and hanging or moving freely. Verb: to move up and down or back and forth, often loosely or noisily.","synonyms":["loose panel","to flutter","to flap about"],"translation":{"es":"solapa; faldón; aletear; agitarse"},"example":{"word":"flap","text":"The loose flap of canvas began to flap in the wind."},"exampleSynonym":{"word":"loose panel","text":"The loose panel of canvas began to move in the wind."}},"falter":{"definition":"Verb: to hesitate or lose confidence; to become unsteady or weaken; of speech or voice, to become hesitant or shaky. Rare noun: a brief hesitation or unsteadiness.","synonyms":["hesitate","waver","weaken"],"translation":{"es":"vacilar; titubear; flaquear"},"example":{"word":"falter","text":"Her voice began to falter as she reached the final sentence."},"exampleSynonym":{"word":"waver","text":"Her voice began to waver as she reached the final sentence."}},"flounder":{"definition":"Verb: to struggle clumsily to move, keep one’s balance, or make progress. Noun: a flatfish, especially a European or American species of the family Pleuronectidae.","synonyms":["struggle","thrash about","flatfish"],"translation":{"es":"debatirse; avanzar con dificultad; platija"},"example":{"word":"flounder","text":"Without a map, the hikers began to flounder in the unfamiliar terrain."},"exampleSynonym":{"word":"struggle","text":"Without a map, the hikers began to struggle in the unfamiliar terrain."}},"phlegmatic":{"definition":"Adjective: calm and not easily excited, angered, or moved to strong emotion; sometimes, slow or impassive in temperament.","synonyms":["calm","even-tempered","impassive"],"translation":{"es":"flemático; imperturbable"},"example":{"word":"phlegmatic","text":"Even during the emergency, the phlegmatic pilot spoke calmly to the passengers."},"exampleSynonym":{"word":"calm","text":"Even during the emergency, the calm pilot spoke calmly to the passengers."}},"halibut":{"definition":"Noun: a large marine flatfish of the family Pleuronectidae, especially Atlantic halibut (Hippoglossus hippoglossus) or Pacific halibut (Hippoglossus stenolepis), valued as food.","synonyms":["large flatfish","Hippoglossus"],"translation":{"es":"fletán; hipogloso"},"example":{"word":"halibut","text":"They ordered grilled halibut with lemon and herbs."},"exampleSynonym":{"word":"large flatfish","text":"They ordered a grilled large flatfish with lemon and herbs."}},"flectional":{"definition":"Adjective, variant of inflectional: relating to inflection, especially a grammatical change in the form of a word to express tense, case, number, or other relations.","synonyms":["inflectional","grammatical"],"translation":{"es":"flexivo; inflexional"},"example":{"word":"flectional","text":"The paper describes flectional endings in an older stage of the language."},"exampleSynonym":{"word":"inflectional","text":"The paper describes inflectional endings in an older stage of the language."}},"inflectional":{"definition":"Adjective: relating to inflection, especially a grammatical change in a word’s form that expresses distinctions such as tense, case, number, or person.","synonyms":["flectional","grammatical inflection"],"translation":{"es":"flexivo; inflexional"},"example":{"word":"inflectional","text":"The language uses inflectional endings to mark grammatical case."},"exampleSynonym":{"word":"flectional","text":"The language uses flectional endings to mark grammatical case."}},"laziness":{"definition":"Noun: unwillingness to work or make an effort; the state or quality of being lazy.","synonyms":["idleness","indolence","sloth"],"translation":{"es":"pereza; holgazanería; flojera"},"example":{"word":"laziness","text":"The manager blamed laziness for the unfinished work, though the team was understaffed."},"exampleSynonym":{"word":"idleness","text":"The manager blamed idleness for the unfinished work, though the team was understaffed."}}};for(const [id,data] of Object.entries(updates)){const row=window.DICCIONARIOS.en.find(entry=>entry.id===id);if(!row)throw new Error('Missing '+id);Object.assign(row,data);}})();

;(()=>{const updates={"flower":{"definition":"Noun: the seed-bearing reproductive structure of a flowering plant, often consisting of petals and other specialized parts. Verb: to produce flowers or reach a flourishing stage.","synonyms":["blossom","bloom","floral structure"],"translation":{"es":"flor; florecer"},"example":{"word":"flower","text":"A red flower opened by the path, and the young plant should flower next spring."},"exampleSynonym":{"word":"blossom","text":"A red blossom opened by the path."}},"floriculturist":{"definition":"Noun: a person who grows flowers, especially commercially or as a specialist in floriculture.","synonyms":["flower grower","floriculturalist"],"translation":{"es":"floricultor; cultivador de flores"},"example":{"word":"floriculturist","text":"The floriculturist selected varieties suited to the cool greenhouse."},"exampleSynonym":{"word":"flower grower","text":"The flower grower selected varieties suited to the cool greenhouse."}},"florin":{"definition":"Noun: a gold coin first issued in Florence in the 13th century, or one of several later coins called a florin, including a former British two-shilling coin.","synonyms":["Florentine gold coin","two-shilling coin (historical British)"],"translation":{"es":"florín"},"example":{"word":"florin","text":"The collection included a medieval Florentine florin."},"exampleSynonym":{"word":"Florentine gold coin","text":"The collection included a medieval Florentine gold coin."}},"flotilla":{"definition":"Noun: a small fleet of ships or boats, especially a group organized for a particular purpose; also, a naval unit of small warships.","synonyms":["small fleet","group of boats"],"translation":{"es":"flotilla; pequeña flota"},"example":{"word":"flotilla","text":"A flotilla of fishing boats left the harbor before sunrise."},"exampleSynonym":{"word":"small fleet","text":"A small fleet of fishing boats left the harbor before sunrise."}},"fluctuate":{"definition":"Verb: to change continually or irregularly between levels, values, or conditions; to rise and fall.","synonyms":["vary","oscillate","swing"],"translation":{"es":"fluctuar; variar; oscilar"},"example":{"word":"fluctuate","text":"Temperatures fluctuate sharply between day and night in the desert."},"exampleSynonym":{"word":"vary","text":"Temperatures vary sharply between day and night in the desert."}},"swing":{"definition":"Verb: to move back and forth or from side to side, or to cause such movement; also, to change or shift noticeably. Noun: a back-and-forth movement or a suspended seat.","synonyms":["sway","rock","oscillate"],"translation":{"es":"balancearse; oscilar; columpio"},"example":{"word":"swing","text":"The sign began to swing in the strong wind."},"exampleSynonym":{"word":"sway","text":"The sign began to sway in the strong wind."}},"waver":{"definition":"Verb: to hesitate or become indecisive; to weaken or become unsteady; of light, sound, or a flame, to flicker or vary.","synonyms":["hesitate","vacillate","falter","flicker"],"translation":{"es":"vacilar; titubear; fluctuar"},"example":{"word":"waver","text":"Despite the pressure, she did not waver in her decision."},"exampleSynonym":{"word":"hesitate","text":"Despite the pressure, she did not hesitate over her decision."}},"fluorine":{"definition":"Noun: the chemical element with atomic number 9 and symbol F, a highly reactive, pale yellow gas and the lightest halogen.","synonyms":["F","chemical element 9"],"translation":{"es":"flúor"},"example":{"word":"fluorine","text":"Fluorine is too reactive to occur freely in nature."},"exampleSynonym":{"word":"F","text":"Element F is too reactive to occur freely in nature."}},"phobic":{"definition":"Adjective: relating to or caused by a phobia; also, having an intense or irrational fear or aversion, as in «phobic reaction».","synonyms":["fearful","averse","phobia-related"],"translation":{"es":"fóbico; relacionado con una fobia"},"example":{"word":"phobic","text":"The therapist helped him manage his phobic response to flying."},"exampleSynonym":{"word":"fearful","text":"The therapist helped him manage his fearful response to flying."}},"animosity":{"definition":"Noun: strong hostility or ill will, often leading to opposition or resentment.","synonyms":["hostility","enmity","ill will","antagonism"],"translation":{"es":"animosidad; hostilidad; enemistad"},"example":{"word":"animosity","text":"Years of rivalry had created deep animosity between the two teams."},"exampleSynonym":{"word":"hostility","text":"Years of rivalry had created deep hostility between the two teams."}}};for(const [id,data] of Object.entries(updates)){const row=window.DICCIONARIOS.en.find(entry=>entry.id===id);if(!row)throw new Error('Missing '+id);Object.assign(row,data);}})();

;(()=>{const updates={"folklore":{"definition":"Noun: the traditional beliefs, customs, stories, songs, and practices of a community or culture, passed down across generations.","synonyms":["traditional culture","oral tradition","folk tradition"],"translation":{"es":"folclore; folklore"},"example":{"word":"folklore","text":"The festival preserves the folklore and songs of the coastal community."},"exampleSynonym":{"word":"traditional culture","text":"The festival preserves the traditional culture and songs of the coastal community."}},"phoneme":{"definition":"Noun: the smallest sound unit in a language that can distinguish one word from another; it may have different phonetic realizations called allophones.","synonyms":["distinctive sound unit","contrastive sound"],"translation":{"es":"fonema"},"example":{"word":"phoneme","text":"Changing one phoneme can turn “bat” into “pat”."},"exampleSynonym":{"word":"distinctive sound unit","text":"Changing one distinctive sound unit can turn “bat” into “pat”."}},"phonological":{"definition":"Adjective: relating to phonology, the study of how speech sounds function and pattern in a language.","synonyms":["phonologic","relating to sound systems"],"translation":{"es":"fonológico"},"example":{"word":"phonological","text":"The paper describes phonological differences between the two dialects."},"exampleSynonym":{"word":"phonologic","text":"The paper describes phonologic differences between the two dialects."}},"former":{"definition":"Adjective: existing or occurring earlier; previous. Also, the first of two people or things just mentioned. Noun: a person who forms or makes something, chiefly in compounds.","synonyms":["previous","earlier","the first of two"],"translation":{"es":"anterior; antiguo; el primero de dos"},"example":{"word":"former","text":"The former director returned to visit the staff."},"exampleSynonym":{"word":"previous","text":"The previous director returned to visit the staff."}},"fortify":{"definition":"Verb: to strengthen or reinforce a person, place, structure, or substance; to build defensive works around a place; to strengthen food or drink by adding nutrients or alcohol.","synonyms":["strengthen","reinforce","fortress"],"translation":{"es":"fortalecer; fortificar; enriquecer"},"example":{"word":"fortify","text":"They used stone walls to fortify the old harbor."},"exampleSynonym":{"word":"reinforce","text":"They used stone walls to reinforce the old harbor."}},"strongman":{"definition":"Noun: a man who displays exceptional physical strength, especially as an entertainer or competitor; also, an authoritarian political leader who exercises power by force.","synonyms":["powerful man","authoritarian leader","strongman performer"],"translation":{"es":"forzudo; hombre fuerte; líder autoritario"},"example":{"word":"strongman","text":"The strongman lifted the heavy stone, while the country’s strongman tightened his grip on power."},"exampleSynonym":{"word":"powerful man","text":"The powerful man lifted the heavy stone."}},"phosphorescent":{"definition":"Adjective: emitting a continuing glow after exposure to radiation or another source of excitation has ceased; relating to phosphorescence.","synonyms":["glowing","luminescent","afterglowing"],"translation":{"es":"fosforescente"},"example":{"word":"phosphorescent","text":"The phosphorescent paint glowed after the lights were switched off."},"exampleSynonym":{"word":"glowing","text":"The glowing paint remained visible after the lights were switched off."}},"photoengraving":{"definition":"Noun: a printing process in which a photographic image is transferred to a plate and etched, or the plate produced by that process.","synonyms":["photochemical engraving","etched printing plate"],"translation":{"es":"fotograbado"},"example":{"word":"photoengraving","text":"The printer used photoengraving to reproduce the fine lines of the illustration."},"exampleSynonym":{"word":"photochemical engraving","text":"The printer used photochemical engraving to reproduce the fine lines of the illustration."}},"photographically":{"definition":"Adverb: by means of photography or in a way characteristic of photographic images or processes.","synonyms":["by photography","in photographic form"],"translation":{"es":"fotográficamente"},"example":{"word":"photographically","text":"The scene was photographically documented before restoration began."},"exampleSynonym":{"word":"by photography","text":"The scene was documented by photography before restoration began."}},"photolithography":{"definition":"Noun: a process that uses light and a photosensitive material to transfer a pattern onto a surface; used in printing and in manufacturing microelectronic circuits.","synonyms":["photolithographic process","lithography using light"],"translation":{"es":"fotolitografía"},"example":{"word":"photolithography","text":"Photolithography is used to create the tiny patterns on a semiconductor wafer."},"exampleSynonym":{"word":"photolithographic process","text":"The photolithographic process creates tiny patterns on a semiconductor wafer."}}};for(const [id,data] of Object.entries(updates)){const row=window.DICCIONARIOS.en.find(entry=>entry.id===id);if(!row)throw new Error('Missing '+id);Object.assign(row,data);}})();

;(()=>{const updates={"photo-booth":{"definition":"Noun: a small enclosed kiosk or booth containing a camera and lighting equipment for taking portrait photographs, often printed automatically; commonly used for ID or passport photos.","synonyms":["photobooth","photo kiosk"],"translation":{"es":"fotomatón; cabina fotográfica"},"example":{"word":"photo booth","text":"They took passport pictures in the photo booth at the station."},"exampleSynonym":{"word":"photobooth","text":"They took passport pictures in the photobooth at the station."}},"collotype":{"definition":"Noun: an obsolete photographic printing process in which a light-sensitive gelatin layer on a plate is used to reproduce continuous-tone images.","synonyms":["collotype printing","photogelatin process"],"translation":{"es":"fototipia; colotipia"},"example":{"word":"collotype","text":"The museum used collotype to reproduce the subtle tones of the historic photograph."},"exampleSynonym":{"word":"collotype printing","text":"The museum used collotype printing to reproduce the subtle tones of the historic photograph."}},"phototoxic":{"definition":"Adjective: causing injury or an abnormal reaction when a substance or organism is exposed to light, especially sunlight.","synonyms":["light-induced toxic","causing light-induced injury"],"translation":{"es":"fototóxico"},"example":{"word":"phototoxic","text":"The label warns that the cream may be phototoxic in direct sunlight."},"exampleSynonym":{"word":"causing light-induced injury","text":"The label warns that the cream may cause light-induced injury in direct sunlight."}},"din":{"definition":"Noun: a loud, continuous, confusing, or unpleasant noise. Verb: to make a person hear something repeatedly and insistently, often with “din into”.","synonyms":["racket","clamor","to din into"],"translation":{"es":"estrépito; estruendo; aturdir repitiendo"},"example":{"word":"din","text":"The din from the construction site made it hard to think."},"exampleSynonym":{"word":"racket","text":"The racket from the construction site made it hard to think."}},"clash":{"definition":"Noun: a loud metallic or breaking sound; a conflict or strong disagreement. Verb: to strike together with a loud noise, conflict, or be incompatible.","synonyms":["collision","conflict","to collide"],"translation":{"es":"choque; estrépito; conflicto; chocar"},"example":{"word":"clash","text":"The clash of cymbals marked the start of the performance."},"exampleSynonym":{"word":"collision","text":"The collision of cymbals marked the start of the performance."}},"uproar":{"definition":"Noun: a noisy state of confusion, excitement, protest, or public anger.","synonyms":["commotion","tumult","outcry"],"translation":{"es":"alboroto; tumulto; protesta ruidosa"},"example":{"word":"uproar","text":"The unexpected decision caused an uproar among the audience."},"exampleSynonym":{"word":"commotion","text":"The unexpected decision caused a commotion among the audience."}},"forge":{"definition":"Noun: a furnace or hearth where metal is heated for shaping. Verb: to shape metal by heating and hammering; to create or develop something through effort; to make a false copy or signature.","synonyms":["blacksmith’s hearth","shape by hammering","falsify"],"translation":{"es":"fragua; forjar; falsificar"},"example":{"word":"forge","text":"The blacksmith heated the iron in the forge before shaping it."},"exampleSynonym":{"word":"blacksmith’s hearth","text":"The blacksmith heated the iron in the blacksmith’s hearth before shaping it."}},"monkish":{"definition":"Adjective: resembling a monk or characteristic of monastic life, especially in austerity, simplicity, or seclusion.","synonyms":["monastic","monk-like","ascetic"],"translation":{"es":"monacal; monástico; austero"},"example":{"word":"monkish","text":"He kept a monkish routine of study, silence, and early rising."},"exampleSynonym":{"word":"monastic","text":"He kept a monastic routine of study, silence, and early rising."}},"francium":{"definition":"Noun: a highly radioactive alkali metal chemical element with atomic number 87 and symbol Fr; it occurs naturally only in minute traces.","synonyms":["Fr","element 87","radioactive alkali metal"],"translation":{"es":"francio"},"example":{"word":"francium","text":"Because francium is extremely rare and radioactive, it has few practical uses."},"exampleSynonym":{"word":"element 87","text":"Because element 87 is extremely rare and radioactive, it has few practical uses."}},"masonic":{"definition":"Adjective: relating to Freemasons, Freemasonry, or its rites and organizations.","synonyms":["Freemason-related","Masonic-order"],"translation":{"es":"masónico; francmasónico"},"example":{"word":"masonic","text":"The archive contains several masonic records from the nineteenth century."},"exampleSynonym":{"word":"Freemason-related","text":"The archive contains several Freemason-related records from the nineteenth century."}}};for(const [id,data] of Object.entries(updates)){const row=window.DICCIONARIOS.en.find(entry=>entry.id===id);if(!row)throw new Error('Missing '+id);Object.assign(row,data);}})();

