;(()=>{const updates={"oligarchic":{"definition":"adj. Of, relating to, or governed by an oligarchy; controlled by a small group holding political or economic power.","synonyms":["oligarchical","oligarchal","rule by a small elite"],"example":{"word":"oligarchic","text":"The report criticized the oligarchic system for concentrating power in a few families."},"exampleSynonym":{"word":"oligarchical","text":"The report criticized the oligarchical system for concentrating power in a few families."},"translation":{"es":"oligárquico"}},"oligarchical":{"definition":"adj. Variant of oligarchic: relating to or governed by an oligarchy.","synonyms":["oligarchic","oligarchal"],"example":{"word":"oligarchical","text":"The historian described the city as oligarchical during that period."},"exampleSynonym":{"word":"oligarchic","text":"The historian described the city as oligarchic during that period."},"translation":{"es":"oligárquico"}},"oligocene":{"definition":"n. and adj. Geology. The epoch of the Paleogene Period from about 33.9 to 23.03 million years ago, or relating to that epoch.","synonyms":["Oligocene Epoch","Paleogene epoch (Oligocene)"],"example":{"word":"Oligocene","text":"The fossil dates to the Oligocene, roughly 30 million years ago."},"exampleSynonym":{"word":"Oligocene Epoch","text":"The fossil dates to the Oligocene Epoch, roughly 30 million years ago."},"translation":{"es":"Oligoceno; época del Oligoceno"}},"oligophrenic":{"definition":"adj. and n. Obsolete and offensive medical term relating to a person with an intellectual disability; encountered today chiefly in historical texts.","synonyms":["intellectually disabled (current respectful wording)","relating to oligophrenia (obsolete)"],"example":{"word":"oligophrenic","text":"The archivist marked oligophrenic as an obsolete and offensive term in the historical record."},"exampleSynonym":{"word":"relating to oligophrenia","text":"The archivist marked relating to oligophrenia as an obsolete and offensive phrase in the historical record."},"translation":{"es":"oligofrénico (término médico obsoleto y ofensivo)"}},"olivine":{"definition":"n. A group of olive-green magnesium-iron silicate minerals common in igneous rocks; gem-quality varieties include peridot.","synonyms":["chrysolite","magnesium-iron silicate mineral","peridot (gem variety)"],"example":{"word":"olivine","text":"The basalt contains small green crystals of olivine."},"exampleSynonym":{"word":"chrysolite","text":"The basalt contains small green crystals of chrysolite."},"translation":{"es":"olivino; crisolita"}},"ombu":{"definition":"n. A large South American evergreen tree (Phytolacca dioica) with a thick, water-storing trunk; also spelled ombú in Spanish.","synonyms":["ombú","Phytolacca dioica","bella sombra"],"example":{"word":"ombu","text":"An old ombu tree shaded the farmyard."},"exampleSynonym":{"word":"ombú","text":"An old ombú tree shaded the farmyard."},"translation":{"es":"ombú; bella sombra"}},"omen":{"definition":"n. An event or sign believed to foretell a future event, especially one regarded as a warning or prediction.","synonyms":["portent","presage","forewarning","sign"],"example":{"word":"omen","text":"The sudden storm was taken as an omen before the voyage."},"exampleSynonym":{"word":"portent","text":"The sudden storm was taken as a portent before the voyage."},"translation":{"es":"presagio; augurio; señal"}},"ominous":{"definition":"adj. Suggesting that something bad or unpleasant is likely to happen; threatening or foreboding.","synonyms":["foreboding","threatening","menacing","portentous"],"example":{"word":"ominous","text":"Dark clouds gathered over the harbor, giving the sky an ominous appearance."},"exampleSynonym":{"word":"threatening","text":"Dark clouds gathered over the harbor, giving the sky a threatening appearance."},"translation":{"es":"ominoso; amenazador; de mal agüero"}},"omissible":{"definition":"adj. Able to be omitted or left out without serious loss; usually of a word, detail, or requirement.","synonyms":["omittable","dispensable","able to be left out"],"example":{"word":"omissible","text":"The editor marked the repeated sentence as omissible."},"exampleSynonym":{"word":"omittable","text":"The editor marked the repeated sentence as omittable."},"translation":{"es":"omisible; prescindible"}},"omniscient":{"definition":"adj. Having complete or unlimited knowledge; knowing everything.","synonyms":["all-knowing","all-seeing (related, not exact)","possessing total knowledge"],"example":{"word":"omniscient","text":"The novel is told by an omniscient narrator who knows every character’s thoughts."},"exampleSynonym":{"word":"all-knowing","text":"The novel is told by an all-knowing narrator who knows every character’s thoughts."},"translation":{"es":"omnisciente; que todo lo sabe"}}};for(const [id,data] of Object.entries(updates)){const e=DICCIONARIOS.en.find(x=>x.id===id);if(!e)throw Error(id);Object.assign(e,data)}})();

;(()=>{const updates={"onager":{"definition":"n. An Asiatic wild ass (Equus hemionus) native to parts of Central and Western Asia; the name can also refer specifically to the Persian subspecies (Equus hemionus onager).","synonyms":["Asiatic wild ass","hemione","Equus hemionus"],"example":{"word":"onager","text":"The onager is adapted to the dry grasslands and deserts of Asia."},"exampleSynonym":{"word":"Asiatic wild ass","text":"The Asiatic wild ass is adapted to the dry grasslands and deserts of Asia."},"translation":{"es":"onagro; asno salvaje asiático"}},"eleventh":{"definition":"adj. and n. Ordinal form of eleven; occupying position 11 in a sequence.","synonyms":["11th","ordinal of eleven"],"example":{"word":"eleventh","text":"She finished in eleventh place in the race."},"exampleSynonym":{"word":"11th","text":"She finished in 11th place in the race."},"translation":{"es":"undécimo; décimo primero"}},"wavy":{"definition":"adj. 1. Having a series of curves or waves. 2. Moving or rising in waves.","synonyms":["undulating","rippled","wave-shaped"],"example":{"word":"wavy","text":"The artist drew a wavy line across the page."},"exampleSynonym":{"word":"undulating","text":"The artist drew an undulating line across the page."},"translation":{"es":"ondulado; ondeante; con ondas"}},"undulate":{"definition":"v. To move or cause something to move in a smooth, wave-like motion; to rise and fall in waves.","synonyms":["ripple","wave","swell"],"example":{"word":"undulate","text":"Tall grass began to undulate in the wind."},"exampleSynonym":{"word":"ripple","text":"Tall grass began to ripple in the wind."},"translation":{"es":"ondular; ondear"}},"ripple":{"definition":"n. and v. 1. A small wave or series of small waves on a surface. 2. To form or move in small waves; to spread through something gradually.","synonyms":["small wave","undulation","wavelet"],"example":{"word":"ripple","text":"A light breeze sent a ripple across the pond."},"exampleSynonym":{"word":"small wave","text":"A light breeze sent a small wave across the pond."},"translation":{"es":"ondulación; rizo; ondular; propagarse"}},"onerous":{"definition":"adj. Involving or imposing a great deal of effort, difficulty, or responsibility; burdensome.","synonyms":["burdensome","arduous","demanding"],"example":{"word":"onerous","text":"The contract imposed onerous reporting requirements on the small company."},"exampleSynonym":{"word":"burdensome","text":"The contract imposed burdensome reporting requirements on the small company."},"translation":{"es":"oneroso; gravoso; exigente"}},"burdensome":{"definition":"adj. Difficult to bear or deal with because it involves a heavy load, effort, or responsibility.","synonyms":["onerous","arduous","taxing"],"example":{"word":"burdensome","text":"The new paperwork became burdensome for the volunteer group."},"exampleSynonym":{"word":"onerous","text":"The new paperwork became onerous for the volunteer group."},"translation":{"es":"gravoso; oneroso; difícil de soportar"}},"onychophagia":{"definition":"n. Repetitive biting of the fingernails; nail-biting, sometimes described as a body-focused repetitive behavior.","synonyms":["nail biting","nail-biting habit"],"example":{"word":"onychophagia","text":"The clinician asked whether onychophagia worsened during periods of stress."},"exampleSynonym":{"word":"nail biting","text":"The clinician asked whether nail biting worsened during periods of stress."},"translation":{"es":"onicofagia; hábito de morderse las uñas"}},"onomatopoeia":{"definition":"n. The formation or use of a word that imitates or suggests the sound associated with what it names, such as buzz or hiss.","synonyms":["sound imitation","echoic word formation"],"example":{"word":"onomatopoeia","text":"“Hiss” is an example of onomatopoeia because it imitates a sound."},"exampleSynonym":{"word":"sound imitation","text":"“Hiss” is an example of sound imitation because it imitates a sound."},"translation":{"es":"onomatopeya"}},"onomatopoetic":{"definition":"adj. Variant of onomatopoeic: formed in imitation of a sound or relating to onomatopoeia.","synonyms":["onomatopoeic","echoic"],"example":{"word":"onomatopoetic","text":"The poem uses onomatopoetic words such as “buzz” and “clang.”"},"exampleSynonym":{"word":"onomatopoeic","text":"The poem uses onomatopoeic words such as “buzz” and “clang.”"},"translation":{"es":"onomatopéyico; imitativo de un sonido"}}};for(const [id,data] of Object.entries(updates)){const e=DICCIONARIOS.en.find(x=>x.id===id);if(!e)throw Error(id);Object.assign(e,data)}})();

;(()=>{const updates={"ontological":{"definition":"adj. Of or relating to ontology, the branch of philosophy concerned with being and what exists.","synonyms":["ontic","metaphysical (in some contexts)"],"example":{"word":"ontological","text":"The seminar examined ontological questions about what kinds of things exist."},"exampleSynonym":{"word":"ontic","text":"The seminar examined ontic questions about what kinds of things exist."},"translation":{"es":"ontológico; relativo a la ontología"}},"ontic":{"definition":"adj. Relating to or having real existence; in philosophy, concerning entities and their being.","synonyms":["real","existent","ontological (related, not always interchangeable)"],"example":{"word":"ontic","text":"The paper distinguishes ontic facts about entities from questions about being itself."},"exampleSynonym":{"word":"real","text":"The paper distinguishes real facts about entities from questions about being itself."},"translation":{"es":"óntico; relativo a lo existente"}},"oolithic":{"definition":"adj. Geol. Relating to ooliths, small rounded grains formed by concentric mineral layers.","synonyms":["oolitic","relating to ooliths"],"example":{"word":"oolithic","text":"The geologist identified an oolithic limestone made of rounded grains."},"exampleSynonym":{"word":"oolitic","text":"The geologist identified an oolitic limestone made of rounded grains."},"translation":{"es":"oolítico; relativo a los oolitos"}},"opacity":{"definition":"n. The quality or degree of being opaque: resistance to the passage of light; figuratively, lack of clarity or transparency.","synonyms":["opaqueness","nontransparency","obscurity (figurative)"],"example":{"word":"opacity","text":"The coating’s opacity prevented light from passing through the glass."},"exampleSynonym":{"word":"opaqueness","text":"The coating’s opaqueness prevented light from passing through the glass."}},"opprobrium":{"definition":"n. Formal. Harsh public criticism or disgrace resulting from shameful conduct.","synonyms":["public disgrace","infamy","condemnation","censure"],"example":{"word":"opprobrium","text":"The decision brought widespread opprobrium from the public."},"exampleSynonym":{"word":"public disgrace","text":"The decision brought widespread public disgrace."}},"optimize":{"definition":"v. To make something as effective, useful, or efficient as possible; to make the best use of available resources.","synonyms":["improve","maximize","make optimal"],"example":{"word":"optimize","text":"The team redesigned the schedule to optimize the use of its equipment."},"exampleSynonym":{"word":"maximize","text":"The team redesigned the schedule to maximize the use of its equipment."},"translation":{"es":"optimizar; hacer el mejor uso de"}},"tract":{"definition":"n. 1. An area or expanse of land or water. 2. A system of connected organs or tissues. 3. A short written work, especially on a religious or political subject.","synonyms":["stretch","expanse","region","pamphlet (sense 3)"],"example":{"word":"tract","text":"They protected a large tract of forest beside the river."},"exampleSynonym":{"word":"expanse","text":"They protected a large expanse of forest beside the river."},"translation":{"es":"extensión de terreno; tracto; folleto"}},"crazy":{"definition":"adj. 1. Informal: very enthusiastic about or preoccupied with something. 2. Informal: wildly unreasonable or unpredictable. 3. When describing mental illness, an outdated and often offensive term meaning mentally ill.","synonyms":["wild","enthusiastic (about)","unreasonable","insane (dated/offensive)"],"example":{"word":"crazy","text":"She is crazy about classical music and attends every concert."},"exampleSynonym":{"word":"enthusiastic","text":"She is enthusiastic about classical music and attends every concert."},"translation":{"es":"entusiasmado con; disparatado; loco (uso anticuado y ofensivo para enfermedad mental)"}},"tidily":{"definition":"adv. In a neat, orderly, or clean way.","synonyms":["neatly","orderly","in an organized way"],"example":{"word":"tidily","text":"He folded the maps tidily and returned them to the drawer."},"exampleSynonym":{"word":"neatly","text":"He folded the maps neatly and returned them to the drawer."}},"commonness":{"definition":"n. The quality or state of being common, ordinary, or usual; frequency or prevalence.","synonyms":["ordinariness","prevalence","frequency (in some contexts)"],"example":{"word":"commonness","text":"The commonness of the expression made it easy for learners to recognize."},"exampleSynonym":{"word":"ordinariness","text":"The ordinariness of the expression made it easy for learners to recognize."},"translation":{"es":"carácter común; frecuencia; ordinariez (según contexto)"}}};for(const [id,data] of Object.entries(updates)){const e=DICCIONARIOS.en.find(x=>x.id===id);if(!e)throw Error(id);Object.assign(e,data)}})();

