;(()=>{const u={"solstice":{"definition":"Either of the two points in the year when the Sun reaches its greatest angular distance north or south of the celestial equator; these mark the longest and shortest days of the year.","synonyms":["June solstice (one event)","December solstice (one event)","solar turning point"],"example":{"word":"solstice","text":"The summer solstice brings the longest daylight period of the year."},"exampleSynonym":{"word":"solar turning point","text":"The summer solar turning point brings the longest daylight period of the year."},"translation":{"es":"solsticio"}},"soluble":{"definition":"Capable of being dissolved, especially in a liquid; also, capable of being solved or explained, as a problem.","synonyms":["dissolvable","solvable (problem)","resolvable"],"example":{"word":"soluble","text":"Salt is soluble in water, and the puzzle proved soluble as well."},"exampleSynonym":{"word":"dissolvable","text":"Salt is dissolvable in water, and the puzzle proved solvable as well."},"translation":{"es":"soluble; que se puede disolver o resolver"}},"solute":{"definition":"A substance dissolved in a solvent to form a solution.","synonyms":["dissolved substance","solution component"],"example":{"word":"solute","text":"In salt water, salt is the solute and water is the solvent."},"exampleSynonym":{"word":"dissolved substance","text":"In salt water, salt is the dissolved substance and water is the solvent."},"translation":{"es":"soluto"}},"solve":{"definition":"To find an answer or solution to a problem, question, or puzzle; also, to explain or resolve something difficult.","synonyms":["resolve","work out","answer","figure out","decipher (code or text)"],"example":{"word":"solve","text":"The team worked together to solve the puzzle."},"exampleSynonym":{"word":"resolve","text":"The team worked together to resolve the puzzle."},"translation":{"es":"resolver; solucionar; descifrar"}},"somatize":{"definition":"To express psychological distress or processes through physical symptoms, often without an identifiable physical cause.","synonyms":["somatise (British spelling)","psychosomatize"],"example":{"word":"somatize","text":"Under prolonged stress, some people somatize anxiety as physical pain."},"exampleSynonym":{"word":"somatise","text":"Under prolonged stress, some people somatise anxiety as physical pain."},"translation":{"es":"somatizar"}},"somatise":{"definition":"British spelling of somatize: to express psychological distress through physical symptoms.","synonyms":["somatize (American spelling)","psychosomatize"],"example":{"word":"somatise","text":"The clinician explained that stress can somatise as physical symptoms."},"exampleSynonym":{"word":"somatize","text":"The clinician explained that stress can somatize as physical symptoms."},"translation":{"es":"somatizar (grafía británica)"}},"shallow":{"definition":"Having little depth; also, superficial or lacking intellectual, emotional, or serious depth.","synonyms":["not deep","superficial (ideas or understanding)","superficial-minded"],"example":{"word":"shallow","text":"The stream was shallow, and the article offered only a shallow analysis."},"exampleSynonym":{"word":"not deep","text":"The stream was not deep, and the article offered little analysis."},"translation":{"es":"poco profundo; superficial; frívolo"}},"cursory":{"definition":"Done quickly and without careful attention or thoroughness.","synonyms":["hasty","superficial","perfunctory (sometimes)"],"example":{"word":"cursory","text":"A cursory inspection missed the crack in the support."},"exampleSynonym":{"word":"hasty","text":"A hasty inspection missed the crack in the support."},"translation":{"es":"somero; superficial; apresurado"}},"superficial":{"definition":"Existing at or relating to the surface; also, lacking depth of thought, feeling, or understanding.","synonyms":["surface-level","shallow (figurative)","cursory (review or examination)"],"example":{"word":"superficial","text":"The damage looked superficial, but the report gave only a superficial analysis."},"exampleSynonym":{"word":"surface-level","text":"The damage looked surface-level, but the report gave only a surface-level analysis."},"translation":{"es":"superficial; de superficie"}},"perfunctory":{"definition":"Done routinely or with only the minimum effort, interest, or care needed to fulfill a duty.","synonyms":["mechanical","routine","half-hearted","cursory (by context)"],"example":{"word":"perfunctory","text":"He offered a perfunctory apology without showing concern."},"exampleSynonym":{"word":"mechanical","text":"He offered a mechanical apology without showing concern."},"translation":{"es":"rutinario; hecho por cumplir; mecánico"}}};for(const[id,v]of Object.entries(u)){const e=DICCIONARIOS.en.find(x=>x.id===id);if(!e)throw Error('missing '+id);Object.assign(e,v)}})();

