(()=>{const row=DICCIONARIOS.en.find(e=>e.id==="autolatry");if(!row)throw Error('Missing en/autolatry');Object.assign(row,{word:'Autolatry',definition:'Excessive worship or admiration of oneself; self-idolatry.',synonyms:['self-worship','egotism'],example:{word:'autolatry',text:'His autolatry made it difficult for him to recognize other people’s merits.'},exampleSynonym:{word:'self-worship',text:'His self-worship made it difficult for him to recognize other people’s merits.'}});})();
